/**
 * Core Command Service
 * Handles fundamental system commands like help, version, and exit
 */

import { BaseCommandService } from '../../shared/BaseCommandService';
import { CommandCategory } from '../../types';
import { HelpCommand } from './handlers/HelpCommand';
import { VersionCommand } from './handlers/VersionCommand';
import { ExitCommand } from './handlers/ExitCommand';
import { logger } from '../../../utils/logger';

export class CoreCommandService extends BaseCommandService {
  readonly category: CommandCategory = 'core';

  /**
   * Register all core command handlers
   */
  registerHandlers(): void {
    logger.debug('Registering core command handlers');

    // Register core commands
    this.handlers.set('/help', new HelpCommand());
    this.handlers.set('/version', new VersionCommand()); 
    this.handlers.set('/exit', new ExitCommand());

    // Register aliases for convenience
    this.handlers.set('/h', this.handlers.get('/help')!);
    this.handlers.set('/?', this.handlers.get('/help')!);
    this.handlers.set('/v', this.handlers.get('/version')!);
    this.handlers.set('/ver', this.handlers.get('/version')!);
    this.handlers.set('/info', this.handlers.get('/version')!);
    this.handlers.set('/quit', this.handlers.get('/exit')!);
    this.handlers.set('/q', this.handlers.get('/exit')!);
    this.handlers.set('/bye', this.handlers.get('/exit')!);

    logger.info(`Core command service registered ${this.handlers.size} commands/aliases`);
  }

  /**
   * Initialize core command service
   */
  override async initialize(): Promise<void> {
    logger.info('Initializing CoreCommandService');

    // Call parent initialization
    await super.initialize();

    // Perform any core-specific initialization
    await this.initializeCoreComponents();

    logger.info('CoreCommandService initialization complete');
  }

  /**
   * Initialize core-specific components
   */
  private async initializeCoreComponents(): Promise<void> {
    try {
      // Any core-specific initialization logic would go here
      // For example: loading system information, checking permissions, etc.
      
      logger.debug('Core components initialized successfully');
    } catch (error) {
      logger.error('Failed to initialize core components:', error);
      throw error;
    }
  }

  /**
   * Get core service statistics
   */
  getCoreStats() {
    const stats = this.getServiceInfo();
    
    return {
      ...stats,
      aliases: {
        help: ['/h', '/?'],
        version: ['/v', '/ver', '/info'],
        exit: ['/quit', '/q', '/bye'],
      },
      description: 'Fundamental system commands for help, versioning, and application control',
    };
  }

  /**
   * Check if all core commands are functional
   */
  async healthCheck(): Promise<boolean> {
    try {
      const essentialCommands = ['/help', '/version', '/exit'];
      
      for (const command of essentialCommands) {
        if (!this.hasCommand(command)) {
          logger.error(`Essential command missing: ${command}`);
          return false;
        }
      }

      logger.info('Core command service health check passed');
      return true;
    } catch (error) {
      logger.error('Core command service health check failed:', error);
      return false;
    }
  }
}