/**
 * Headless Browser Engine
 * Manages headless browser instances for web scraping and content extraction
 */

import { logger } from '../../../../utils/logger';

export interface BrowserOptions {
  headless: boolean;
  timeout: number;
  userAgent?: string;
  viewport?: {
    width: number;
    height: number;
  };
  waitFor?: 'load' | 'domcontentloaded' | 'networkidle0' | 'networkidle2';
  javascript: boolean;
  cookies?: Array<{
    name: string;
    value: string;
    domain?: string;
  }>;
}

export interface ScrapingResult {
  url: string;
  html: string;
  title: string;
  status: number;
  headers: Record<string, string>;
  screenshots?: Buffer[];
  loadTime: number;
  error?: string;
}

export interface NavigationOptions extends BrowserOptions {
  retries?: number;
  retryDelay?: number;
  blockResources?: string[]; // 'image', 'stylesheet', 'font', 'media'
}

export class HeadlessBrowser {
  private browser: any = null;
  private page: any = null;
  private isInitialized = false;

  constructor(private options: BrowserOptions = {
    headless: true,
    timeout: 30000,
    javascript: true,
    waitFor: 'domcontentloaded',
    viewport: { width: 1920, height: 1080 }
  }) {}

  /**
   * Initialize the browser instance
   */
  async initialize(): Promise<void> {
    if (this.isInitialized) {
      return;
    }

    try {
      // Try to use puppeteer if available
      const puppeteer = this.requirePuppeteer();
      
      if (puppeteer) {
        await this.initializePuppeteer(puppeteer);
      } else {
        logger.warn('Puppeteer not available, falling back to native fetch');
      }

      this.isInitialized = true;
      logger.debug('Headless browser initialized');
    } catch (error) {
      logger.error('Failed to initialize headless browser:', error);
      throw new Error(`Browser initialization failed: ${error instanceof Error ? error.message : 'Unknown error'}`);
    }
  }

  /**
   * Try to require puppeteer (optional dependency)
   */
  private requirePuppeteer(): any {
    try {
      return require('puppeteer');
    } catch (error) {
      logger.debug('Puppeteer not available:', error instanceof Error ? error.message : 'Unknown error');
      return null;
    }
  }

  /**
   * Initialize Puppeteer browser
   */
  private async initializePuppeteer(puppeteer: any): Promise<void> {
    const launchOptions = {
      headless: this.options.headless ? 'new' : false,
      args: [
        '--no-sandbox',
        '--disable-setuid-sandbox',
        '--disable-dev-shm-usage',
        '--disable-gpu',
        '--disable-web-security',
        '--allow-running-insecure-content',
        '--disable-features=VizDisplayCompositor',
      ],
      timeout: this.options.timeout,
    };

    // Add user agent if specified
    if (this.options.userAgent) {
      launchOptions.args.push(`--user-agent=${this.options.userAgent}`);
    }

    this.browser = await puppeteer.launch(launchOptions);
    this.page = await this.browser.newPage();

    // Set viewport
    if (this.options.viewport) {
      await this.page.setViewport(this.options.viewport);
    }

    // Set user agent
    if (this.options.userAgent) {
      await this.page.setUserAgent(this.options.userAgent);
    }

    // Set cookies if provided
    if (this.options.cookies && this.options.cookies.length > 0) {
      await this.page.setCookie(...this.options.cookies);
    }

    logger.debug('Puppeteer browser launched successfully');
  }

  /**
   * Navigate to URL and extract content
   */
  async scrape(url: string, options: Partial<NavigationOptions> = {}): Promise<ScrapingResult> {
    const startTime = Date.now();
    const mergedOptions = { ...this.options, ...options };

    try {
      // Validate URL
      if (!this.isValidUrl(url)) {
        throw new Error(`Invalid URL: ${url}`);
      }

      // Initialize browser if not already done
      if (!this.isInitialized) {
        await this.initialize();
      }

      let result: ScrapingResult;

      if (this.browser && this.page) {
        // Use Puppeteer for dynamic content
        result = await this.scrapeWithPuppeteer(url, mergedOptions);
      } else {
        // Fallback to native fetch for static content
        result = await this.scrapeWithFetch(url, mergedOptions);
      }

      result.loadTime = Date.now() - startTime;
      logger.info(`Successfully scraped ${url} in ${result.loadTime}ms`);

      return result;

    } catch (error) {
      const loadTime = Date.now() - startTime;
      const errorMessage = error instanceof Error ? error.message : 'Unknown error';
      
      logger.error(`Failed to scrape ${url}: ${errorMessage}`);

      return {
        url,
        html: '',
        title: '',
        status: 0,
        headers: {},
        loadTime,
        error: errorMessage,
      };
    }
  }

  /**
   * Scrape using Puppeteer (for dynamic content)
   */
  private async scrapeWithPuppeteer(url: string, options: NavigationOptions): Promise<ScrapingResult> {
    try {
      // Block unnecessary resources if specified
      if (options.blockResources && options.blockResources.length > 0) {
        await this.page.setRequestInterception(true);
        this.page.on('request', (req: any) => {
          const resourceType = req.resourceType();
          if (options.blockResources!.includes(resourceType)) {
            req.abort();
          } else {
            req.continue();
          }
        });
      }

      // Navigate to the page
      const response = await this.page.goto(url, {
        waitUntil: options.waitFor || 'domcontentloaded',
        timeout: options.timeout || 30000,
      });

      // Wait for JavaScript to execute if enabled
      if (options.javascript) {
        await this.page.waitForTimeout(1000); // Give JS some time to execute
        
        // Wait for any additional selectors or conditions if needed
        try {
          await this.page.waitForSelector('body', { timeout: 5000 });
        } catch (error) {
          logger.warn('Body selector not found, continuing anyway');
        }
      }

      // Extract content
      const html = await this.page.content();
      const title = await this.page.title();
      const status = response?.status() || 200;
      const headers = response?.headers() || {};

      // Take screenshot if needed (optional feature)
      let screenshots: Buffer[] | undefined;
      try {
        const screenshot = await this.page.screenshot({
          type: 'png',
          fullPage: false,
        });
        screenshots = [screenshot];
      } catch (error) {
        logger.debug('Screenshot capture failed:', error);
      }

      return {
        url,
        html,
        title,
        status,
        headers,
        screenshots,
        loadTime: 0, // Will be set by caller
      };

    } catch (error) {
      logger.error('Puppeteer scraping failed:', error);
      throw error;
    }
  }

  /**
   * Scrape using native fetch (for static content)
   */
  private async scrapeWithFetch(url: string, options: NavigationOptions): Promise<ScrapingResult> {
    const https = require('https');
    const http = require('http');
    const { URL } = require('url');

    return new Promise((resolve, reject) => {
      try {
        const parsedUrl = new URL(url);
        const client = parsedUrl.protocol === 'https:' ? https : http;

        const requestOptions = {
          hostname: parsedUrl.hostname,
          port: parsedUrl.port,
          path: parsedUrl.pathname + parsedUrl.search,
          method: 'GET',
          headers: {
            'User-Agent': options.userAgent || 'Mozilla/5.0 (compatible; MARIA-Research/2.0)',
            'Accept': 'text/html,application/xhtml+xml,application/xml;q=0.9,*/*;q=0.8',
            'Accept-Language': 'en-US,en;q=0.5',
            'Accept-Encoding': 'gzip, deflate',
            'Connection': 'keep-alive',
          },
          timeout: options.timeout || 30000,
        };

        const req = client.request(requestOptions, (res: any) => {
          let data = '';
          
          res.on('data', (chunk: any) => {
            data += chunk;
          });

          res.on('end', () => {
            // Extract title from HTML
            const titleMatch = data.match(/<title[^>]*>([^<]+)<\/title>/i);
            const title = titleMatch ? titleMatch[1].trim() : '';

            resolve({
              url,
              html: data,
              title,
              status: res.statusCode || 200,
              headers: res.headers || {},
              loadTime: 0, // Will be set by caller
            });
          });
        });

        req.on('error', (error: Error) => {
          reject(error);
        });

        req.on('timeout', () => {
          req.destroy();
          reject(new Error('Request timeout'));
        });

        req.end();

      } catch (error) {
        reject(error);
      }
    });
  }

  /**
   * Batch scrape multiple URLs
   */
  async scrapeMultiple(
    urls: string[],
    options: Partial<NavigationOptions> = {},
    concurrency: number = 3
  ): Promise<ScrapingResult[]> {
    const results: ScrapingResult[] = [];
    const batches: string[][] = [];

    // Split URLs into batches
    for (let i = 0; i < urls.length; i += concurrency) {
      batches.push(urls.slice(i, i + concurrency));
    }

    logger.info(`Scraping ${urls.length} URLs in ${batches.length} batches (concurrency: ${concurrency})`);

    // Process batches sequentially, URLs within batch concurrently
    for (const batch of batches) {
      const batchPromises = batch.map(url => this.scrape(url, options));
      const batchResults = await Promise.allSettled(batchPromises);

      batchResults.forEach((result, index) => {
        if (result.status === 'fulfilled') {
          results.push(result.value);
        } else {
          logger.error(`Failed to scrape ${batch[index]}:`, result.reason);
          results.push({
            url: batch[index],
            html: '',
            title: '',
            status: 0,
            headers: {},
            loadTime: 0,
            error: result.reason instanceof Error ? result.reason.message : 'Unknown error',
          });
        }
      });

      // Small delay between batches to be respectful
      if (batches.indexOf(batch) < batches.length - 1) {
        await new Promise(resolve => setTimeout(resolve, 1000));
      }
    }

    return results;
  }

  /**
   * Extract links from a page
   */
  async extractLinks(url: string, options: Partial<NavigationOptions> = {}): Promise<string[]> {
    try {
      const result = await this.scrape(url, options);
      
      if (!result.html) {
        return [];
      }

      // Use cheerio if available, otherwise regex
      try {
        const cheerio = require('cheerio');
        const $ = cheerio.load(result.html);
        
        const links: string[] = [];
        $('a[href]').each((_: number, element: any) => {
          const href = $(element).attr('href');
          if (href) {
            const absoluteUrl = this.resolveUrl(href, url);
            if (absoluteUrl) {
              links.push(absoluteUrl);
            }
          }
        });
        
        return [...new Set(links)]; // Remove duplicates

      } catch (cheerioError) {
        // Fallback to regex
        logger.debug('Cheerio not available, using regex fallback');
        const linkRegex = /<a[^>]+href=["']([^"']+)["'][^>]*>/gi;
        const links: string[] = [];
        let match;

        while ((match = linkRegex.exec(result.html)) !== null) {
          const href = match[1];
          const absoluteUrl = this.resolveUrl(href, url);
          if (absoluteUrl) {
            links.push(absoluteUrl);
          }
        }

        return [...new Set(links)];
      }

    } catch (error) {
      logger.error(`Failed to extract links from ${url}:`, error);
      return [];
    }
  }

  /**
   * Validate URL format
   */
  private isValidUrl(url: string): boolean {
    try {
      new URL(url);
      return url.startsWith('http://') || url.startsWith('https://');
    } catch {
      return false;
    }
  }

  /**
   * Resolve relative URLs to absolute
   */
  private resolveUrl(href: string, baseUrl: string): string | null {
    try {
      const { URL } = require('url');
      const resolved = new URL(href, baseUrl);
      return resolved.href;
    } catch {
      return null;
    }
  }

  /**
   * Close browser and cleanup
   */
  async close(): Promise<void> {
    try {
      if (this.page) {
        await this.page.close();
        this.page = null;
      }

      if (this.browser) {
        await this.browser.close();
        this.browser = null;
      }

      this.isInitialized = false;
      logger.debug('Headless browser closed');
    } catch (error) {
      logger.error('Error closing headless browser:', error);
    }
  }

  /**
   * Check if browser is ready
   */
  isReady(): boolean {
    return this.isInitialized && (this.browser !== null || true); // Allow fallback mode
  }

  /**
   * Get browser info
   */
  async getBrowserInfo(): Promise<{
    engine: string;
    version?: string;
    headless: boolean;
    ready: boolean;
  }> {
    if (this.browser) {
      try {
        const version = await this.browser.version();
        return {
          engine: 'puppeteer',
          version,
          headless: this.options.headless,
          ready: this.isReady(),
        };
      } catch {
        return {
          engine: 'puppeteer',
          headless: this.options.headless,
          ready: this.isReady(),
        };
      }
    } else {
      return {
        engine: 'native-fetch',
        headless: true,
        ready: this.isReady(),
      };
    }
  }
}