/**
 * FileDropHandler Component
 * Handles file drag & drop detection and processing
 */

import { EventEmitter } from 'events';
import * as fs from 'fs';
import * as path from 'path';
import chalk from 'chalk';

/**
 * File drop event data
 */
export interface FileDropEvent {
  type: 'file' | 'directory' | 'url' | 'image';
  path: string;
  name: string;
  size?: number;
  mimeType?: string;
  content?: string;
  isImage?: boolean;
}

/**
 * File drop handler configuration
 */
export interface FileDropHandlerConfig {
  maxFileSize?: number; // Max file size in bytes
  allowedExtensions?: string[];
  autoReadContent?: boolean;
  enableUrlDetection?: boolean;
}

/**
 * File drop handler class
 */
export class FileDropHandler extends EventEmitter {
  private config: Required<FileDropHandlerConfig>;
  private droppedFiles: FileDropEvent[] = [];
  
  constructor(config: FileDropHandlerConfig = {}) {
    super();
    this.config = {
      maxFileSize: config.maxFileSize || 10 * 1024 * 1024, // 10MB default
      allowedExtensions: config.allowedExtensions || [],
      autoReadContent: config.autoReadContent || false,
      enableUrlDetection: config.enableUrlDetection ?? true,
    };
  }

  /**
   * Process dropped or pasted input
   */
  async processInput(input: string): Promise<FileDropEvent[]> {
    const results: FileDropEvent[] = [];
    
    // Check if input is a URL
    if (this.config.enableUrlDetection && this.isUrl(input)) {
      const urlEvent = this.createUrlEvent(input);
      results.push(urlEvent);
      this.emit('url', urlEvent);
      return results;
    }
    
    // Check if input contains file paths
    const paths = this.extractFilePaths(input);
    
    for (const filePath of paths) {
      try {
        const event = await this.processFilePath(filePath);
        if (event) {
          results.push(event);
          this.droppedFiles.push(event);
          this.emit('file', event);
        }
      } catch (error) {
        this.emit('error', {
          path: filePath,
          error: error instanceof Error ? error.message : 'Unknown error',
        });
      }
    }
    
    return results;
  }

  /**
   * Process a file path
   */
  private async processFilePath(filePath: string): Promise<FileDropEvent | null> {
    // Expand home directory
    if (filePath.startsWith('~')) {
      filePath = path.join(process.env['HOME'] || '', filePath.slice(1));
    }
    
    // Resolve absolute path
    const absolutePath = path.resolve(filePath);
    
    // Check if file exists
    if (!fs.existsSync(absolutePath)) {
      return null;
    }
    
    const stats = fs.statSync(absolutePath);
    
    // Check if it's a directory
    if (stats.isDirectory()) {
      return {
        type: 'directory',
        path: absolutePath,
        name: path.basename(absolutePath),
      };
    }
    
    // Check file size
    if (stats.size > this.config.maxFileSize) {
      throw new Error(`File too large: ${this.formatFileSize(stats.size)} (max: ${this.formatFileSize(this.config.maxFileSize)})`);
    }
    
    // Check extension if restrictions are set
    const ext = path.extname(absolutePath).toLowerCase();
    if (this.config.allowedExtensions.length > 0 && !this.config.allowedExtensions.includes(ext)) {
      throw new Error(`File type not allowed: ${ext}`);
    }
    
    // Determine if it's an image
    const isImage = this.isImageFile(absolutePath);
    
    // Create file event
    const event: FileDropEvent = {
      type: isImage ? 'image' : 'file',
      path: absolutePath,
      name: path.basename(absolutePath),
      size: stats.size,
      mimeType: this.getMimeType(absolutePath),
      isImage,
    };
    
    // Auto-read content if enabled and not too large
    if (this.config.autoReadContent && stats.size < 1024 * 1024) { // 1MB limit for auto-read
      try {
        event.content = fs.readFileSync(absolutePath, 'utf-8');
      } catch {
        // If can't read as text, skip content
      }
    }
    
    return event;
  }

  /**
   * Check if string is a URL
   */
  private isUrl(str: string): boolean {
    try {
      const url = new URL(str);
      return url.protocol === 'http:' || url.protocol === 'https:';
    } catch {
      return false;
    }
  }

  /**
   * Create URL event
   */
  private createUrlEvent(url: string): FileDropEvent {
    return {
      type: 'url',
      path: url,
      name: url,
    };
  }

  /**
   * Extract file paths from input text
   */
  private extractFilePaths(input: string): string[] {
    const paths: string[] = [];
    
    // Match file paths (Unix/Windows)
    const pathPattern = /(?:^|\s)([~\/]?[\w\-./\\:]+(?:\.\w+)?)/g;
    const matches = input.matchAll(pathPattern);
    
    for (const match of matches) {
      const potentialPath = match[1];
      if (potentialPath) {
        // Basic validation - must have at least one separator
        if (potentialPath.includes('/') || potentialPath.includes('\\')) {
          paths.push(potentialPath);
        }
      }
    }
    
    // Also check for quoted paths
    const quotedPattern = /["']([^"']+)["']/g;
    const quotedMatches = input.matchAll(quotedPattern);
    
    for (const match of quotedMatches) {
      const potentialPath = match[1];
      if (potentialPath) {
        if (potentialPath.includes('/') || potentialPath.includes('\\')) {
          paths.push(potentialPath);
        }
      }
    }
    
    return [...new Set(paths)]; // Remove duplicates
  }

  /**
   * Check if file is an image
   */
  private isImageFile(filePath: string): boolean {
    const ext = path.extname(filePath).toLowerCase();
    const imageExtensions = ['.png', '.jpg', '.jpeg', '.gif', '.bmp', '.svg', '.webp', '.ico'];
    return imageExtensions.includes(ext);
  }

  /**
   * Get MIME type from file extension
   */
  private getMimeType(filePath: string): string {
    const ext = path.extname(filePath).toLowerCase();
    const mimeTypes: Record<string, string> = {
      '.txt': 'text/plain',
      '.html': 'text/html',
      '.css': 'text/css',
      '.js': 'application/javascript',
      '.ts': 'application/typescript',
      '.json': 'application/json',
      '.png': 'image/png',
      '.jpg': 'image/jpeg',
      '.jpeg': 'image/jpeg',
      '.gif': 'image/gif',
      '.svg': 'image/svg+xml',
      '.pdf': 'application/pdf',
      '.md': 'text/markdown',
    };
    
    return mimeTypes[ext] || 'application/octet-stream';
  }

  /**
   * Format file size for display
   */
  private formatFileSize(bytes: number): string {
    const units = ['B', 'KB', 'MB', 'GB'];
    let size = bytes;
    let unitIndex = 0;
    
    while (size >= 1024 && unitIndex < units.length - 1) {
      size /= 1024;
      unitIndex++;
    }
    
    return `${size.toFixed(2)} ${units[unitIndex]}`;
  }

  /**
   * Get all dropped files
   */
  getDroppedFiles(): FileDropEvent[] {
    return [...this.droppedFiles];
  }

  /**
   * Clear dropped files history
   */
  clearDroppedFiles(): void {
    this.droppedFiles = [];
  }

  /**
   * Display dropped files summary
   */
  displaySummary(): void {
    if (this.droppedFiles.length === 0) {
      console.log(chalk.gray('No files attached'));
      return;
    }
    
    console.log(chalk.cyan('\n📎 Attached References:'));
    for (const file of this.droppedFiles) {
      const icon = file.isImage ? '🖼️' : file.type === 'directory' ? '📁' : file.type === 'url' ? '🔗' : '📄';
      const sizeStr = file.size ? chalk.gray(` (${this.formatFileSize(file.size)})`) : '';
      console.log(`  ${icon} ${chalk.white(file.name)}${sizeStr}`);
    }
  }
}

export default FileDropHandler;