import * as fs from 'fs';
import * as path from 'path';
import * as os from 'os';
import chalk from 'chalk';

interface CodeSnippet {
  id: string;
  name: string;
  description: string;
  language: string;
  code: string;
  tags: string[];
  category: string;
  author: string;
  createdAt: Date;
  lastUsed: Date;
  useCount: number;
  isFavorite: boolean;
}

export class SnippetHandler {
  private snippetsPath: string;
  private snippets: Map<string, CodeSnippet>;

  constructor() {
    this.snippetsPath = path.join(os.homedir(), '.maria', 'snippets.json');
    this.snippets = new Map();
    this.loadSnippets();
  }

  async execute(args: string[]): Promise<string> {
    const command = args[0];
    const restArgs = args.slice(1);
    
    if (!command || command === '--help') {
      return this.showHelp();
    }

    switch (command) {
      case 'save':
        return this.saveSnippet(restArgs);
      case 'load':
        return this.loadSnippet(restArgs);
      case 'list':
        return this.listSnippets(restArgs);
      case 'search':
        return this.searchSnippets(restArgs);
      case 'delete':
        return this.deleteSnippet(restArgs);
      case 'export':
        return this.exportSnippets(restArgs);
      case 'import':
        return this.importSnippets(restArgs);
      case 'favorite':
        return this.toggleFavorite(restArgs);
      case 'tag':
        return this.tagSnippet(restArgs);
      case 'category':
        return this.categorizeSnippet(restArgs);
      default:
        return this.showHelp();
    }
  }

  private showHelp(): string {
    return `
${chalk.cyan('📝 Code Snippet Management')}

${chalk.yellow('Usage:')}
  /snippet save <name> [code]       Save code as snippet
  /snippet load <name>              Load snippet
  /snippet list [options]           List all snippets
  /snippet search <keyword>         Search snippets
  /snippet delete <name>            Delete snippet
  /snippet export <file>            Export snippets
  /snippet import <file>            Import snippets
  /snippet favorite <name>          Toggle favorite
  /snippet tag <name> <tags>        Add tags to snippet
  /snippet category <name> <cat>    Set category

${chalk.yellow('Options:')}
  --tags <tags>     Filter by tags
  --category <cat>  Filter by category
  --language <lang> Filter by language
  --favorites       Show only favorites

${chalk.yellow('Examples:')}
  /snippet save "quicksort" "function quicksort(arr) {...}"
  /snippet search authentication
  /snippet list --tags=react,hooks
  /snippet export ./my-snippets.json
  /snippet tag "quicksort" algorithm,sorting
  /snippet category "react-hook" frontend

${chalk.gray('Snippets are stored locally in ~/.maria/snippets.json')}
    `.trim();
  }

  private saveSnippet(args: string[]): string {
    const name = args[0];
    if (!name) {
      return chalk.red('❌ Please provide a snippet name');
    }

    // Parse code and options
    let code = '';
    let tags: string[] = [];
    let category = 'general';
    let language = 'javascript';
    let description = '';

    // Simple parsing - in real implementation would be more robust
    for (let i = 1; i < args.length; i++) {
      const arg = args[i];
      if (arg.startsWith('--tags=')) {
        tags = arg.replace('--tags=', '').split(',');
      } else if (arg.startsWith('--category=')) {
        category = arg.replace('--category=', '');
      } else if (arg.startsWith('--language=')) {
        language = arg.replace('--language=', '');
      } else if (arg.startsWith('--description=')) {
        description = arg.replace('--description=', '');
      } else {
        code += (code ? ' ' : '') + arg;
      }
    }

    if (!code) {
      code = this.generateSampleCode(name);
    }

    const snippet: CodeSnippet = {
      id: this.generateId(),
      name,
      description: description || `Code snippet: ${name}`,
      language: this.detectLanguage(code, language),
      code,
      tags,
      category,
      author: os.userInfo().username,
      createdAt: new Date(),
      lastUsed: new Date(),
      useCount: 0,
      isFavorite: false,
    };

    this.snippets.set(name, snippet);
    this.saveSnippets();

    return `
${chalk.green('✅ Snippet Saved Successfully!')}

${chalk.cyan('📋 Snippet Details:')}
  • Name: ${name}
  • Language: ${snippet.language}
  • Category: ${category}
  • Tags: ${tags.length > 0 ? tags.join(', ') : 'none'}
  • Size: ${code.length} characters

${chalk.yellow('💡 Usage:')}
  • Load: /snippet load "${name}"
  • Search: /snippet search "${name}"
  • Add tags: /snippet tag "${name}" <tags>

${chalk.gray(`Saved to: ${this.snippetsPath}`)}
    `.trim();
  }

  private loadSnippet(args: string[]): string {
    const name = args[0];
    if (!name) {
      return chalk.red('❌ Please provide a snippet name');
    }

    const snippet = this.snippets.get(name);
    if (!snippet) {
      return chalk.red(`❌ Snippet "${name}" not found. Use /snippet list to see available snippets.`);
    }

    // Update usage stats
    snippet.lastUsed = new Date();
    snippet.useCount++;
    this.saveSnippets();

    return `
${chalk.green(`✅ Loaded Snippet: ${name}`)}

${chalk.cyan('📋 Details:')}
  • Language: ${snippet.language}
  • Category: ${snippet.category}
  • Tags: ${snippet.tags.join(', ') || 'none'}
  • Used: ${snippet.useCount} times
  • Author: ${snippet.author}

${chalk.yellow('📝 Code:')}
\`\`\`${snippet.language}
${snippet.code}
\`\`\`

${chalk.gray(`Last used: ${snippet.lastUsed.toLocaleString()}`)}
    `.trim();
  }

  private listSnippets(args: string[]): string {
    let filteredSnippets = Array.from(this.snippets.values());

    // Apply filters
    for (const arg of args) {
      if (arg.startsWith('--tags=')) {
        const tags = arg.replace('--tags=', '').split(',');
        filteredSnippets = filteredSnippets.filter(s => 
          tags.some(tag => s.tags.includes(tag))
        );
      } else if (arg.startsWith('--category=')) {
        const category = arg.replace('--category=', '');
        filteredSnippets = filteredSnippets.filter(s => s.category === category);
      } else if (arg.startsWith('--language=')) {
        const language = arg.replace('--language=', '');
        filteredSnippets = filteredSnippets.filter(s => s.language === language);
      } else if (arg === '--favorites') {
        filteredSnippets = filteredSnippets.filter(s => s.isFavorite);
      }
    }

    if (filteredSnippets.length === 0) {
      return chalk.yellow('📭 No snippets found matching your criteria.');
    }

    const snippetList = filteredSnippets
      .sort((a, b) => b.lastUsed.getTime() - a.lastUsed.getTime())
      .map(s => {
        const star = s.isFavorite ? '⭐ ' : '   ';
        const tags = s.tags.length > 0 ? chalk.gray(` [${s.tags.join(', ')}]`) : '';
        return `${star}${chalk.cyan(s.name)} - ${s.language} - ${s.category}${tags}`;
      })
      .join('\n');

    return `
${chalk.green('📚 Code Snippets Library')}

${chalk.yellow(`Found ${filteredSnippets.length} snippet(s):`)}

${snippetList}

${chalk.gray('💡 Use /snippet load <name> to view a snippet')}
${chalk.gray('⭐ = Favorite snippet')}
    `.trim();
  }

  private searchSnippets(args: string[]): string {
    const keyword = args.join(' ').toLowerCase();
    if (!keyword) {
      return chalk.red('❌ Please provide a search keyword');
    }

    const results = Array.from(this.snippets.values()).filter(s => 
      s.name.toLowerCase().includes(keyword) ||
      s.description.toLowerCase().includes(keyword) ||
      s.code.toLowerCase().includes(keyword) ||
      s.tags.some(tag => tag.toLowerCase().includes(keyword)) ||
      s.category.toLowerCase().includes(keyword)
    );

    if (results.length === 0) {
      return chalk.yellow(`📭 No snippets found matching "${keyword}"`);
    }

    const resultList = results
      .map(s => {
        const star = s.isFavorite ? '⭐ ' : '   ';
        const preview = s.code.substring(0, 50).replace(/\n/g, ' ');
        return `${star}${chalk.cyan(s.name)} - ${chalk.gray(preview + '...')}`;
      })
      .join('\n');

    return `
${chalk.green(`🔍 Search Results for "${keyword}":`)}

${chalk.yellow(`Found ${results.length} matching snippet(s):`)}

${resultList}

${chalk.gray('💡 Use /snippet load <name> to view full snippet')}
    `.trim();
  }

  private deleteSnippet(args: string[]): string {
    const name = args[0];
    if (!name) {
      return chalk.red('❌ Please provide a snippet name to delete');
    }

    if (!this.snippets.has(name)) {
      return chalk.red(`❌ Snippet "${name}" not found`);
    }

    this.snippets.delete(name);
    this.saveSnippets();

    return chalk.green(`✅ Snippet "${name}" deleted successfully`);
  }

  private exportSnippets(args: string[]): string {
    const filePath = args[0] || './snippets-export.json';
    
    try {
      const exportData = {
        version: '1.0.0',
        exportDate: new Date().toISOString(),
        snippets: Array.from(this.snippets.values()),
      };
      
      fs.writeFileSync(filePath, JSON.stringify(exportData, null, 2));
      
      return `
${chalk.green('✅ Snippets Exported Successfully!')}

${chalk.cyan('📋 Export Details:')}
  • File: ${filePath}
  • Snippets: ${this.snippets.size}
  • Format: JSON
  • Date: ${new Date().toLocaleString()}

${chalk.gray('Share this file with your team or import on another machine')}
      `.trim();
    } catch (error: any) {
      return chalk.red(`❌ Export failed: ${error.message}`);
    }
  }

  private importSnippets(args: string[]): string {
    const filePath = args[0];
    if (!filePath) {
      return chalk.red('❌ Please provide a file path to import');
    }

    try {
      const data = JSON.parse(fs.readFileSync(filePath, 'utf-8'));
      let imported = 0;
      
      if (data.snippets && Array.isArray(data.snippets)) {
        for (const snippet of data.snippets) {
          if (snippet.name) {
            this.snippets.set(snippet.name, {
              ...snippet,
              createdAt: new Date(snippet.createdAt),
              lastUsed: new Date(snippet.lastUsed),
            });
            imported++;
          }
        }
        
        this.saveSnippets();
      }
      
      return chalk.green(`✅ Imported ${imported} snippet(s) successfully!`);
    } catch (error: any) {
      return chalk.red(`❌ Import failed: ${error.message}`);
    }
  }

  private toggleFavorite(args: string[]): string {
    const name = args[0];
    if (!name) {
      return chalk.red('❌ Please provide a snippet name');
    }

    const snippet = this.snippets.get(name);
    if (!snippet) {
      return chalk.red(`❌ Snippet "${name}" not found`);
    }

    snippet.isFavorite = !snippet.isFavorite;
    this.saveSnippets();

    const status = snippet.isFavorite ? 'added to' : 'removed from';
    return chalk.green(`✅ Snippet "${name}" ${status} favorites`);
  }

  private tagSnippet(args: string[]): string {
    const name = args[0];
    const tags = args.slice(1).join(',').split(',').filter(t => t.trim());

    if (!name) {
      return chalk.red('❌ Please provide a snippet name');
    }

    const snippet = this.snippets.get(name);
    if (!snippet) {
      return chalk.red(`❌ Snippet "${name}" not found`);
    }

    snippet.tags = [...new Set([...snippet.tags, ...tags])];
    this.saveSnippets();

    return chalk.green(`✅ Tags added to "${name}": ${tags.join(', ')}`);
  }

  private categorizeSnippet(args: string[]): string {
    const name = args[0];
    const category = args[1];

    if (!name || !category) {
      return chalk.red('❌ Please provide snippet name and category');
    }

    const snippet = this.snippets.get(name);
    if (!snippet) {
      return chalk.red(`❌ Snippet "${name}" not found`);
    }

    snippet.category = category;
    this.saveSnippets();

    return chalk.green(`✅ Snippet "${name}" moved to category: ${category}`);
  }

  // Helper methods

  private loadSnippets(): void {
    try {
      if (fs.existsSync(this.snippetsPath)) {
        const data = JSON.parse(fs.readFileSync(this.snippetsPath, 'utf-8'));
        for (const [name, snippet] of Object.entries(data)) {
          this.snippets.set(name, {
            ...(snippet as any),
            createdAt: new Date((snippet as any).createdAt),
            lastUsed: new Date((snippet as any).lastUsed),
          });
        }
      }
    } catch (error) {
      // Initialize with empty snippets if load fails
      this.snippets = new Map();
    }
  }

  private saveSnippets(): void {
    try {
      const dir = path.dirname(this.snippetsPath);
      if (!fs.existsSync(dir)) {
        fs.mkdirSync(dir, { recursive: true });
      }
      
      const data: Record<string, CodeSnippet> = {};
      for (const [name, snippet] of this.snippets.entries()) {
        data[name] = snippet;
      }
      
      fs.writeFileSync(this.snippetsPath, JSON.stringify(data, null, 2));
    } catch (error: any) {
      console.error(chalk.red(`Failed to save snippets: ${error.message}`));
    }
  }

  private generateId(): string {
    return Date.now().toString(36) + Math.random().toString(36).substr(2);
  }

  private detectLanguage(code: string, defaultLang: string = 'javascript'): string {
    // Simple language detection based on patterns
    if (code.includes('function') || code.includes('=>') || code.includes('const ')) {
      return 'javascript';
    } else if (code.includes('def ') || code.includes('import ')) {
      return 'python';
    } else if (code.includes('public class') || code.includes('private ')) {
      return 'java';
    } else if (code.includes('<?php')) {
      return 'php';
    } else if (code.includes('func ') || code.includes('let ') || code.includes('var ')) {
      return 'swift';
    } else if (code.includes('package main')) {
      return 'go';
    }
    return defaultLang;
  }

  private generateSampleCode(name: string): string {
    // Generate sample code based on snippet name
    if (name.includes('sort')) {
      return `function quickSort(arr) {
  if (arr.length <= 1) return arr;
  const pivot = arr[0];
  const left = arr.slice(1).filter(x => x < pivot);
  const right = arr.slice(1).filter(x => x >= pivot);
  return [...quickSort(left), pivot, ...quickSort(right)];
}`;
    } else if (name.includes('auth')) {
      return `async function authenticate(username, password) {
  const user = await db.users.findOne({ username });
  if (!user) return { success: false, error: 'User not found' };
  const valid = await bcrypt.compare(password, user.passwordHash);
  if (!valid) return { success: false, error: 'Invalid password' };
  const token = jwt.sign({ id: user.id }, process.env.JWT_SECRET);
  return { success: true, token };
}`;
    } else {
      return `// ${name} snippet
function ${name.replace(/[^a-zA-Z0-9]/g, '')}() {
  // TODO: Implement ${name}
  console.log('${name} executed');
}`;
    }
  }
}