/**
 * Version Command
 * Display version information and system details
 */

import { BaseCommand } from '../../../base-command';
import { CommandArgs, CommandContext, CommandResult, CommandExample } from '../../../types';
import { logger } from '../../../../utils/logger';
import * as fs from 'fs/promises';
import * as path from 'path';
import * as os from 'os';

interface VersionInfo {
  maria: string;
  node: string;
  platform: string;
  architecture: string;
  uptime: string;
  memoryUsage: {
    used: string;
    total: string;
    percentage: string;
  };
  systemInfo: {
    hostname: string;
    user: string;
    shell: string;
    terminal: string;
  };
  dependencies: Record<string, string>;
  lastUpdated: string;
  buildInfo?: {
    commit: string;
    branch: string;
    buildDate: string;
  };
}

export class VersionCommand extends BaseCommand {
  name = 'version';
  category = 'core' as const;
  description = '📋 Display version information and system details';
  override aliases = ['v', 'ver', 'info'];
  override usage = '[--detailed] [--json] [--check-updates]';

  override examples: CommandExample[] = [
    {
      input: '/version',
      description: 'Show basic version information',
      output: 'MARIA v2.0.7 - AI Development Assistant',
    },
    {
      input: '/version --detailed',
      description: 'Show detailed system and dependency information',
      output: 'Complete system report with dependencies',
    },
    {
      input: '/version --json',
      description: 'Output version information in JSON format',
      output: 'Machine-readable version data',
    },
    {
      input: '/version --check-updates',
      description: 'Check for available updates',
      output: 'Update status and availability',
    },
  ];

  private versionCache: VersionInfo | null = null;
  private cacheExpiry: number = 0;

  async execute(args: CommandArgs, _context: CommandContext): Promise<CommandResult> {
    try {
      const { flags } = args;

      // Get version information
      const versionInfo = await this.getVersionInfo();

      if (flags['check-updates']) {
        return await this.checkForUpdates(versionInfo);
      }

      if (flags['json']) {
        return this.success('Version information (JSON format)', versionInfo);
      }

      if (flags['detailed']) {
        return await this.showDetailedVersion(versionInfo);
      }

      // Show basic version info
      return this.showBasicVersion(versionInfo);

    } catch (error) {
      logger.error('Version command failed:', error);
      return this.error(
        'Failed to retrieve version information',
        'VERSION_ERROR',
        error instanceof Error ? error.message : 'Unknown error'
      );
    }
  }

  /**
   * Get comprehensive version information
   */
  private async getVersionInfo(): Promise<VersionInfo> {
    // Use cached version if still valid (cache for 1 minute)
    if (this.versionCache && Date.now() < this.cacheExpiry) {
      return this.versionCache;
    }

    try {
      const packageInfo = await this.getPackageInfo();
      const systemInfo = this.getSystemInfo();
      const dependencies = await this.getDependencyVersions();

      const versionInfo: VersionInfo = {
        maria: packageInfo.version || 'Unknown',
        node: process.version,
        platform: `${os.platform()} ${os.release()}`,
        architecture: os.arch(),
        uptime: this.formatUptime(process.uptime()),
        memoryUsage: this.getMemoryUsage(),
        systemInfo,
        dependencies,
        lastUpdated: new Date().toISOString(),
      };

      // Try to get build information if available
      try {
        const buildInfo = await this.getBuildInfo();
        if (buildInfo) {
          versionInfo.buildInfo = buildInfo;
        }
      } catch {
        // Build info not available, continue without it
      }

      // Cache the result
      this.versionCache = versionInfo;
      this.cacheExpiry = Date.now() + 60000; // 1 minute cache

      return versionInfo;
    } catch (error) {
      logger.error('Failed to gather version information:', error);
      throw error;
    }
  }

  /**
   * Read package.json information
   */
  private async getPackageInfo(): Promise<any> {
    try {
      const packagePath = path.join(process.cwd(), 'package.json');
      const packageContent = await fs.readFile(packagePath, 'utf-8');
      return JSON.parse(packageContent);
    } catch (error) {
      logger.warn('Could not read package.json:', error);
      return { version: 'Unknown' };
    }
  }

  /**
   * Get system information
   */
  private getSystemInfo() {
    return {
      hostname: os.hostname(),
      user: os.userInfo().username,
      shell: process.env['SHELL'] || 'Unknown',
      terminal: process.env['TERM'] || 'Unknown',
    };
  }

  /**
   * Get memory usage information
   */
  private getMemoryUsage() {
    const used = process.memoryUsage();
    const total = os.totalmem();
    const usedMB = Math.round(used.heapUsed / 1024 / 1024);
    const totalMB = Math.round(total / 1024 / 1024);
    const percentage = ((used.heapUsed / total) * 100).toFixed(1);

    return {
      used: `${usedMB} MB`,
      total: `${totalMB} MB`,
      percentage: `${percentage}%`,
    };
  }

  /**
   * Get versions of key dependencies
   */
  private async getDependencyVersions(): Promise<Record<string, string>> {
    const dependencies: Record<string, string> = {};

    try {
      const packageInfo = await this.getPackageInfo();
      const keyDeps = [
        'typescript',
        'tsup', 
        'chalk',
        'commander',
        'inquirer',
        '@anthropic-ai/sdk',
        'openai',
      ];

      for (const dep of keyDeps) {
        if (packageInfo.dependencies?.[dep]) {
          dependencies[dep] = packageInfo.dependencies[dep];
        } else if (packageInfo.devDependencies?.[dep]) {
          dependencies[dep] = packageInfo.devDependencies[dep];
        }
      }

      return dependencies;
    } catch {
      return {};
    }
  }

  /**
   * Try to get build information from git
   */
  private async getBuildInfo(): Promise<any> {
    // This would typically read from a build info file or git
    // For now, return null as build info is not available
    return null;
  }

  /**
   * Format uptime in human readable format
   */
  private formatUptime(seconds: number): string {
    const days = Math.floor(seconds / 86400);
    const hours = Math.floor((seconds % 86400) / 3600);
    const minutes = Math.floor((seconds % 3600) / 60);
    const secs = Math.floor(seconds % 60);

    const parts: string[] = [];
    if (days > 0) parts.push(`${days}d`);
    if (hours > 0) parts.push(`${hours}h`);
    if (minutes > 0) parts.push(`${minutes}m`);
    if (secs > 0 || parts.length === 0) parts.push(`${secs}s`);

    return parts.join(' ');
  }

  /**
   * Show basic version information
   */
  private showBasicVersion(versionInfo: VersionInfo): CommandResult {
    const lines: string[] = [];
    
    lines.push('');
    lines.push('🚀 **MARIA CODE - AI Development Assistant**');
    lines.push('');
    lines.push(`**Version:** ${versionInfo.maria}`);
    lines.push(`**Node.js:** ${versionInfo.node}`);
    lines.push(`**Platform:** ${versionInfo.platform}`);
    lines.push(`**Uptime:** ${versionInfo.uptime}`);
    lines.push('');
    lines.push('💡 Use `/version --detailed` for more information');
    lines.push('');

    return this.success(lines.join('\n'), {
      version: versionInfo.maria,
      type: 'basic',
    });
  }

  /**
   * Show detailed version information
   */
  private async showDetailedVersion(versionInfo: VersionInfo): Promise<CommandResult> {
    const lines: string[] = [];
    
    lines.push('');
    lines.push('🚀 **MARIA CODE - DETAILED SYSTEM INFORMATION**');
    lines.push('═'.repeat(60));
    lines.push('');

    // Core Information
    lines.push('**📋 Core Information:**');
    lines.push(`  Version: ${versionInfo.maria}`);
    lines.push(`  Node.js: ${versionInfo.node}`);
    lines.push(`  Platform: ${versionInfo.platform}`);
    lines.push(`  Architecture: ${versionInfo.architecture}`);
    lines.push(`  Uptime: ${versionInfo.uptime}`);
    lines.push('');

    // Memory Usage
    lines.push('**💾 Memory Usage:**');
    lines.push(`  Used: ${versionInfo.memoryUsage.used} (${versionInfo.memoryUsage.percentage})`);
    lines.push(`  Total Available: ${versionInfo.memoryUsage.total}`);
    lines.push('');

    // Dependencies
    if (Object.keys(versionInfo.dependencies).length > 0) {
      lines.push('**📦 Key Dependencies:**');
      for (const [name, version] of Object.entries(versionInfo.dependencies)) {
        lines.push(`  ${name}: ${version}`);
      }
      lines.push('');
    }

    // Build Information
    if (versionInfo.buildInfo) {
      lines.push('**🔨 Build Information:**');
      lines.push(`  Commit: ${versionInfo.buildInfo.commit}`);
      lines.push(`  Branch: ${versionInfo.buildInfo.branch}`);
      lines.push(`  Build Date: ${versionInfo.buildInfo.buildDate}`);
      lines.push('');
    }

    // Last Updated
    lines.push(`**🕒 Information gathered:** ${new Date(versionInfo.lastUpdated).toLocaleString()}`);
    lines.push('');

    return this.success(lines.join('\n'), {
      ...versionInfo,
      type: 'detailed',
    });
  }

  /**
   * Check for available updates
   */
  private async checkForUpdates(versionInfo: VersionInfo): Promise<CommandResult> {
    try {
      // In a real implementation, this would check a remote registry or API
      // For now, we'll simulate an update check
      
      const lines: string[] = [];
      lines.push('');
      lines.push('🔍 **CHECKING FOR UPDATES...**');
      lines.push('');
      lines.push(`Current version: ${versionInfo.maria}`);
      lines.push('Checking remote registry...');
      lines.push('');
      
      // Simulate update check delay
      await new Promise(resolve => setTimeout(resolve, 1000));
      
      lines.push('✅ **You are running the latest version!**');
      lines.push('');
      lines.push('💡 To manually check for updates:');
      lines.push('  • npm update @bonginkan/maria');
      lines.push('  • Or visit: https://github.com/bonginkan/maria/releases');
      lines.push('');

      return this.success(lines.join('\n'), {
        currentVersion: versionInfo.maria,
        isLatest: true,
        type: 'update-check',
      });

    } catch (error) {
      logger.error('Update check failed:', error);
      return this.error(
        'Failed to check for updates',
        'UPDATE_CHECK_FAILED',
        {
          suggestion: 'Check your internet connection and try again',
        }
      );
    }
  }

  /**
   * Validation for version command
   */
  override async validate(args: CommandArgs): Promise<{ success: boolean; error?: string }> {
    const { parsed } = args;
    const positional = (parsed['positional'] as string[]) || [];

    // Version command doesn't accept positional arguments
    if (positional.length > 0) {
      return {
        success: false,
        error: `Unexpected arguments: ${positional.join(', ')}. Use flags like --detailed instead.`,
      };
    }

    return { success: true };
  }
}