/**
 * ContentAnalyzer Component
 * Analyzes file contents and triggers appropriate actions
 */

import * as fs from 'fs';
import * as path from 'path';
import chalk from 'chalk';
import { EventEmitter } from 'events';
import { VisionAnalyzer } from './VisionAnalyzer.js';
import { FileDropEvent } from './FileDropHandler.js';
import { ReferenceItem } from './ReferenceManager.js';

/**
 * Content analysis result
 */
export interface AnalysisResult {
  type: 'text' | 'code' | 'data' | 'image' | 'document' | 'url';
  summary: string;
  language?: string;
  keywords?: string[];
  shouldResearch?: boolean;
  researchQuery?: string;
  extractedText?: string;
  metadata?: Record<string, any>;
}

/**
 * Content analyzer configuration
 */
export interface ContentAnalyzerConfig {
  enableVision?: boolean;
  enableAutoResearch?: boolean;
  maxFileSize?: number;
  codeLanguages?: string[];
  preferredVisionProvider?: 'gemini' | 'openai' | 'auto';
}

/**
 * Content analyzer class
 */
export class ContentAnalyzer extends EventEmitter {
  private config: Required<ContentAnalyzerConfig>;
  private visionAnalyzer: VisionAnalyzer | null = null;
  
  constructor(config: ContentAnalyzerConfig = {}) {
    super();
    this.config = {
      enableVision: config.enableVision ?? true,
      enableAutoResearch: config.enableAutoResearch ?? true,
      maxFileSize: config.maxFileSize || 5 * 1024 * 1024, // 5MB
      codeLanguages: config.codeLanguages || [
        'javascript', 'typescript', 'python', 'java', 'cpp', 'c',
        'go', 'rust', 'ruby', 'php', 'swift', 'kotlin'
      ],
      preferredVisionProvider: config.preferredVisionProvider || 'auto',
    };
    
    // Initialize vision analyzer if enabled
    if (this.config.enableVision) {
      this.visionAnalyzer = new VisionAnalyzer({
        preferredProvider: this.config.preferredVisionProvider,
        fallbackToOCR: true,
        enableCache: true,
      });
    }
  }

  /**
   * Analyze content from file drop event
   */
  async analyzeFileDropEvent(event: FileDropEvent): Promise<AnalysisResult> {
    switch (event.type) {
      case 'url':
        return this.analyzeURL(event.path);
      case 'image':
        return this.analyzeImage(event.path);
      case 'file':
        return this.analyzeFile(event.path);
      case 'directory':
        return this.analyzeDirectory(event.path);
      default:
        return {
          type: 'text',
          summary: `Unknown type: ${event.type}`,
        };
    }
  }

  /**
   * Analyze reference item
   */
  async analyzeReference(reference: ReferenceItem): Promise<AnalysisResult> {
    if (reference.type === 'url') {
      return this.analyzeURL(reference.path);
    } else if (reference.type === 'image') {
      return this.analyzeImage(reference.path);
    } else if (reference.type === 'file') {
      return this.analyzeFile(reference.path);
    } else if (reference.type === 'code') {
      return this.analyzeCode(reference.content || '', reference.name);
    } else if (reference.type === 'directory') {
      return this.analyzeDirectory(reference.path);
    }
    
    return {
      type: 'text',
      summary: 'Unknown reference type',
    };
  }

  /**
   * Analyze URL and determine if research is needed
   */
  private async analyzeURL(url: string): Promise<AnalysisResult> {
    this.emit('analyzing', { type: 'url', path: url });
    
    const result: AnalysisResult = {
      type: 'url',
      summary: `URL: ${url}`,
      shouldResearch: true,
      researchQuery: `Research and summarize content from: ${url}`,
    };
    
    // Detect URL type
    if (url.includes('github.com')) {
      result.summary = 'GitHub repository or file';
      result.researchQuery = `Analyze GitHub repository structure and key features from: ${url}`;
    } else if (url.includes('arxiv.org')) {
      result.summary = 'Academic paper from arXiv';
      result.researchQuery = `Summarize the research paper and key findings from: ${url}`;
    } else if (url.match(/\.(pdf|doc|docx)$/i)) {
      result.summary = 'Document URL';
      result.researchQuery = `Download and analyze document from: ${url}`;
    } else if (url.match(/\.(jpg|jpeg|png|gif|webp)$/i)) {
      result.summary = 'Image URL';
      result.shouldResearch = false; // Handle as image instead
    }
    
    this.emit('analysis-complete', result);
    return result;
  }

  /**
   * Analyze image file with Vision AI
   */
  private async analyzeImage(imagePath: string): Promise<AnalysisResult> {
    this.emit('analyzing', { type: 'image', path: imagePath });
    
    const result: AnalysisResult = {
      type: 'image',
      summary: `Image: ${path.basename(imagePath)}`,
    };
    
    // Use Vision AI if enabled
    if (this.config.enableVision && this.visionAnalyzer) {
      console.log(chalk.cyan('🖼️ Analyzing image with Vision AI...'));
      
      try {
        // Provide a specific prompt for better analysis
        const prompt = `Analyze this image and:
1. Extract any visible text
2. Describe the main content
3. Identify key objects or elements
4. Note any important context or details that would be helpful for understanding`;
        
        const visionResult = await this.visionAnalyzer.analyzeImage(imagePath, prompt);
        
        // Display the result
        this.visionAnalyzer.displayResult(visionResult, imagePath);
        
        if (visionResult.text && visionResult.text.trim()) {
          result.extractedText = visionResult.text;
          result.summary = `Image analyzed: ${visionResult.description?.substring(0, 100) || visionResult.text.substring(0, 50)}...`;
          
          // Add metadata from vision analysis
          result.metadata = {
            provider: visionResult.provider,
            confidence: visionResult.confidence,
            objects: visionResult.objects,
          };
          
          // Determine if research is needed
          if (this.shouldResearchText(visionResult.text) || visionResult.objects?.length) {
            result.shouldResearch = true;
            const context = visionResult.description || visionResult.text.substring(0, 200);
            result.researchQuery = `Provide context and explanation for this image content: ${context}`;
          }
        } else if (visionResult.description) {
          result.summary = visionResult.description.substring(0, 150);
          
          // Still trigger research for images with descriptions but no text
          if (visionResult.objects?.length || visionResult.labels?.length) {
            result.shouldResearch = true;
            result.researchQuery = `Explain the significance of: ${visionResult.description}`;
          }
        } else {
          result.summary = `Image analyzed (${visionResult.provider})`;
        }
      } catch (error) {
        console.log(chalk.yellow('⚠️ Vision analysis failed'));
        result.summary = 'Image (analysis failed)';
      }
    }
    
    this.emit('analysis-complete', result);
    return result;
  }

  /**
   * Analyze regular file
   */
  private async analyzeFile(filePath: string): Promise<AnalysisResult> {
    this.emit('analyzing', { type: 'file', path: filePath });
    
    const ext = path.extname(filePath).toLowerCase();
    const basename = path.basename(filePath);
    
    // Check file size
    const stats = await fs.promises.stat(filePath);
    if (stats.size > this.config.maxFileSize) {
      return {
        type: 'document',
        summary: `Large file: ${basename} (${this.formatFileSize(stats.size)})`,
        metadata: { size: stats.size, tooLarge: true },
      };
    }
    
    // Determine file type and analyze accordingly
    if (this.isCodeFile(ext)) {
      const content = await fs.promises.readFile(filePath, 'utf-8');
      return this.analyzeCode(content, basename);
    } else if (this.isDataFile(ext)) {
      return this.analyzeDataFile(filePath);
    } else if (this.isDocumentFile(ext)) {
      return this.analyzeDocument(filePath);
    } else {
      // Try to read as text
      try {
        const content = await fs.promises.readFile(filePath, 'utf-8');
        return this.analyzeTextContent(content, basename);
      } catch {
        return {
          type: 'document',
          summary: `Binary file: ${basename}`,
        };
      }
    }
  }

  /**
   * Analyze code content
   */
  private async analyzeCode(content: string, filename: string): Promise<AnalysisResult> {
    const language = this.detectLanguage(filename, content);
    const lines = content.split('\n').length;
    
    // Extract key information
    const keywords = this.extractKeywords(content);
    const hasTests = /test|spec|jest|mocha|chai/.test(content.toLowerCase());
    const hasMain = /main|app|index/.test(filename.toLowerCase());
    
    const result: AnalysisResult = {
      type: 'code',
      summary: `${language} code: ${filename} (${lines} lines)`,
      language,
      keywords,
      metadata: {
        lines,
        hasTests,
        hasMain,
      },
    };
    
    // Determine if explanation is needed
    if (lines > 100 || keywords.includes('algorithm') || keywords.includes('complex')) {
      result.shouldResearch = true;
      result.researchQuery = `Analyze and explain the ${language} code in ${filename}, focusing on its main functionality and architecture`;
    }
    
    this.emit('analysis-complete', result);
    return result;
  }

  /**
   * Analyze data file
   */
  private async analyzeDataFile(filePath: string): Promise<AnalysisResult> {
    const ext = path.extname(filePath).toLowerCase();
    const basename = path.basename(filePath);
    
    let result: AnalysisResult = {
      type: 'data',
      summary: `Data file: ${basename}`,
    };
    
    if (ext === '.json') {
      try {
        const content = await fs.promises.readFile(filePath, 'utf-8');
        const data = JSON.parse(content);
        const keys = Object.keys(data).slice(0, 5);
        result.summary = `JSON file with keys: ${keys.join(', ')}${keys.length < Object.keys(data).length ? '...' : ''}`;
        result.keywords = keys;
      } catch {
        result.summary = `Invalid JSON file: ${basename}`;
      }
    } else if (ext === '.csv') {
      try {
        const content = await fs.promises.readFile(filePath, 'utf-8');
        const lines = content.split('\n');
        if (lines.length > 0 && lines[0]) {
          const headers = lines[0].split(',').map(h => h.trim());
          result.summary = `CSV file with columns: ${headers.slice(0, 5).join(', ')}${headers.length > 5 ? '...' : ''}`;
          result.keywords = headers.slice(0, 10);
        } else {
          result.summary = `Empty CSV file: ${basename}`;
        }
      } catch {
        result.summary = `CSV file: ${basename}`;
      }
    }
    
    return result;
  }

  /**
   * Analyze document file
   */
  private async analyzeDocument(filePath: string): Promise<AnalysisResult> {
    const basename = path.basename(filePath);
    const ext = path.extname(filePath).toLowerCase();
    
    const result: AnalysisResult = {
      type: 'document',
      summary: `Document: ${basename}`,
    };
    
    // For markdown files, we can read and analyze
    if (ext === '.md') {
      try {
        const content = await fs.promises.readFile(filePath, 'utf-8');
        const headers = content.match(/^#{1,3} .+$/gm) || [];
        result.summary = `Markdown document with ${headers.length} sections`;
        result.keywords = headers.slice(0, 5).map(h => h.replace(/^#+\s*/, ''));
        
        if (content.length > 1000) {
          result.shouldResearch = true;
          result.researchQuery = `Summarize the key points from the markdown document: ${basename}`;
        }
      } catch {
        // Keep default summary
      }
    }
    
    return result;
  }

  /**
   * Analyze directory
   */
  private async analyzeDirectory(dirPath: string): Promise<AnalysisResult> {
    const basename = path.basename(dirPath);
    
    try {
      const files = await fs.promises.readdir(dirPath);
      const fileTypes = new Set<string>();
      
      for (const file of files.slice(0, 100)) { // Limit to first 100 files
        const ext = path.extname(file).toLowerCase();
        if (ext) fileTypes.add(ext);
      }
      
      return {
        type: 'document',
        summary: `Directory: ${basename} (${files.length} items)`,
        metadata: {
          fileCount: files.length,
          fileTypes: Array.from(fileTypes),
        },
      };
    } catch {
      return {
        type: 'document',
        summary: `Directory: ${basename} (inaccessible)`,
      };
    }
  }

  /**
   * Analyze text content
   */
  private async analyzeTextContent(content: string, filename: string): Promise<AnalysisResult> {
    const lines = content.split('\n').length;
    const words = content.split(/\s+/).length;
    
    const result: AnalysisResult = {
      type: 'text',
      summary: `Text file: ${filename} (${lines} lines, ${words} words)`,
      keywords: this.extractKeywords(content),
    };
    
    if (words > 500) {
      result.shouldResearch = true;
      result.researchQuery = `Summarize the main points from the text file: ${filename}`;
    }
    
    return result;
  }

  /**
   * Detect programming language
   */
  private detectLanguage(filename: string, _content: string): string {
    const ext = path.extname(filename).toLowerCase();
    
    const extToLang: Record<string, string> = {
      '.js': 'JavaScript',
      '.ts': 'TypeScript',
      '.py': 'Python',
      '.java': 'Java',
      '.cpp': 'C++',
      '.c': 'C',
      '.go': 'Go',
      '.rs': 'Rust',
      '.rb': 'Ruby',
      '.php': 'PHP',
      '.swift': 'Swift',
      '.kt': 'Kotlin',
      '.cs': 'C#',
      '.r': 'R',
      '.m': 'MATLAB',
    };
    
    return extToLang[ext] || 'Unknown';
  }

  /**
   * Check if file is code
   */
  private isCodeFile(ext: string): boolean {
    const codeExtensions = [
      '.js', '.ts', '.jsx', '.tsx', '.py', '.java', '.cpp', '.c', '.h',
      '.go', '.rs', '.rb', '.php', '.swift', '.kt', '.cs', '.r', '.m',
      '.sh', '.bash', '.zsh', '.ps1', '.vim', '.lua',
    ];
    return codeExtensions.includes(ext);
  }

  /**
   * Check if file is data
   */
  private isDataFile(ext: string): boolean {
    return ['.json', '.csv', '.xml', '.yaml', '.yml', '.toml'].includes(ext);
  }

  /**
   * Check if file is document
   */
  private isDocumentFile(ext: string): boolean {
    return ['.md', '.txt', '.pdf', '.doc', '.docx', '.rtf'].includes(ext);
  }

  /**
   * Extract keywords from text
   */
  private extractKeywords(text: string): string[] {
    // Simple keyword extraction - can be improved
    const words = text.toLowerCase().split(/\W+/);
    const stopWords = new Set(['the', 'a', 'an', 'and', 'or', 'but', 'in', 'on', 'at', 'to', 'for']);
    
    const wordFreq = new Map<string, number>();
    for (const word of words) {
      if (word.length > 3 && !stopWords.has(word)) {
        wordFreq.set(word, (wordFreq.get(word) || 0) + 1);
      }
    }
    
    // Sort by frequency and return top keywords
    return Array.from(wordFreq.entries())
      .sort((a, b) => b[1] - a[1])
      .slice(0, 10)
      .map(([word]) => word);
  }

  /**
   * Determine if text should trigger research
   */
  private shouldResearchText(text: string): boolean {
    // Check for patterns that might need research
    const researchPatterns = [
      /https?:\/\//i, // URLs
      /\b(API|SDK|framework|library)\b/i, // Technical terms
      /\b(error|exception|bug|issue)\b/i, // Problems
      /\b(how|what|why|when|where)\b/i, // Questions
    ];
    
    return researchPatterns.some(pattern => pattern.test(text));
  }

  /**
   * Format file size
   */
  private formatFileSize(bytes: number): string {
    const units = ['B', 'KB', 'MB', 'GB'];
    let size = bytes;
    let unitIndex = 0;
    
    while (size >= 1024 && unitIndex < units.length - 1) {
      size /= 1024;
      unitIndex++;
    }
    
    return `${size.toFixed(1)} ${units[unitIndex]}`;
  }

  /**
   * Display analysis summary
   */
  displaySummary(result: AnalysisResult): void {
    console.log(chalk.cyan('\n📊 Content Analysis:'));
    console.log(`  Type: ${chalk.yellow(result.type)}`);
    console.log(`  Summary: ${chalk.white(result.summary)}`);
    
    if (result.language) {
      console.log(`  Language: ${chalk.blue(result.language)}`);
    }
    
    if (result.keywords && result.keywords.length > 0) {
      console.log(`  Keywords: ${chalk.gray(result.keywords.slice(0, 5).join(', '))}`);
    }
    
    if (result.extractedText) {
      const preview = result.extractedText.substring(0, 100);
      console.log(`  Extracted: ${chalk.gray(preview)}${result.extractedText.length > 100 ? '...' : ''}`);
    }
    
    if (result.shouldResearch) {
      console.log(`  ${chalk.green('🔍 Auto-research triggered')}`);
    }
  }
}

export default ContentAnalyzer;