import { EventEmitter } from 'events';

export interface VisualizationEngine {
    render(data: any[], config: VisualizationConfig): Promise<string>;
    export(data: any[], config: VisualizationConfig, format: ExportFormat): Promise<Buffer | string>;
}

export interface VisualizationConfig {
    type: ChartType;
    title?: string;
    width: number;
    height: number;
    theme: VisualizationTheme;
    axes?: AxisConfig[];
    series?: SeriesConfig[];
    legend?: LegendConfig;
    tooltip?: TooltipConfig;
    animation?: AnimationConfig;
    interaction?: InteractionConfig;
    grid?: GridConfig;
    colors?: ColorPalette;
}

export type ChartType = 'line' | 'bar' | 'area' | 'scatter' | 'pie' | 'gauge' | 'heatmap' | 'histogram' | 'box' | 'candlestick' | 'radar' | 'treemap' | 'sankey';

export type ExportFormat = 'png' | 'svg' | 'pdf' | 'ascii' | 'html';

export interface VisualizationTheme {
    name: string;
    background: string;
    foreground: string;
    grid: string;
    accent: string;
    success: string;
    warning: string;
    error: string;
    text: TextTheme;
}

export interface TextTheme {
    primary: string;
    secondary: string;
    disabled: string;
    fontSize: {
        title: number;
        subtitle: number;
        label: number;
        annotation: number;
    };
    fontFamily: string;
}

export interface AxisConfig {
    id: string;
    type: 'linear' | 'logarithmic' | 'time' | 'category';
    position: 'left' | 'right' | 'top' | 'bottom';
    label?: string;
    min?: number;
    max?: number;
    ticks?: TickConfig;
    grid?: boolean;
    format?: string;
}

export interface TickConfig {
    count?: number;
    interval?: number;
    format?: string;
    rotation?: number;
}

export interface SeriesConfig {
    id: string;
    name: string;
    type?: ChartType;
    data: string | string[]; // field reference
    xField?: string;
    yField?: string;
    color?: string;
    style?: SeriesStyle;
    markers?: MarkerConfig;
    fill?: FillConfig;
}

export interface SeriesStyle {
    lineWidth?: number;
    lineDash?: number[];
    opacity?: number;
    strokeColor?: string;
    fillColor?: string;
}

export interface MarkerConfig {
    enabled: boolean;
    type: 'circle' | 'square' | 'triangle' | 'diamond';
    size: number;
    color?: string;
}

export interface FillConfig {
    enabled: boolean;
    color?: string;
    opacity?: number;
    gradient?: GradientConfig;
}

export interface GradientConfig {
    type: 'linear' | 'radial';
    stops: { offset: number; color: string }[];
}

export interface LegendConfig {
    enabled: boolean;
    position: 'top' | 'bottom' | 'left' | 'right';
    align: 'start' | 'center' | 'end';
    orientation: 'horizontal' | 'vertical';
    interactive: boolean;
}

export interface TooltipConfig {
    enabled: boolean;
    shared: boolean;
    format?: string;
    backgroundColor?: string;
    borderColor?: string;
    textColor?: string;
}

export interface AnimationConfig {
    enabled: boolean;
    duration: number;
    easing: 'linear' | 'ease' | 'ease-in' | 'ease-out' | 'ease-in-out';
    delay?: number;
    stagger?: number;
}

export interface InteractionConfig {
    zoom: boolean;
    pan: boolean;
    select: boolean;
    brush: boolean;
    crosshair: boolean;
}

export interface GridConfig {
    x: boolean;
    y: boolean;
    color?: string;
    width?: number;
    dash?: number[];
}

export interface ColorPalette {
    primary: string[];
    secondary: string[];
    categorical: string[];
    sequential: string[];
    diverging: string[];
}

export interface RenderContext {
    width: number;
    height: number;
    dpi: number;
    antialiasing: boolean;
}

// ASCII Chart Renderer for terminal output
export class ASCIIChartRenderer implements VisualizationEngine {
    async render(data: any[], config: VisualizationConfig): Promise<string> {
        switch (config.type) {
            case 'line':
                return this.renderLineChart(data, config);
            case 'bar':
                return this.renderBarChart(data, config);
            case 'histogram':
                return this.renderHistogram(data, config);
            case 'gauge':
                return this.renderGauge(data, config);
            case 'heatmap':
                return this.renderHeatmap(data, config);
            default:
                return this.renderGeneric(data, config);
        }
    }

    async export(data: any[], config: VisualizationConfig, format: ExportFormat): Promise<string> {
        if (format !== 'ascii') {
            throw new Error('ASCII renderer only supports ascii export format');
        }
        return this.render(data, config);
    }

    private renderLineChart(data: any[], config: VisualizationConfig): string {
        if (data.length === 0) return 'No data';

        const series = config.series?.[0];
        if (!series) return 'No series defined';

        const values = data.map(d => Number(this.getFieldValue(d, series.yField || 'value')) || 0);
        const min = Math.min(...values);
        const max = Math.max(...values);
        const range = max - min || 1;

        const width = Math.min(config.width || 60, 80);
        const height = Math.min(config.height || 20, 30);
        
        let chart = '';
        
        // Add title
        if (config.title) {
            chart += `${config.title.padStart((width + config.title.length) / 2)}\n`;
            chart += '─'.repeat(width) + '\n';
        }

        // Create chart grid
        const grid: string[][] = Array(height).fill(null).map(() => Array(width).fill(' '));

        // Plot data points
        const step = Math.max(1, Math.floor(values.length / width));
        
        for (let x = 0; x < width && x * step < values.length; x++) {
            const value = values[x * step];
            const y = Math.floor((height - 1) * (1 - (value - min) / range));
            const clampedY = Math.max(0, Math.min(height - 1, y));
            
            grid[clampedY][x] = '●';
            
            // Connect points with lines
            if (x > 0) {
                const prevValue = values[(x - 1) * step];
                const prevY = Math.floor((height - 1) * (1 - (prevValue - min) / range));
                const clampedPrevY = Math.max(0, Math.min(height - 1, prevY));
                
                const startY = Math.min(clampedY, clampedPrevY);
                const endY = Math.max(clampedY, clampedPrevY);
                
                for (let lineY = startY; lineY <= endY; lineY++) {
                    if (lineY !== clampedY && lineY !== clampedPrevY) {
                        grid[lineY][x - 1] = '│';
                    }
                }
            }
        }

        // Convert grid to string with Y-axis labels
        for (let y = 0; y < height; y++) {
            const yValue = min + (range * (height - 1 - y) / (height - 1));
            const yLabel = yValue.toFixed(1).padStart(6);
            chart += `${yLabel} │${grid[y].join('')}\n`;
        }

        // Add X-axis
        chart += '      └' + '─'.repeat(width) + '\n';
        
        // Add X-axis labels
        const xLabel = `${series.name || 'Values'} (${values.length} points)`;
        chart += `        ${xLabel}`;

        return chart;
    }

    private renderBarChart(data: any[], config: VisualizationConfig): string {
        if (data.length === 0) return 'No data';

        const series = config.series?.[0];
        if (!series) return 'No series defined';

        const items = data.slice(0, 20); // Limit to 20 items
        const values = items.map(d => Number(this.getFieldValue(d, series.yField || 'value')) || 0);
        const labels = items.map(d => String(this.getFieldValue(d, series.xField || 'label') || ''));

        const max = Math.max(...values, 1);
        const maxWidth = 40;
        const maxLabelWidth = Math.max(...labels.map(l => l.length), 8);

        let chart = '';
        
        if (config.title) {
            chart += `${config.title}\n`;
            chart += '═'.repeat(config.title.length) + '\n\n';
        }

        for (let i = 0; i < items.length; i++) {
            const value = values[i];
            const label = labels[i].padEnd(maxLabelWidth);
            const barWidth = Math.floor((value / max) * maxWidth);
            const bar = '█'.repeat(barWidth);
            const valueStr = value.toFixed(1);
            
            chart += `${label} │${bar}${' '.repeat(maxWidth - barWidth)} ${valueStr}\n`;
        }

        return chart;
    }

    private renderHistogram(data: any[], config: VisualizationConfig): string {
        if (data.length === 0) return 'No data';

        const series = config.series?.[0];
        if (!series) return 'No series defined';

        const values = data.map(d => Number(this.getFieldValue(d, series.yField || 'value')) || 0);
        const min = Math.min(...values);
        const max = Math.max(...values);
        const bins = 10;
        const binSize = (max - min) / bins;

        const histogram = new Array(bins).fill(0);
        
        values.forEach(value => {
            const binIndex = Math.min(bins - 1, Math.floor((value - min) / binSize));
            histogram[binIndex]++;
        });

        const maxCount = Math.max(...histogram);
        const barWidth = 30;

        let chart = '';
        
        if (config.title) {
            chart += `${config.title}\n`;
            chart += '─'.repeat(config.title.length) + '\n\n';
        }

        for (let i = 0; i < bins; i++) {
            const rangeStart = (min + i * binSize).toFixed(1);
            const rangeEnd = (min + (i + 1) * binSize).toFixed(1);
            const count = histogram[i];
            const barLen = Math.floor((count / maxCount) * barWidth);
            const bar = '█'.repeat(barLen);
            
            chart += `${rangeStart}-${rangeEnd} │${bar}${' '.repeat(barWidth - barLen)} ${count}\n`;
        }

        return chart;
    }

    private renderGauge(data: any[], config: VisualizationConfig): string {
        if (data.length === 0) return 'No data';

        const value = Number(data[data.length - 1].value || 0);
        const min = config.axes?.[0]?.min || 0;
        const max = config.axes?.[0]?.max || 100;
        const range = max - min;
        const percentage = Math.max(0, Math.min(100, ((value - min) / range) * 100));

        const width = 40;
        const filled = Math.floor((percentage / 100) * width);
        const empty = width - filled;

        let gauge = '';
        
        if (config.title) {
            gauge += `${config.title}\n`;
        }

        gauge += `Value: ${value.toFixed(2)} (${percentage.toFixed(1)}%)\n`;
        gauge += `[${' '.repeat(filled)}${'░'.repeat(empty)}] ${min}-${max}\n`;
        gauge += ` ${' '.repeat(filled)}▲\n`;

        // Add color indicator
        let indicator = '●';
        if (percentage < 30) indicator = '🔴';
        else if (percentage < 70) indicator = '🟡';
        else indicator = '🟢';

        gauge += ` Status: ${indicator}`;

        return gauge;
    }

    private renderHeatmap(data: any[], config: VisualizationConfig): string {
        if (data.length === 0) return 'No data';

        const series = config.series?.[0];
        if (!series) return 'No series defined';

        // Group data by x and y coordinates
        const grid = new Map<string, number>();
        let minValue = Infinity;
        let maxValue = -Infinity;

        data.forEach(d => {
            const x = String(this.getFieldValue(d, series.xField || 'x'));
            const y = String(this.getFieldValue(d, series.yField || 'y'));
            const value = Number(this.getFieldValue(d, 'value')) || 0;
            
            const key = `${x},${y}`;
            grid.set(key, (grid.get(key) || 0) + value);
            
            minValue = Math.min(minValue, value);
            maxValue = Math.max(maxValue, value);
        });

        const xLabels = [...new Set(data.map(d => String(this.getFieldValue(d, series.xField || 'x'))))];
        const yLabels = [...new Set(data.map(d => String(this.getFieldValue(d, series.yField || 'y'))))];

        const range = maxValue - minValue || 1;
        const intensityChars = [' ', '░', '▒', '▓', '█'];

        let heatmap = '';
        
        if (config.title) {
            heatmap += `${config.title}\n`;
        }

        // Header
        heatmap += '     ';
        xLabels.forEach(x => heatmap += x.padStart(3));
        heatmap += '\n';

        // Rows
        yLabels.forEach(y => {
            heatmap += y.padStart(4) + ' ';
            
            xLabels.forEach(x => {
                const value = grid.get(`${x},${y}`) || 0;
                const intensity = Math.floor(((value - minValue) / range) * (intensityChars.length - 1));
                const char = intensityChars[Math.max(0, Math.min(intensityChars.length - 1, intensity))];
                heatmap += char.repeat(3);
            });
            
            heatmap += '\n';
        });

        return heatmap;
    }

    private renderGeneric(data: any[], config: VisualizationConfig): string {
        let output = '';
        
        if (config.title) {
            output += `${config.title}\n`;
            output += '─'.repeat(config.title.length) + '\n';
        }

        output += `Chart Type: ${config.type}\n`;
        output += `Data Points: ${data.length}\n`;
        
        if (data.length > 0) {
            output += '\nSample Data:\n';
            const sample = data.slice(0, 5);
            sample.forEach((item, index) => {
                output += `  ${index + 1}: ${JSON.stringify(item)}\n`;
            });
            
            if (data.length > 5) {
                output += `  ... and ${data.length - 5} more\n`;
            }
        }

        return output;
    }

    private getFieldValue(obj: any, field: string): any {
        return field.split('.').reduce((current, key) => current?.[key], obj);
    }
}

// HTML/SVG Chart Renderer for web output
export class HTMLChartRenderer implements VisualizationEngine {
    async render(data: any[], config: VisualizationConfig): Promise<string> {
        return this.generateHTML(data, config);
    }

    async export(data: any[], config: VisualizationConfig, format: ExportFormat): Promise<string> {
        switch (format) {
            case 'html':
                return this.generateHTML(data, config);
            case 'svg':
                return this.generateSVG(data, config);
            default:
                throw new Error(`HTML renderer does not support ${format} export format`);
        }
    }

    private generateHTML(data: any[], config: VisualizationConfig): string {
        const containerId = `chart_${Math.random().toString(36).substr(2, 9)}`;
        
        return `
<!DOCTYPE html>
<html>
<head>
    <meta charset="UTF-8">
    <title>${config.title || 'Chart'}</title>
    <style>
        body { 
            font-family: 'Segoe UI', Tahoma, Geneva, Verdana, sans-serif; 
            margin: 20px;
            background-color: ${config.theme.background};
            color: ${config.theme.text.primary};
        }
        #${containerId} {
            width: ${config.width}px;
            height: ${config.height}px;
            border: 1px solid ${config.theme.grid};
            background-color: ${config.theme.background};
        }
        .chart-title {
            text-align: center;
            font-size: ${config.theme.text.fontSize.title}px;
            font-weight: bold;
            margin-bottom: 20px;
            color: ${config.theme.text.primary};
        }
        .chart-container {
            position: relative;
            margin: 20px auto;
        }
        .tooltip {
            position: absolute;
            background-color: rgba(0,0,0,0.8);
            color: white;
            padding: 5px 10px;
            border-radius: 4px;
            font-size: 12px;
            pointer-events: none;
            z-index: 1000;
        }
        .legend {
            display: flex;
            justify-content: center;
            margin-top: 20px;
            flex-wrap: wrap;
        }
        .legend-item {
            display: flex;
            align-items: center;
            margin: 0 10px;
            font-size: ${config.theme.text.fontSize.label}px;
        }
        .legend-color {
            width: 16px;
            height: 16px;
            margin-right: 5px;
        }
    </style>
</head>
<body>
    <div class="chart-container">
        ${config.title ? `<div class="chart-title">${config.title}</div>` : ''}
        <div id="${containerId}"></div>
        ${this.generateLegend(config)}
    </div>
    
    <script>
        ${this.generateChartScript(data, config, containerId)}
    </script>
</body>
</html>`;
    }

    private generateSVG(data: any[], config: VisualizationConfig): string {
        const width = config.width;
        const height = config.height;
        const margin = { top: 40, right: 40, bottom: 40, left: 60 };
        const innerWidth = width - margin.left - margin.right;
        const innerHeight = height - margin.top - margin.bottom;

        let svg = `
<svg width="${width}" height="${height}" xmlns="http://www.w3.org/2000/svg">
    <defs>
        <style>
            .chart-title { font-size: ${config.theme.text.fontSize.title}px; font-weight: bold; text-anchor: middle; fill: ${config.theme.text.primary}; }
            .axis-label { font-size: ${config.theme.text.fontSize.label}px; fill: ${config.theme.text.primary}; }
            .grid-line { stroke: ${config.theme.grid}; stroke-width: 1; opacity: 0.3; }
            .data-line { fill: none; stroke: ${config.colors?.primary[0] || config.theme.accent}; stroke-width: 2; }
            .data-point { fill: ${config.colors?.primary[0] || config.theme.accent}; }
        </style>
    </defs>
    
    <!-- Background -->
    <rect width="${width}" height="${height}" fill="${config.theme.background}"/>
    
    <!-- Title -->
    ${config.title ? `<text x="${width/2}" y="25" class="chart-title">${config.title}</text>` : ''}
    
    <!-- Chart Area -->
    <g transform="translate(${margin.left}, ${margin.top})">`;

        // Add grid if enabled
        if (config.grid?.x || config.grid?.y) {
            svg += this.generateSVGGrid(innerWidth, innerHeight, config);
        }

        // Add chart content based on type
        svg += this.generateSVGChart(data, config, innerWidth, innerHeight);

        svg += `
    </g>
</svg>`;

        return svg;
    }

    private generateSVGGrid(width: number, height: number, config: VisualizationConfig): string {
        let grid = '';
        
        if (config.grid?.x) {
            const xSteps = 10;
            for (let i = 0; i <= xSteps; i++) {
                const x = (width / xSteps) * i;
                grid += `<line x1="${x}" y1="0" x2="${x}" y2="${height}" class="grid-line"/>`;
            }
        }
        
        if (config.grid?.y) {
            const ySteps = 8;
            for (let i = 0; i <= ySteps; i++) {
                const y = (height / ySteps) * i;
                grid += `<line x1="0" y1="${y}" x2="${width}" y2="${y}" class="grid-line"/>`;
            }
        }
        
        return grid;
    }

    private generateSVGChart(data: any[], config: VisualizationConfig, width: number, height: number): string {
        if (!config.series || config.series.length === 0) return '';

        const series = config.series[0];
        const values = data.map(d => Number(this.getFieldValue(d, series.yField || 'value')) || 0);
        
        if (values.length === 0) return '';

        const min = Math.min(...values);
        const max = Math.max(...values);
        const range = max - min || 1;

        switch (config.type) {
            case 'line':
                return this.generateSVGLineChart(values, width, height, min, range);
            case 'bar':
                return this.generateSVGBarChart(data, series, width, height, min, range);
            default:
                return `<text x="${width/2}" y="${height/2}" text-anchor="middle" fill="${config.theme.text.primary}">Chart type ${config.type} not implemented</text>`;
        }
    }

    private generateSVGLineChart(values: number[], width: number, height: number, min: number, range: number): string {
        if (values.length < 2) return '';

        const points: string[] = [];
        const stepX = width / (values.length - 1);

        values.forEach((value, index) => {
            const x = index * stepX;
            const y = height - ((value - min) / range) * height;
            points.push(`${x},${y}`);
        });

        let svg = `<polyline points="${points.join(' ')}" class="data-line"/>`;
        
        // Add data points
        points.forEach(point => {
            const [x, y] = point.split(',').map(Number);
            svg += `<circle cx="${x}" cy="${y}" r="3" class="data-point"/>`;
        });

        return svg;
    }

    private generateSVGBarChart(data: any[], series: any, width: number, height: number, min: number, range: number): string {
        const barWidth = width / data.length * 0.8;
        const gap = width / data.length * 0.2;
        
        let svg = '';
        
        data.forEach((item, index) => {
            const value = Number(this.getFieldValue(item, series.yField || 'value')) || 0;
            const barHeight = ((value - min) / range) * height;
            const x = index * (barWidth + gap);
            const y = height - barHeight;
            
            svg += `<rect x="${x}" y="${y}" width="${barWidth}" height="${barHeight}" fill="${series.color || '#3498db'}"/>`;
        });

        return svg;
    }

    private generateLegend(config: VisualizationConfig): string {
        if (!config.legend?.enabled || !config.series) return '';

        const legendItems = config.series.map(series => `
            <div class="legend-item">
                <div class="legend-color" style="background-color: ${series.color || config.theme.accent}"></div>
                <span>${series.name}</span>
            </div>
        `).join('');

        return `<div class="legend">${legendItems}</div>`;
    }

    private generateChartScript(data: any[], config: VisualizationConfig, containerId: string): string {
        // Simple JavaScript charting implementation
        return `
        (function() {
            const container = document.getElementById('${containerId}');
            const canvas = document.createElement('canvas');
            canvas.width = ${config.width};
            canvas.height = ${config.height};
            container.appendChild(canvas);
            
            const ctx = canvas.getContext('2d');
            const data = ${JSON.stringify(data)};
            const config = ${JSON.stringify(config)};
            
            // Simple chart rendering
            ctx.fillStyle = config.theme.background;
            ctx.fillRect(0, 0, canvas.width, canvas.height);
            
            ctx.strokeStyle = config.theme.accent;
            ctx.lineWidth = 2;
            ctx.textAlign = 'center';
            ctx.fillStyle = config.theme.text.primary;
            ctx.font = '14px ${config.theme.text.fontFamily}';
            
            if (data.length > 0) {
                ctx.fillText('Interactive chart rendered with ${data.length} data points', canvas.width/2, canvas.height/2);
            } else {
                ctx.fillText('No data to display', canvas.width/2, canvas.height/2);
            }
        })();`;
    }

    private getFieldValue(obj: any, field: string): any {
        return field.split('.').reduce((current, key) => current?.[key], obj);
    }
}

// Chart factory for creating appropriate renderers
export class ChartFactory {
    private static renderers = new Map<string, () => VisualizationEngine>([
        ['ascii', () => new ASCIIChartRenderer()],
        ['html', () => new HTMLChartRenderer()],
        ['svg', () => new HTMLChartRenderer()]
    ]);

    static createRenderer(type: 'ascii' | 'html' | 'svg'): VisualizationEngine {
        const factory = this.renderers.get(type);
        if (!factory) {
            throw new Error(`Unknown renderer type: ${type}`);
        }
        return factory();
    }

    static registerRenderer(type: string, factory: () => VisualizationEngine): void {
        this.renderers.set(type, factory);
    }

    static getAvailableRenderers(): string[] {
        return Array.from(this.renderers.keys());
    }
}

