// Utility functions for visualization
export class VisualizationUtils {
    static createDefaultConfig(type: ChartType, theme: string = 'default'): VisualizationConfig {
        return {
            type,
            width: 800,
            height: 400,
            theme: BuiltinThemes[theme] || BuiltinThemes.default,
            colors: ColorPalettes.default,
            legend: { enabled: true, position: 'bottom', align: 'center', orientation: 'horizontal', interactive: false },
            tooltip: { enabled: true, shared: false },
            animation: { enabled: true, duration: 500, easing: 'ease-out' },
            grid: { x: true, y: true }
        };
    }

    static validateData(data: any[], config: VisualizationConfig): { valid: boolean; errors: string[] } {
        const errors: string[] = [];

        if (!Array.isArray(data)) {
            errors.push('Data must be an array');
        }

        if (data.length === 0) {
            errors.push('Data array is empty');
        }

        if (config.series) {
            for (const series of config.series) {
                if (!series.data && !series.yField) {
                    errors.push(`Series '${series.name}' missing data field reference`);
                }
            }
        }

        return { valid: errors.length === 0, errors };
    }

    static preprocessData(data: any[], config: VisualizationConfig): any[] {
        // Sort data if time series
        if (config.type === 'line' && config.axes?.some(axis => axis.type === 'time')) {
            const timeField = config.axes.find(axis => axis.type === 'time')?.id || 'timestamp';
            return [...data].sort((a, b) => new Date(a[timeField]).getTime() - new Date(b[timeField]).getTime());
        }

        // Limit data points for performance
        if (data.length > 1000) {
            const step = Math.ceil(data.length / 1000);
            return data.filter((_, index) => index % step === 0);
        }

        return data;
    }

    static calculateOptimalDimensions(dataCount: number, chartType: ChartType): { width: number; height: number } {
        const baseWidth = 600;
        const baseHeight = 400;

        switch (chartType) {
            case 'pie':
                return { width: Math.min(baseWidth, baseHeight), height: Math.min(baseWidth, baseHeight) };
            case 'bar':
                const barWidth = Math.max(baseWidth, Math.min(dataCount * 30, 1200));
                return { width: barWidth, height: baseHeight };
            case 'heatmap':
                return { width: baseWidth * 1.2, height: baseHeight * 0.8 };
            default:
                return { width: baseWidth, height: baseHeight };
        }
    }
}