/**
 * InputBox Component
 * ユーザー入力用の白枠チョークボックス
 */

import chalk from 'chalk';
import readline from 'readline';
import { DESIGN_CONSTANTS } from '../optimized-design-system.js';
import { FileDropHandler, FileDropEvent } from './FileDropHandler.js';
import { ReferenceManager } from './ReferenceManager.js';
import { ContentAnalyzer } from './ContentAnalyzer.js';
import { RealTimeFeedbackManager } from './RealTimeFeedbackManager.js';

/**
 * チョークボックス文字
 */
const CHALK_BOX_CHARS = {
  TOP_LEFT: '┌',
  TOP_RIGHT: '┐',
  BOTTOM_LEFT: '└',
  BOTTOM_RIGHT: '┘',
  HORIZONTAL: '─',
  VERTICAL: '│',
  PROMPT: '>',
} as const;

/**
 * 入力ボックス設定
 */
export interface InputBoxConfig {
  width?: number;
  promptSymbol?: string;
  promptColor?: typeof chalk;
  borderColor?: typeof chalk;
  textColor?: typeof chalk;
  multiline?: boolean;
  placeholder?: string;
}

/**
 * 入力ボックスクラス
 */
export class InputBox {
  private config: Required<InputBoxConfig>;
  private rl: readline.Interface | null = null;
  private currentInput: string = '';
  private isActive: boolean = false;
  private fileDropHandler: FileDropHandler;
  private referenceManager: ReferenceManager;
  private contentAnalyzer: ContentAnalyzer;
  private feedbackManager: RealTimeFeedbackManager;
  private triggerResearch: ((query: string) => Promise<void>) | null = null;

  constructor(config: InputBoxConfig = {}) {
    this.config = {
      width: config.width || DESIGN_CONSTANTS.CONTENT_WIDTH,
      promptSymbol: config.promptSymbol || CHALK_BOX_CHARS.PROMPT,
      promptColor: config.promptColor || chalk.cyan,
      borderColor: config.borderColor || chalk.white,
      textColor: config.textColor || chalk.white,
      multiline: config.multiline || false,
      placeholder: config.placeholder || 'Type your command or question here...',
    };
    
    // Initialize file drop handler and reference manager
    this.fileDropHandler = new FileDropHandler({
      autoReadContent: true,
      enableUrlDetection: true,
    });
    
    this.referenceManager = new ReferenceManager({
      autoExtractContent: true,
      maxReferences: 50,
    });
    
    // Initialize content analyzer with Vision AI support
    this.contentAnalyzer = new ContentAnalyzer({
      enableVision: true,
      enableAutoResearch: true,
      preferredVisionProvider: 'auto', // Will use Gemini or GPT-4o-mini automatically
    });
    
    // Initialize real-time feedback manager
    this.feedbackManager = new RealTimeFeedbackManager({
      compactMode: false,
      showTimestamps: true,
      enableNotifications: true,
    });
    
    // Set up event listeners
    this.fileDropHandler.on('file', async (event: FileDropEvent) => {
      await this.handleFileDrop(event);
    });
    
    this.fileDropHandler.on('url', async (event: FileDropEvent) => {
      await this.handleUrlDrop(event);
    });
  }

  /**
   * 入力ボックスを描画
   */
  render(value: string = ''): void {
    const width = this.config.width;
    const border = this.config.borderColor;
    const prompt = this.config.promptColor;
    const text = this.config.textColor;

    // Clear previous render
    if (this.isActive) {
      this.clearBox();
    }

    // Top border
    console.log(
      border(
        CHALK_BOX_CHARS.TOP_LEFT +
          CHALK_BOX_CHARS.HORIZONTAL.repeat(width - 2) +
          CHALK_BOX_CHARS.TOP_RIGHT,
      ),
    );

    // Empty line for padding
    console.log(
      border(CHALK_BOX_CHARS.VERTICAL) + ' '.repeat(width - 2) + border(CHALK_BOX_CHARS.VERTICAL),
    );

    // Input line with prompt
    const promptStr = prompt(` ${this.config.promptSymbol} `);
    const inputValue = value || this.currentInput;
    const displayText = inputValue || chalk.gray(this.config.placeholder);
    const maxTextWidth = width - 6; // Account for borders, prompt, and spacing

    const truncatedText =
      displayText.length > maxTextWidth
        ? `${displayText.substring(0, maxTextWidth - 3)  }...`
        : displayText;

    const textLine = promptStr + text(truncatedText);
    const padding = width - this.stripAnsi(promptStr + truncatedText).length - 2;

    console.log(
      border(CHALK_BOX_CHARS.VERTICAL) +
        textLine +
        ' '.repeat(Math.max(0, padding)) +
        border(CHALK_BOX_CHARS.VERTICAL),
    );

    // Empty line for padding
    console.log(
      border(CHALK_BOX_CHARS.VERTICAL) + ' '.repeat(width - 2) + border(CHALK_BOX_CHARS.VERTICAL),
    );

    // Bottom border
    console.log(
      border(
        CHALK_BOX_CHARS.BOTTOM_LEFT +
          CHALK_BOX_CHARS.HORIZONTAL.repeat(width - 2) +
          CHALK_BOX_CHARS.BOTTOM_RIGHT,
      ),
    );

    this.isActive = true;
  }

  /**
   * 入力ボックスをアクティブ化
   */
  async activate(): Promise<string> {
    return new Promise((resolve) => {
      this.render();

      // Create readline interface with custom prompt
      this.rl = readline.createInterface({
        input: process.stdin,
        output: process.stdout,
        terminal: true,
        prompt: '', // Empty prompt since we handle it in the box
      });

      // Move cursor to the input line (3 lines up from bottom of box)
      process.stdout.write('\x1b[3A');
      
      // Move cursor to after the prompt symbol
      const promptLength = this.stripAnsi(` ${this.config.promptSymbol} `).length + 1;
      process.stdout.write(`\x1b[${promptLength}C`);

      // Set up the readline prompt at the correct position
      this.rl.setPrompt('');
      
      // Handle input with readline
      this.rl.on('line', async (answer) => {
        this.currentInput = answer;
        
        // Process input for file drops or URLs
        await this.processInputForReferences(answer);
        
        // Move cursor to after the box
        process.stdout.write('\x1b[3B\r');
        this.deactivate();
        resolve(answer);
      });

      // Start the prompt
      this.rl.prompt();
    });
  }

  /**
   * 入力ボックスを非アクティブ化
   */
  deactivate(): void {
    if (this.rl) {
      this.rl.close();
      this.rl = null;
    }
    this.isActive = false;
  }

  /**
   * マルチライン入力モード
   */
  async activateMultiline(): Promise<string[]> {
    const lines: string[] = [];
    console.log(chalk.gray('(Press Ctrl+D or type "EOF" on a new line to finish)'));

    return new Promise((resolve) => {
      const collectLines = async () => {
        const line = await this.activate();

        if (line === 'EOF' || line === '') {
          resolve(lines);
        } else {
          lines.push(line);
          await collectLines();
        }
      };

      collectLines();
    });
  }


  /**
   * ボックスをクリア
   */
  private clearBox(): void {
    // Move up 5 lines (box height) and clear each line
    for (let i = 0; i < 5; i++) {
      process.stdout.write('\x1b[1A\x1b[2K');
    }
  }

  /**
   * ANSIコードを削除
   */
  private stripAnsi(str: string): string {
    return str.replace(/\x1b\[[0-9;]*m/g, '');
  }

  /**
   * 入力値を取得
   */
  getValue(): string {
    return this.currentInput;
  }

  /**
   * 入力値をクリア
   */
  clear(): void {
    this.currentInput = '';
    if (this.isActive) {
      this.render();
    }
  }

  /**
   * プレースホルダーを設定
   */
  setPlaceholder(placeholder: string): void {
    this.config.placeholder = placeholder;
    if (this.isActive && !this.currentInput) {
      this.render();
    }
  }

  /**
   * 入力値を設定
   */
  setValue(value: string): void {
    this.currentInput = value;
    if (this.isActive) {
      this.render(value);
    }
  }

  /**
   * スタティックレンダリング（インタラクティブでない表示）
   */
  static renderStatic(content: string, config: InputBoxConfig = {}): void {
    const box = new InputBox(config);
    box.render(content);
  }

  /**
   * コンパクト入力ボックス
   */
  static renderCompact(prompt: string = '>'): void {
    const border = chalk.white;
    const promptColor = chalk.cyan;

    console.log(
      border('[') + promptColor(` ${prompt} `) + chalk.gray('_'.repeat(40)) + border(']'),
    );
  }

  /**
   * Process input for file references and URLs
   */
  private async processInputForReferences(input: string): Promise<void> {
    try {
      const events = await this.fileDropHandler.processInput(input);
      
      // Add references to manager
      for (const event of events) {
        await this.referenceManager.addReference(event);
      }
      
      // Display summary if references were added
      if (events.length > 0) {
        this.fileDropHandler.displaySummary();
      }
    } catch (error) {
      // Silently handle errors - don't interrupt user flow
    }
  }

  /**
   * Handle file drop event
   */
  private async handleFileDrop(event: FileDropEvent): Promise<void> {
    try {
      // Show processing feedback
      this.feedbackManager.showProcessingStatus('start', `${event.type} processing`, event.name);
      
      // Add to reference manager
      await this.referenceManager.addReference(event);
      this.feedbackManager.success(`Added ${event.type}`, event.name);
      
      // Analyze content with progress
      this.feedbackManager.showProcessingStatus('progress', 'content analysis');
      const analysis = await this.contentAnalyzer.analyzeFileDropEvent(event);
      this.contentAnalyzer.displaySummary(analysis);
      
      // Trigger research if needed
      if (analysis.shouldResearch && analysis.researchQuery && this.triggerResearch) {
        this.feedbackManager.info('Auto-research triggered', 'Starting background research');
        await this.triggerResearch(analysis.researchQuery);
      }
      
      this.feedbackManager.showProcessingStatus('complete', 'file processing');
    } catch (error) {
      this.feedbackManager.showProcessingStatus('error', 'file processing', error instanceof Error ? error.message : 'Unknown error');
    }
  }

  /**
   * Handle URL drop event
   */
  private async handleUrlDrop(event: FileDropEvent): Promise<void> {
    try {
      // Show processing feedback
      this.feedbackManager.showProcessingStatus('start', 'URL processing', event.name);
      
      // Add to reference manager
      await this.referenceManager.addReference(event);
      this.feedbackManager.success('Added URL', event.name);
      
      // Analyze URL
      this.feedbackManager.showProcessingStatus('progress', 'URL analysis');
      const analysis = await this.contentAnalyzer.analyzeFileDropEvent(event);
      this.contentAnalyzer.displaySummary(analysis);
      
      // Trigger research for URLs
      if (this.triggerResearch) {
        this.feedbackManager.info('URL research triggered', 'Starting background research');
        await this.triggerResearch(`Research and summarize: ${event.path}`);
      }
      
      this.feedbackManager.showProcessingStatus('complete', 'URL processing');
    } catch (error) {
      this.feedbackManager.showProcessingStatus('error', 'URL processing', error instanceof Error ? error.message : 'Unknown error');
    }
  }

  /**
   * Get reference manager
   */
  getReferenceManager(): ReferenceManager {
    return this.referenceManager;
  }

  /**
   * Get file drop handler
   */
  getFileDropHandler(): FileDropHandler {
    return this.fileDropHandler;
  }

  /**
   * Display current references
   */
  displayReferences(): void {
    this.referenceManager.displaySummary();
  }

  /**
   * Get context with references
   */
  getContextWithReferences(): string {
    return this.referenceManager.buildContext();
  }

  /**
   * Get content analyzer
   */
  getContentAnalyzer(): ContentAnalyzer {
    return this.contentAnalyzer;
  }

  /**
   * Get feedback manager
   */
  getFeedbackManager(): RealTimeFeedbackManager {
    return this.feedbackManager;
  }

  /**
   * Set research trigger callback
   */
  setResearchTrigger(callback: (query: string) => Promise<void>): void {
    this.triggerResearch = callback;
  }

  /**
   * Process all references for analysis
   */
  async analyzeAllReferences(): Promise<void> {
    const references = this.referenceManager.getAllReferences();
    
    if (references.length === 0) {
      console.log(chalk.gray('No references to analyze'));
      return;
    }
    
    console.log(chalk.cyan(`\n📊 Analyzing ${references.length} reference(s)...`));
    
    for (const reference of references) {
      try {
        const analysis = await this.contentAnalyzer.analyzeReference(reference);
        this.contentAnalyzer.displaySummary(analysis);
        
        // Trigger research if needed
        if (analysis.shouldResearch && analysis.researchQuery && this.triggerResearch) {
          console.log(chalk.cyan('🔬 Triggering research...'));
          await this.triggerResearch(analysis.researchQuery);
        }
      } catch (error) {
        console.log(chalk.red(`✗ Failed to analyze ${reference.name}`));
      }
    }
  }
}

export default InputBox;
