import { BaseCommandService } from '../../shared/BaseCommandService';
import { BenchmarkHandler } from '../../handlers/optimization/benchmark.handler';

export class OptimizationCommandService extends BaseCommandService {
  private benchmarkHandler: BenchmarkHandler;

  constructor() {
    super();
    this.benchmarkHandler = new BenchmarkHandler();
  }

  async execute(command: string, args: string[]): Promise<string> {
    switch (command) {
      case '/benchmark':
        return this.benchmarkHandler.execute(args);
      default:
        return `Unknown optimization command: ${command}`;
    }
  }

  getCommands(): string[] {
    return ['/benchmark'];
  }

  getCategory(): string {
    return 'optimization';
  }
}