/**
 * Content Extraction Engine
 * Extracts and structures content from web pages and documents
 */

import { logger } from '../../../../utils/logger';

export interface ExtractedContent {
  // Basic content
  title: string;
  description?: string;
  content: string;
  cleanText: string;
  
  // Metadata
  metadata: {
    url: string;
    domain: string;
    author?: string;
    publishDate?: Date;
    lastModified?: Date;
    language: string;
    contentType: string;
    wordCount: number;
    readingTime: number; // minutes
    charset?: string;
  };

  // Structured content
  structure: {
    headings: Heading[];
    paragraphs: string[];
    lists: List[];
    tables: Table[];
    quotes: string[];
    codeBlocks: CodeBlock[];
  };

  // Media content
  media: {
    images: ImageInfo[];
    videos: VideoInfo[];
    audio: AudioInfo[];
    documents: DocumentInfo[];
  };

  // Links and references
  links: {
    internal: LinkInfo[];
    external: LinkInfo[];
    anchors: AnchorInfo[];
  };

  // SEO and social
  seo: {
    metaTags: Record<string, string>;
    openGraph: Record<string, string>;
    twitterCard: Record<string, string>;
    jsonLd: any[];
  };

  // Analysis results
  analysis: {
    topics: string[];
    keywords: string[];
    entities: string[];
    sentiment?: 'positive' | 'negative' | 'neutral';
    readabilityScore?: number;
  };
}

export interface Heading {
  level: number;
  text: string;
  id?: string;
}

export interface List {
  type: 'ordered' | 'unordered' | 'definition';
  items: string[];
}

export interface Table {
  headers: string[];
  rows: string[][];
  caption?: string;
}

export interface CodeBlock {
  language?: string;
  code: string;
  filename?: string;
}

export interface ImageInfo {
  src: string;
  alt?: string;
  title?: string;
  width?: number;
  height?: number;
  size?: number;
}

export interface VideoInfo {
  src: string;
  title?: string;
  duration?: number;
  thumbnail?: string;
  type?: string;
}

export interface AudioInfo {
  src: string;
  title?: string;
  duration?: number;
  type?: string;
}

export interface DocumentInfo {
  url: string;
  title?: string;
  type: string;
  size?: number;
}

export interface LinkInfo {
  url: string;
  text: string;
  title?: string;
  rel?: string;
}

export interface AnchorInfo {
  id: string;
  text: string;
}

export interface ExtractionOptions {
  includeImages: boolean;
  includeLinks: boolean;
  includeTables: boolean;
  includeCode: boolean;
  minTextLength: number;
  language?: string;
  extractKeywords: boolean;
  extractEntities: boolean;
  analyzeSentiment: boolean;
  preserveFormatting: boolean;
}

export class ContentExtractor {
  private cheerio: any = null;

  constructor() {
    try {
      this.cheerio = require('cheerio');
      logger.debug('Cheerio loaded for HTML parsing');
    } catch {
      logger.warn('Cheerio not available - HTML parsing will be limited');
    }
  }

  /**
   * Extract content from HTML
   */
  async extractFromHtml(
    html: string,
    url: string,
    options: Partial<ExtractionOptions> = {}
  ): Promise<ExtractedContent> {
    const defaultOptions: ExtractionOptions = {
      includeImages: true,
      includeLinks: true,
      includeTables: true,
      includeCode: true,
      minTextLength: 50,
      extractKeywords: true,
      extractEntities: false,
      analyzeSentiment: false,
      preserveFormatting: false,
      ...options,
    };

    try {
      if (this.cheerio) {
        return await this.extractWithCheerio(html, url, defaultOptions);
      } else {
        return await this.extractWithRegex(html, url, defaultOptions);
      }
    } catch (error) {
      logger.error('Content extraction failed:', error);
      throw new Error(`Content extraction failed: ${error instanceof Error ? error.message : 'Unknown error'}`);
    }
  }

  /**
   * Extract content using Cheerio (preferred method)
   */
  private async extractWithCheerio(
    html: string,
    url: string,
    options: ExtractionOptions
  ): Promise<ExtractedContent> {
    const $ = this.cheerio.load(html);
    const domain = this.extractDomain(url);

    // Remove unwanted elements
    $('script, style, nav, header, footer, aside, .advertisement, .ads, .social-share').remove();

    // Extract basic content
    const title = this.extractTitle($);
    const description = this.extractDescription($);
    const content = this.extractMainContent($);
    const cleanText = this.cleanText(content);

    // Extract metadata
    const metadata = {
      url,
      domain,
      author: this.extractAuthor($),
      publishDate: this.extractPublishDate($),
      lastModified: this.extractLastModified($),
      language: this.extractLanguage($),
      contentType: 'text/html',
      wordCount: this.countWords(cleanText),
      readingTime: this.calculateReadingTime(cleanText),
      charset: this.extractCharset($),
    };

    // Extract structured content
    const structure = {
      headings: this.extractHeadings($),
      paragraphs: this.extractParagraphs($),
      lists: options.includeTables ? this.extractLists($) : [],
      tables: options.includeTables ? this.extractTables($) : [],
      quotes: this.extractQuotes($),
      codeBlocks: options.includeCode ? this.extractCodeBlocks($) : [],
    };

    // Extract media
    const media = {
      images: options.includeImages ? this.extractImages($, url) : [],
      videos: this.extractVideos($, url),
      audio: this.extractAudio($, url),
      documents: this.extractDocuments($, url),
    };

    // Extract links
    const links = options.includeLinks ? {
      internal: this.extractInternalLinks($, url),
      external: this.extractExternalLinks($, url),
      anchors: this.extractAnchors($),
    } : { internal: [], external: [], anchors: [] };

    // Extract SEO data
    const seo = {
      metaTags: this.extractMetaTags($),
      openGraph: this.extractOpenGraph($),
      twitterCard: this.extractTwitterCard($),
      jsonLd: this.extractJsonLd($),
    };

    // Perform analysis
    const analysis = await this.analyzeContent(cleanText, options);

    return {
      title,
      description,
      content,
      cleanText,
      metadata,
      structure,
      media,
      links,
      seo,
      analysis,
    };
  }

  /**
   * Extract content using regex (fallback method)
   */
  private async extractWithRegex(
    html: string,
    url: string,
    options: ExtractionOptions
  ): Promise<ExtractedContent> {
    const domain = this.extractDomain(url);

    // Extract basic content with regex
    const titleMatch = html.match(/<title[^>]*>([^<]+)<\/title>/i);
    const title = titleMatch ? titleMatch[1].trim() : '';

    const descMatch = html.match(/<meta[^>]+name=["']description["'][^>]+content=["']([^"']+)["'][^>]*>/i);
    const description = descMatch ? descMatch[1] : undefined;

    // Remove script and style tags
    const cleanHtml = html
      .replace(/<script[^>]*>[\s\S]*?<\/script>/gi, '')
      .replace(/<style[^>]*>[\s\S]*?<\/style>/gi, '')
      .replace(/<[^>]+>/g, ' ')
      .replace(/\s+/g, ' ')
      .trim();

    const cleanText = this.cleanText(cleanHtml);

    // Basic metadata
    const metadata = {
      url,
      domain,
      language: 'en', // Default
      contentType: 'text/html',
      wordCount: this.countWords(cleanText),
      readingTime: this.calculateReadingTime(cleanText),
    };

    // Basic structure (limited without proper parsing)
    const structure = {
      headings: [],
      paragraphs: cleanText.split('\n').filter(p => p.length > options.minTextLength),
      lists: [],
      tables: [],
      quotes: [],
      codeBlocks: [],
    };

    const media = { images: [], videos: [], audio: [], documents: [] };
    const links = { internal: [], external: [], anchors: [] };
    const seo = { metaTags: {}, openGraph: {}, twitterCard: {}, jsonLd: [] };

    // Basic analysis
    const analysis = await this.analyzeContent(cleanText, options);

    return {
      title,
      description,
      content: cleanHtml,
      cleanText,
      metadata,
      structure,
      media,
      links,
      seo,
      analysis,
    };
  }

  /**
   * Extract title from document
   */
  private extractTitle($: any): string {
    // Try multiple sources for title
    const sources = [
      $('title').first().text(),
      $('h1').first().text(),
      $('[property="og:title"]').attr('content'),
      $('[name="twitter:title"]').attr('content'),
    ];

    for (const title of sources) {
      if (title && title.trim()) {
        return title.trim();
      }
    }

    return 'Untitled';
  }

  /**
   * Extract description from document
   */
  private extractDescription($: any): string | undefined {
    const sources = [
      $('meta[name="description"]').attr('content'),
      $('[property="og:description"]').attr('content'),
      $('[name="twitter:description"]').attr('content'),
    ];

    for (const desc of sources) {
      if (desc && desc.trim()) {
        return desc.trim();
      }
    }

    return undefined;
  }

  /**
   * Extract main content from document
   */
  private extractMainContent($: any): string {
    // Try to find main content area
    const contentSelectors = [
      'main',
      'article',
      '[role="main"]',
      '.content',
      '.main-content',
      '.post-content',
      '.entry-content',
      '.article-content',
      '#content',
      '#main',
      '.container',
      'body',
    ];

    for (const selector of contentSelectors) {
      const element = $(selector).first();
      if (element.length && element.text().trim().length > 100) {
        return element.html() || '';
      }
    }

    return $('body').html() || '';
  }

  /**
   * Extract headings from document
   */
  private extractHeadings($: any): Heading[] {
    const headings: Heading[] = [];
    
    $('h1, h2, h3, h4, h5, h6').each((_: number, element: any) => {
      const $el = $(element);
      const level = parseInt(element.tagName.substring(1));
      const text = $el.text().trim();
      const id = $el.attr('id');
      
      if (text) {
        headings.push({ level, text, id });
      }
    });

    return headings;
  }

  /**
   * Extract paragraphs from document
   */
  private extractParagraphs($: any): string[] {
    const paragraphs: string[] = [];
    
    $('p').each((_: number, element: any) => {
      const text = $(element).text().trim();
      if (text && text.length > 20) {
        paragraphs.push(text);
      }
    });

    return paragraphs;
  }

  /**
   * Extract lists from document
   */
  private extractLists($: any): List[] {
    const lists: List[] = [];

    $('ul, ol, dl').each((_: number, element: any) => {
      const $el = $(element);
      const tagName = element.tagName.toLowerCase();
      
      let type: 'ordered' | 'unordered' | 'definition';
      if (tagName === 'ol') {
        type = 'ordered';
      } else if (tagName === 'dl') {
        type = 'definition';
      } else {
        type = 'unordered';
      }

      const items: string[] = [];
      $el.find('li, dt, dd').each((_: number, item: any) => {
        const text = $(item).text().trim();
        if (text) {
          items.push(text);
        }
      });

      if (items.length > 0) {
        lists.push({ type, items });
      }
    });

    return lists;
  }

  /**
   * Extract tables from document
   */
  private extractTables($: any): Table[] {
    const tables: Table[] = [];

    $('table').each((_: number, element: any) => {
      const $table = $(element);
      const headers: string[] = [];
      const rows: string[][] = [];

      // Extract headers
      $table.find('th').each((_: number, th: any) => {
        headers.push($(th).text().trim());
      });

      // Extract rows
      $table.find('tbody tr, tr').each((_: number, tr: any) => {
        const row: string[] = [];
        $(tr).find('td, th').each((_: number, cell: any) => {
          row.push($(cell).text().trim());
        });
        if (row.length > 0) {
          rows.push(row);
        }
      });

      const caption = $table.find('caption').text().trim() || undefined;

      if (headers.length > 0 || rows.length > 0) {
        tables.push({ headers, rows, caption });
      }
    });

    return tables;
  }

  /**
   * Extract quotes from document
   */
  private extractQuotes($: any): string[] {
    const quotes: string[] = [];
    
    $('blockquote, q').each((_: number, element: any) => {
      const text = $(element).text().trim();
      if (text) {
        quotes.push(text);
      }
    });

    return quotes;
  }

  /**
   * Extract code blocks from document
   */
  private extractCodeBlocks($: any): CodeBlock[] {
    const codeBlocks: CodeBlock[] = [];
    
    $('pre code, code, .highlight').each((_: number, element: any) => {
      const $el = $(element);
      const code = $el.text().trim();
      
      if (code && code.length > 10) {
        const language = $el.attr('class')?.match(/language-(\w+)/)?.[1];
        const filename = $el.attr('data-filename');
        
        codeBlocks.push({ language, code, filename });
      }
    });

    return codeBlocks;
  }

  /**
   * Extract images from document
   */
  private extractImages($: any, baseUrl: string): ImageInfo[] {
    const images: ImageInfo[] = [];
    
    $('img').each((_: number, element: any) => {
      const $img = $(element);
      const src = this.resolveUrl($img.attr('src'), baseUrl);
      
      if (src) {
        images.push({
          src,
          alt: $img.attr('alt'),
          title: $img.attr('title'),
          width: parseInt($img.attr('width')) || undefined,
          height: parseInt($img.attr('height')) || undefined,
        });
      }
    });

    return images;
  }

  /**
   * Extract videos from document
   */
  private extractVideos($: any, baseUrl: string): VideoInfo[] {
    const videos: VideoInfo[] = [];
    
    $('video, iframe[src*="youtube"], iframe[src*="vimeo"]').each((_: number, element: any) => {
      const $el = $(element);
      const src = this.resolveUrl($el.attr('src'), baseUrl);
      
      if (src) {
        videos.push({
          src,
          title: $el.attr('title'),
          type: element.tagName.toLowerCase(),
        });
      }
    });

    return videos;
  }

  /**
   * Extract audio from document
   */
  private extractAudio($: any, baseUrl: string): AudioInfo[] {
    const audio: AudioInfo[] = [];
    
    $('audio').each((_: number, element: any) => {
      const $el = $(element);
      const src = this.resolveUrl($el.attr('src'), baseUrl);
      
      if (src) {
        audio.push({
          src,
          title: $el.attr('title'),
          type: $el.attr('type'),
        });
      }
    });

    return audio;
  }

  /**
   * Extract documents from document
   */
  private extractDocuments($: any, baseUrl: string): DocumentInfo[] {
    const documents: DocumentInfo[] = [];
    
    $('a[href$=".pdf"], a[href$=".doc"], a[href$=".docx"], a[href$=".xls"], a[href$=".xlsx"]').each((_: number, element: any) => {
      const $el = $(element);
      const url = this.resolveUrl($el.attr('href'), baseUrl);
      
      if (url) {
        const extension = url.split('.').pop()?.toLowerCase() || '';
        documents.push({
          url,
          title: $el.text().trim() || $el.attr('title'),
          type: extension,
        });
      }
    });

    return documents;
  }

  /**
   * Extract internal links
   */
  private extractInternalLinks($: any, baseUrl: string): LinkInfo[] {
    const links: LinkInfo[] = [];
    const domain = this.extractDomain(baseUrl);
    
    $('a[href]').each((_: number, element: any) => {
      const $el = $(element);
      const href = $el.attr('href');
      const text = $el.text().trim();
      
      if (href && text) {
        const url = this.resolveUrl(href, baseUrl);
        if (url && this.extractDomain(url) === domain) {
          links.push({
            url,
            text,
            title: $el.attr('title'),
            rel: $el.attr('rel'),
          });
        }
      }
    });

    return links;
  }

  /**
   * Extract external links
   */
  private extractExternalLinks($: any, baseUrl: string): LinkInfo[] {
    const links: LinkInfo[] = [];
    const domain = this.extractDomain(baseUrl);
    
    $('a[href]').each((_: number, element: any) => {
      const $el = $(element);
      const href = $el.attr('href');
      const text = $el.text().trim();
      
      if (href && text) {
        const url = this.resolveUrl(href, baseUrl);
        if (url && this.extractDomain(url) !== domain) {
          links.push({
            url,
            text,
            title: $el.attr('title'),
            rel: $el.attr('rel'),
          });
        }
      }
    });

    return links;
  }

  /**
   * Extract anchor links
   */
  private extractAnchors($: any): AnchorInfo[] {
    const anchors: AnchorInfo[] = [];
    
    $('[id]').each((_: number, element: any) => {
      const $el = $(element);
      const id = $el.attr('id');
      const text = $el.text().trim();
      
      if (id && text) {
        anchors.push({ id, text: text.substring(0, 50) });
      }
    });

    return anchors;
  }

  /**
   * Extract meta tags
   */
  private extractMetaTags($: any): Record<string, string> {
    const metaTags: Record<string, string> = {};
    
    $('meta[name], meta[property]').each((_: number, element: any) => {
      const $meta = $(element);
      const name = $meta.attr('name') || $meta.attr('property');
      const content = $meta.attr('content');
      
      if (name && content) {
        metaTags[name] = content;
      }
    });

    return metaTags;
  }

  /**
   * Extract Open Graph data
   */
  private extractOpenGraph($: any): Record<string, string> {
    const og: Record<string, string> = {};
    
    $('meta[property^="og:"]').each((_: number, element: any) => {
      const $meta = $(element);
      const property = $meta.attr('property');
      const content = $meta.attr('content');
      
      if (property && content) {
        og[property] = content;
      }
    });

    return og;
  }

  /**
   * Extract Twitter Card data
   */
  private extractTwitterCard($: any): Record<string, string> {
    const twitter: Record<string, string> = {};
    
    $('meta[name^="twitter:"]').each((_: number, element: any) => {
      const $meta = $(element);
      const name = $meta.attr('name');
      const content = $meta.attr('content');
      
      if (name && content) {
        twitter[name] = content;
      }
    });

    return twitter;
  }

  /**
   * Extract JSON-LD structured data
   */
  private extractJsonLd($: any): any[] {
    const jsonLd: any[] = [];
    
    $('script[type="application/ld+json"]').each((_: number, element: any) => {
      try {
        const content = $(element).html();
        if (content) {
          const data = JSON.parse(content);
          jsonLd.push(data);
        }
      } catch (error) {
        logger.debug('Failed to parse JSON-LD:', error);
      }
    });

    return jsonLd;
  }

  /**
   * Analyze content for topics, keywords, etc.
   */
  private async analyzeContent(text: string, options: ExtractionOptions): Promise<{
    topics: string[];
    keywords: string[];
    entities: string[];
    sentiment?: 'positive' | 'negative' | 'neutral';
    readabilityScore?: number;
  }> {
    const analysis = {
      topics: [],
      keywords: [],
      entities: [],
      sentiment: undefined as 'positive' | 'negative' | 'neutral' | undefined,
      readabilityScore: undefined as number | undefined,
    };

    try {
      // Extract keywords if requested
      if (options.extractKeywords) {
        analysis.keywords = this.extractKeywords(text);
      }

      // Basic topic detection (simplified)
      analysis.topics = this.detectTopics(text);

      // Calculate readability score
      analysis.readabilityScore = this.calculateReadabilityScore(text);

    } catch (error) {
      logger.debug('Content analysis failed:', error);
    }

    return analysis;
  }

  /**
   * Extract keywords from text
   */
  private extractKeywords(text: string): string[] {
    // Simple keyword extraction based on word frequency
    const words = text.toLowerCase()
      .replace(/[^\w\s]/g, ' ')
      .split(/\s+/)
      .filter(word => word.length > 3)
      .filter(word => !this.isStopWord(word));

    const frequency: Record<string, number> = {};
    words.forEach(word => {
      frequency[word] = (frequency[word] || 0) + 1;
    });

    return Object.entries(frequency)
      .sort((a, b) => b[1] - a[1])
      .slice(0, 20)
      .map(([word]) => word);
  }

  /**
   * Detect topics in text (simplified)
   */
  private detectTopics(text: string): string[] {
    const topicKeywords = {
      technology: ['software', 'computer', 'algorithm', 'programming', 'code', 'data', 'api', 'database'],
      business: ['company', 'market', 'revenue', 'profit', 'customer', 'sales', 'business', 'strategy'],
      science: ['research', 'study', 'experiment', 'hypothesis', 'analysis', 'method', 'result', 'conclusion'],
      health: ['health', 'medical', 'treatment', 'disease', 'patient', 'doctor', 'medicine', 'therapy'],
      education: ['learning', 'education', 'student', 'teacher', 'course', 'university', 'knowledge', 'study'],
    };

    const topics: string[] = [];
    const lowerText = text.toLowerCase();

    Object.entries(topicKeywords).forEach(([topic, keywords]) => {
      const matches = keywords.filter(keyword => lowerText.includes(keyword)).length;
      if (matches >= 2) {
        topics.push(topic);
      }
    });

    return topics;
  }

  /**
   * Calculate reading time in minutes
   */
  private calculateReadingTime(text: string): number {
    const wordsPerMinute = 200;
    const wordCount = this.countWords(text);
    return Math.ceil(wordCount / wordsPerMinute);
  }

  /**
   * Calculate readability score (Flesch Reading Ease)
   */
  private calculateReadabilityScore(text: string): number {
    const sentences = text.split(/[.!?]+/).length;
    const words = this.countWords(text);
    const syllables = this.countSyllables(text);

    if (sentences === 0 || words === 0) {return 0;}

    const score = 206.835 - (1.015 * (words / sentences)) - (84.6 * (syllables / words));
    return Math.max(0, Math.min(100, score));
  }

  // Helper methods

  private cleanText(text: string): string {
    return text
      .replace(/\s+/g, ' ')
      .replace(/\n\s*\n/g, '\n')
      .trim();
  }

  private countWords(text: string): number {
    return text.split(/\s+/).filter(word => word.length > 0).length;
  }

  private countSyllables(text: string): number {
    const words = text.toLowerCase().split(/\s+/);
    let totalSyllables = 0;

    words.forEach(word => {
      const syllables = word.match(/[aeiouy]+/g);
      totalSyllables += syllables ? syllables.length : 1;
    });

    return totalSyllables;
  }

  private isStopWord(word: string): boolean {
    const stopWords = [
      'the', 'be', 'to', 'of', 'and', 'a', 'in', 'that', 'have',
      'i', 'it', 'for', 'not', 'on', 'with', 'he', 'as', 'you',
      'do', 'at', 'this', 'but', 'his', 'by', 'from', 'they',
      'we', 'say', 'her', 'she', 'or', 'an', 'will', 'my',
      'one', 'all', 'would', 'there', 'their',
    ];
    return stopWords.includes(word);
  }

  private extractDomain(url: string): string {
    try {
      const { URL } = require('url');
      return new URL(url).hostname;
    } catch {
      return '';
    }
  }

  private extractAuthor($: any): string | undefined {
    const sources = [
      $('[rel="author"]').text(),
      $('[itemprop="author"]').text(),
      $('meta[name="author"]').attr('content'),
      $('.author').text(),
      $('.by-author').text(),
    ];

    for (const author of sources) {
      if (author && author.trim()) {
        return author.trim();
      }
    }

    return undefined;
  }

  private extractPublishDate($: any): Date | undefined {
    const sources = [
      $('[itemprop="datePublished"]').attr('datetime'),
      $('[itemprop="datePublished"]').attr('content'),
      $('meta[property="article:published_time"]').attr('content'),
      $('time[pubdate]').attr('datetime'),
      $('time').attr('datetime'),
    ];

    for (const dateStr of sources) {
      if (dateStr) {
        const date = new Date(dateStr);
        if (!isNaN(date.getTime())) {
          return date;
        }
      }
    }

    return undefined;
  }

  private extractLastModified($: any): Date | undefined {
    const sources = [
      $('[itemprop="dateModified"]').attr('datetime'),
      $('meta[property="article:modified_time"]').attr('content'),
    ];

    for (const dateStr of sources) {
      if (dateStr) {
        const date = new Date(dateStr);
        if (!isNaN(date.getTime())) {
          return date;
        }
      }
    }

    return undefined;
  }

  private extractLanguage($: any): string {
    return $('html').attr('lang') || 
           $('meta[http-equiv="content-language"]').attr('content') || 
           'en';
  }

  private extractCharset($: any): string | undefined {
    return $('meta[charset]').attr('charset') ||
           $('meta[http-equiv="content-type"]').attr('content')?.match(/charset=([^;]+)/)?.[1];
  }

  private resolveUrl(href: string | undefined, baseUrl: string): string | null {
    if (!href) {return null;}

    try {
      const { URL } = require('url');
      const resolved = new URL(href, baseUrl);
      return resolved.href;
    } catch {
      return null;
    }
  }
}