import { BaseCommandService } from '../../shared/BaseCommandService';
import { SnippetHandler } from '../../handlers/implementation/snippet.handler';

export class ImplementationCommandService extends BaseCommandService {
  private snippetHandler: SnippetHandler;

  constructor() {
    super();
    this.snippetHandler = new SnippetHandler();
  }

  async execute(command: string, args: string[]): Promise<string> {
    switch (command) {
      case '/snippet':
        return this.snippetHandler.execute(args);
      default:
        return `Unknown implementation command: ${command}`;
    }
  }

  getCommands(): string[] {
    return ['/snippet'];
  }

  getCategory(): string {
    return 'implementation';
  }
}