/**
 * Visual Input Renderer - Creates chalk-based visual input box
 */
import chalk from 'chalk';
import * as readline from 'readline';

export interface InputBoxConfig {
  width: number;
  height: number;
  title?: string;
  prompt?: string;
  borderStyle: 'single' | 'double' | 'rounded';
  borderColor: string;
  backgroundColor?: string;
  textColor: string;
}

export interface CursorPosition {
  row: number;
  col: number;
}

export class InputRenderer {
  private config: InputBoxConfig;
  private inputBuffer: string = '';
  private cursorPos: CursorPosition = { row: 0, col: 0 };
  private displayStartRow = 0;

  constructor(config: Partial<InputBoxConfig> = {}) {
    this.config = {
      width: 120,
      height: 6,
      title: 'MARIA CLI',
      prompt: 'You: ',
      borderStyle: 'single',
      borderColor: 'white',
      textColor: 'white',
      ...config,
    };
  }

  /**
   * Draw the visual input box with chalk
   */
  drawInputBox(): void {
    const { width, height, title, borderStyle, borderColor } = this.config;
    
    // Clear screen area for the input box
    this.clearInputArea();
    
    // Calculate border characters based on style
    const borders = this.getBorderChars(borderStyle);
    
    // Draw top border with title
    const topBorder = this.createTopBorder(borders, width, title);
    console.log(chalk[borderColor as keyof typeof chalk](topBorder));
    
    // Draw side borders and content area
    for (let i = 0; i < height - 2; i++) {
      const leftBorder = chalk[borderColor as keyof typeof chalk](borders.vertical);
      const rightBorder = chalk[borderColor as keyof typeof chalk](borders.vertical);
      const contentSpace = ' '.repeat(width - 2);
      
      console.log(leftBorder + contentSpace + rightBorder);
    }
    
    // Draw bottom border
    const bottomBorder = borders.bottomLeft + borders.horizontal.repeat(width - 2) + borders.bottomRight;
    console.log(chalk[borderColor as keyof typeof chalk](bottomBorder));
    
    // Position cursor for input
    this.positionCursorForInput();
  }

  /**
   * Get border characters for different styles
   */
  private getBorderChars(style: string) {
    switch (style) {
      case 'double':
        return {
          topLeft: '╔',
          topRight: '╗',
          bottomLeft: '╚',
          bottomRight: '╝',
          horizontal: '═',
          vertical: '║',
          horizontalDown: '╦',
          horizontalUp: '╩',
        };
      case 'rounded':
        return {
          topLeft: '╭',
          topRight: '╮',
          bottomLeft: '╰',
          bottomRight: '╯',
          horizontal: '─',
          vertical: '│',
          horizontalDown: '┬',
          horizontalUp: '┴',
        };
      default: // single
        return {
          topLeft: '┌',
          topRight: '┐',
          bottomLeft: '└',
          bottomRight: '┘',
          horizontal: '─',
          vertical: '│',
          horizontalDown: '┬',
          horizontalUp: '┴',
        };
    }
  }

  /**
   * Create top border with title
   */
  private createTopBorder(borders: any, width: number, title?: string): string {
    if (!title) {
      return borders.topLeft + borders.horizontal.repeat(width - 2) + borders.topRight;
    }
    
    const titleWithPadding = ` ${title} `;
    const titleLength = titleWithPadding.length;
    const availableSpace = width - 2 - titleLength;
    
    if (availableSpace < 0) {
      // Title too long, truncate
      const truncatedTitle = title.substring(0, width - 6) + '...';
      return borders.topLeft + ` ${truncatedTitle} ` + borders.topRight;
    }
    
    const leftPadding = Math.floor(availableSpace / 2);
    const rightPadding = availableSpace - leftPadding;
    
    return (
      borders.topLeft +
      borders.horizontal.repeat(leftPadding) +
      titleWithPadding +
      borders.horizontal.repeat(rightPadding) +
      borders.topRight
    );
  }

  /**
   * Clear the input area on screen
   */
  private clearInputArea(): void {
    // Move cursor up to clear previous input box
    process.stdout.write(`\x1b[${this.config.height}A`);
    // Clear lines
    for (let i = 0; i < this.config.height; i++) {
      process.stdout.write('\x1b[2K'); // Clear entire line
      if (i < this.config.height - 1) {
        process.stdout.write('\n');
      }
    }
    // Move cursor back to top
    process.stdout.write(`\x1b[${this.config.height - 1}A`);
  }

  /**
   * Position cursor for user input inside the box
   */
  private positionCursorForInput(): void {
    const promptLength = this.config.prompt?.length || 0;
    // Move cursor to inside the input box (row 2, after prompt)
    process.stdout.write(`\x1b[2;${2 + promptLength}H`);
    
    // Show the prompt inside the box
    if (this.config.prompt) {
      process.stdout.write(`\x1b[1B\x1b[2C${chalk[this.config.textColor as keyof typeof chalk](this.config.prompt)}`);
      process.stdout.write(`\x1b[1A\x1b[${promptLength + 2}C`);
    }
  }

  /**
   * Handle text input and display within the box
   */
  updateInputDisplay(text: string): void {
    // Clear current input area within box
    const { width, height } = this.config;
    const maxInputWidth = width - 4 - (this.config.prompt?.length || 0);
    const maxInputHeight = height - 3;
    
    // Handle text wrapping within the input box
    const lines = this.wrapText(text, maxInputWidth);
    const visibleLines = lines.slice(this.displayStartRow, this.displayStartRow + maxInputHeight);
    
    // Clear input area within box
    for (let i = 0; i < maxInputHeight; i++) {
      process.stdout.write(`\x1b[${i + 2};3H`); // Move to line i+2, column 3
      process.stdout.write(' '.repeat(maxInputWidth)); // Clear line content
    }
    
    // Display visible lines
    visibleLines.forEach((line, index) => {
      process.stdout.write(`\x1b[${index + 2};${3 + (this.config.prompt?.length || 0)}H`);
      process.stdout.write(chalk[this.config.textColor as keyof typeof chalk](line));
    });
  }

  /**
   * Wrap text to fit within input box width
   */
  private wrapText(text: string, maxWidth: number): string[] {
    const lines: string[] = [];
    const words = text.split(' ');
    let currentLine = '';
    
    for (const word of words) {
      if ((currentLine + word).length <= maxWidth) {
        currentLine += (currentLine ? ' ' : '') + word;
      } else {
        if (currentLine) {
          lines.push(currentLine);
          currentLine = word;
        } else {
          // Word is longer than max width, break it
          lines.push(word.substring(0, maxWidth));
          currentLine = word.substring(maxWidth);
        }
      }
    }
    
    if (currentLine) {
      lines.push(currentLine);
    }
    
    return lines.length ? lines : [''];
  }

  /**
   * Show drag and drop indicator
   */
  showDropIndicator(fileCount: number = 0): void {
    const { width } = this.config;
    const message = fileCount > 0 
      ? `📎 ${fileCount} file(s) attached - Drop more or press Enter to continue`
      : '📎 Drop files/images here or type your message';
    
    // Show indicator at bottom of input box
    const indicatorRow = this.config.height - 1;
    process.stdout.write(`\x1b[${indicatorRow};2H`);
    process.stdout.write(chalk.cyan(message.padEnd(width - 4)));
  }

  /**
   * Hide drag and drop indicator
   */
  hideDropIndicator(): void {
    const { width } = this.config;
    const indicatorRow = this.config.height - 1;
    process.stdout.write(`\x1b[${indicatorRow};2H`);
    process.stdout.write(' '.repeat(width - 4));
  }

  /**
   * Get terminal dimensions
   */
  getTerminalSize(): { width: number; height: number } {
    return {
      width: process.stdout.columns || 120,
      height: process.stdout.rows || 30,
    };
  }

  /**
   * Resize input box to fit terminal
   */
  autoResize(): void {
    const termSize = this.getTerminalSize();
    this.config.width = Math.min(120, termSize.width - 4);
  }
}