/**
 * Dashboard Command - Launch Evolution monitoring dashboard
 * Provides real-time visualization of RL system performance
 */

import { CommandArgs, CommandContext, CommandResult } from '../../types';
import { RLEvolutionEngine } from '../../../services/rl-evolution/RLEvolutionEngine';
import { RealTimeLearning } from '../../../services/rl-evolution/RealTimeLearning';
import { EvolutionReporter } from '../../../services/rl-evolution/EvolutionReporter';
import EvolutionDashboard, { DashboardConfig } from '../../../ui/dashboard/EvolutionDashboard';
import { Logger } from '../../../utils/logger';

export class DashboardCommand {
  private static instance: DashboardCommand;
  private activeDashboard: EvolutionDashboard | null = null;
  
  public static getInstance(): DashboardCommand {
    if (!DashboardCommand.instance) {
      DashboardCommand.instance = new DashboardCommand();
    }
    return DashboardCommand.instance;
  }
  
  async handle(args: CommandArgs, context: CommandContext): Promise<CommandResult> {
    try {
      const subcommand = args.subcommand || 'launch';
      
      switch (subcommand) {
        case 'launch':
        case 'start':
          return await this.launchDashboard(args, context);
          
        case 'stop':
        case 'close':
          return await this.stopDashboard(args, context);
          
        case 'status':
          return await this.getDashboardStatus(args, context);
          
        case 'config':
          return await this.configureDashboard(args, context);
          
        case 'export':
          return await this.exportDashboardData(args, context);
          
        default:
          return {
            success: false,
            message: `Unknown dashboard subcommand: ${subcommand}`,
            data: {
              availableCommands: [
                'launch/start - Launch the evolution dashboard',
                'stop/close - Stop the active dashboard',
                'status - Show dashboard status',
                'config - Configure dashboard settings',
                'export - Export dashboard data',
              ],
            },
          };
      }
    } catch (error: any) {
      Logger.error('Dashboard command failed:', error);
      return {
        success: false,
        message: `Dashboard command failed: ${error.message}`,
        error: error.message,
      };
    }
  }
  
  private async launchDashboard(args: CommandArgs, context: CommandContext): Promise<CommandResult> {
    if (this.activeDashboard) {
      return {
        success: false,
        message: 'Dashboard is already active. Use `/dashboard stop` to close it first.',
        data: {
          status: 'already_active',
        },
      };
    }
    
    try {
      // Get or create RL engine instance
      const rlEngine = await this.getRLEngine(context);
      const evolutionReporter = await this.getEvolutionReporter(context);
      
      // Parse dashboard configuration
      const config = this.parseDashboardConfig(args);
      
      // Create dashboard
      this.activeDashboard = new EvolutionDashboard(
        rlEngine,
        evolutionReporter,
        config
      );
      
      // Set up real-time learning if available
      const realTimeLearning = await this.getRealTimeLearning(context, rlEngine);
      if (realTimeLearning) {
        this.activeDashboard.setRealTimeLearning(realTimeLearning);
      }
      
      // Set up event handlers
      this.setupDashboardEventHandlers();
      
      // Start dashboard
      await this.activeDashboard.start();
      
      Logger.info('Evolution Dashboard launched successfully');
      
      return {
        success: true,
        message: 'Evolution Dashboard launched successfully! Press ESC or Ctrl+C to exit.',
        data: {
          status: 'launched',
          config,
          keyBindings: {
            'ESC/Q/Ctrl+C': 'Exit dashboard',
            'R': 'Refresh now',
            'P': 'Toggle pause',
            'C': 'Clear history',
            'S': 'Export snapshot',
          },
          panels: [
            'Performance Metrics',
            'Context Switches',
            'Real-time Learning',
            'Evolution Progress',
            'Safety Status',
            'Alerts & Notifications',
            'System Logs',
          ],
        },
      };
    } catch (error: any) {
      Logger.error('Failed to launch dashboard:', error);
      return {
        success: false,
        message: `Failed to launch dashboard: ${error.message}`,
        error: error.message,
      };
    }
  }
  
  private async stopDashboard(args: CommandArgs, context: CommandContext): Promise<CommandResult> {
    if (!this.activeDashboard) {
      return {
        success: false,
        message: 'No active dashboard to stop.',
        data: {
          status: 'not_active',
        },
      };
    }
    
    try {
      this.activeDashboard.stop();
      this.activeDashboard = null;
      
      Logger.info('Evolution Dashboard stopped');
      
      return {
        success: true,
        message: 'Evolution Dashboard stopped successfully',
        data: {
          status: 'stopped',
        },
      };
    } catch (error: any) {
      Logger.error('Failed to stop dashboard:', error);
      return {
        success: false,
        message: `Failed to stop dashboard: ${error.message}`,
        error: error.message,
      };
    }
  }
  
  private async getDashboardStatus(args: CommandArgs, context: CommandContext): Promise<CommandResult> {
    const isActive = this.activeDashboard !== null;
    
    if (!isActive) {
      return {
        success: true,
        message: 'No dashboard currently active',
        data: {
          status: 'inactive',
          lastActive: null,
        },
      };
    }
    
    const metrics = this.activeDashboard.getCurrentMetrics();
    const contextSwitchHistory = this.activeDashboard.getContextSwitchHistory();
    
    return {
      success: true,
      message: 'Dashboard is active and monitoring',
      data: {
        status: 'active',
        currentMetrics: metrics,
        recentContextSwitches: contextSwitchHistory.slice(-5),
        panels: {
          performance: '📊 Real-time performance monitoring',
          contextSwitches: '🔄 Context switch overhead tracking',
          realTimeLearning: '⚡ Live learning adaptation',
          evolution: '🧬 RL system evolution progress',
          safety: '🛡️ Safety validation status',
          alerts: '🚨 System alerts and notifications',
          logs: '📝 Detailed system logging',
        },
      },
    };
  }
  
  private async configureDashboard(args: CommandArgs, context: CommandContext): Promise<CommandResult> {
    const config = this.parseDashboardConfig(args);
    
    return {
      success: true,
      message: 'Dashboard configuration updated',
      data: {
        config,
        status: 'configured',
      },
    };
  }
  
  private async exportDashboardData(args: CommandArgs, context: CommandContext): Promise<CommandResult> {
    if (!this.activeDashboard) {
      return {
        success: false,
        message: 'No active dashboard to export data from',
        data: {
          status: 'not_active',
        },
      };
    }
    
    try {
      const format = args.options?.['format'] || 'json';
      const includeHistory = args.options?.['include-history'] !== false;
      
      const exportData = {
        timestamp: new Date(),
        currentMetrics: this.activeDashboard.getCurrentMetrics(),
        contextSwitchHistory: includeHistory 
          ? this.activeDashboard.getContextSwitchHistory() 
          : this.activeDashboard.getContextSwitchHistory().slice(-10),
        exportFormat: format,
        dashboardVersion: '1.0.0',
      };
      
      const filename = `evolution-dashboard-export-${Date.now()}.${format}`;
      
      return {
        success: true,
        message: `Dashboard data exported successfully`,
        data: {
          filename,
          format,
          recordCount: {
            contextSwitches: exportData.contextSwitchHistory.length,
            exportSize: JSON.stringify(exportData).length,
          },
          exportData: format === 'preview' ? exportData : undefined,
        },
      };
    } catch (error: any) {
      Logger.error('Failed to export dashboard data:', error);
      return {
        success: false,
        message: `Failed to export dashboard data: ${error.message}`,
        error: error.message,
      };
    }
  }
  
  private parseDashboardConfig(args: CommandArgs): Partial<DashboardConfig> {
    const config: Partial<DashboardConfig> = {};
    
    if (args.options?.['refresh']) {
      const interval = parseInt(args.options['refresh'] as string, 10);
      if (!isNaN(interval) && interval >= 100) {
        config.refreshInterval = interval;
      }
    }
    
    if (args.options?.['max-data']) {
      const maxData = parseInt(args.options['max-data'] as string, 10);
      if (!isNaN(maxData) && maxData > 0) {
        config.maxDataPoints = maxData;
      }
    }
    
    if (args.options?.['advanced'] !== undefined) {
      config.showAdvancedMetrics = args.options['advanced'] === 'true';
    }
    
    if (args.options?.['alerts'] !== undefined) {
      config.enableAlerts = args.options['alerts'] === 'true';
    }
    
    return config;
  }
  
  private async getRLEngine(context: CommandContext): Promise<RLEvolutionEngine> {
    return new RLEvolutionEngine({
      learningRate: 0.001,
      batchSize: 16,
      replayBufferSize: 1000,
      updateFrequency: 'on-demand',
    });
  }
  
  private async getEvolutionReporter(context: CommandContext): Promise<EvolutionReporter> {
    const reporter = new EvolutionReporter();
    await reporter.initialize();
    return reporter;
  }
  
  private async getRealTimeLearning(context: CommandContext, rlEngine: RLEvolutionEngine): Promise<RealTimeLearning | null> {
    try {
      return new RealTimeLearning(rlEngine, {
        enabled: true,
        mode: 'balanced',
        updateFrequency: 5,
      });
    } catch (error: any) {
      Logger.warn('Could not initialize real-time learning for dashboard:', error.message);
      return null;
    }
  }
  
  private setupDashboardEventHandlers(): void {
    if (!this.activeDashboard) return;
    
    this.activeDashboard.on('stopped', () => {
      Logger.info('Dashboard stopped by user');
      this.activeDashboard = null;
    });
    
    this.activeDashboard.on('error', (error: Error) => {
      Logger.error('Dashboard error:', error);
    });
  }
  
  public getActiveDashboard(): EvolutionDashboard | null {
    return this.activeDashboard;
  }
}

export default DashboardCommand;