  private calculateConvergenceRate(adaptations: AdaptationRecord[]): number {
    return adaptations.length > 0 ? 0.85 : 0;
  }

  private calculateLearningEfficiency(episodes: Episode[], updates: number): number {
    return episodes.length > 0 ? Math.min(1, episodes.length / (updates * 10)) : 0;
  }

  private calculateAdaptationSpeed(adaptations: AdaptationRecord[]): number {
    return adaptations.length > 0 ? 2.5 : 0;
  }

  private calculateLearningStability(improvements: number[]): number {
    if (improvements.length === 0) return 1;
    const variance = improvements.reduce((sum, imp) => sum + Math.pow(imp, 2), 0) / improvements.length;
    return Math.max(0, 1 - Math.sqrt(variance) / 10);
  }

  private findEffectiveTriggers(adaptations: AdaptationRecord[]): string[] {
    const triggers = adaptations.map(a => a.trigger);
    return this.getTopItems(triggers, 3);
  }

  private getTopItems<T>(items: T[], count: number): T[] {
    const counts = new Map<T, number>();
    for (const item of items) {
      counts.set(item, (counts.get(item) || 0) + 1);
    }
    
    return Array.from(counts.entries())
      .sort((a, b) => b[1] - a[1])
      .slice(0, count)
      .map(([item]) => item);
  }

