/**
 * Visual CLI Module Exports
 */

// Core components
export { InputRenderer } from './InputRenderer';
export { FileDropHandler, DroppedFile } from './FileDropHandler';
export { OCRProcessor, OCRResult, OCRWord } from './OCRProcessor';
export { ReferenceManager, Reference, ReferenceMetadata } from './ReferenceManager';
export { ResponseRenderer, ProgressStep } from './ResponseRenderer';

// Main interface
export { EnhancedCLIInterface, EnhancedCLIConfig, CLISession } from './EnhancedCLIInterface';

// Type definitions
export interface VisualCLIOptions {
  enableEnhancedInterface: boolean;
  inputBoxWidth: number;
  enableFileDrops: boolean;
  enableOCR: boolean;
  enableImageAnalysis: boolean;
  autoResize: boolean;
  showProgressReports: boolean;
}

// Default configuration
export const DEFAULT_VISUAL_CLI_CONFIG: VisualCLIOptions = {
  enableEnhancedInterface: true,
  inputBoxWidth: 120,
  enableFileDrops: true,
  enableOCR: true,
  enableImageAnalysis: true,
  autoResize: true,
  showProgressReports: true,
};

// Factory function
export function createEnhancedCLI(maria: any, options: Partial<VisualCLIOptions> = {}) {
  const config = { ...DEFAULT_VISUAL_CLI_CONFIG, ...options };
  
  return new EnhancedCLIInterface(maria, {
    inputBox: {
      width: config.inputBoxWidth,
    },
    enableFileDrops: config.enableFileDrops,
    enableOCR: config.enableOCR,
    enableImageAnalysis: config.enableImageAnalysis,
    autoResize: config.autoResize,
    showProgressReports: config.showProgressReports,
  });
}