/**
 * Linux Intelligence Engine
 * Core intelligence functions for autonomous system administration
 */

export interface SystemState {
  cpuUsage: number;
  memoryUsage: number;
  diskUsage: number;
  activeProcesses: number;
  systemLoad: number[];
  uptime: number;
}

export interface CommandValidation {
  isValid: boolean;
  riskLevel: 'SAFE' | 'LOW' | 'MEDIUM' | 'HIGH' | 'CRITICAL';
  warnings: string[];
  suggestions: string[];
}

export interface UserIntent {
  action: string;
  target: string;
  confidence: number;
  category: string;
}

export interface ExecutionResult {
  success: boolean;
  output: string;
  error?: string;
  metrics: {
    executionTime: number;
    resourceUsage: number;
  };
}

export interface Workflow {
  id: string;
  name: string;
  steps: WorkflowStep[];
  created: Date;
}

export interface WorkflowStep {
  command: string;
  description: string;
  validation: CommandValidation;
}

export class LinuxIntelligenceEngine {
  private learningData: Map<string, any> = new Map();
  private workflows: Map<string, Workflow> = new Map();
  
  /**
   * Analyze user intent from natural language input
   */
  async analyzeUserIntent(input: string): Promise<UserIntent> {
    // Parse natural language to determine intent
    const keywords = {
      file: ['file', 'directory', 'folder', 'path'],
      service: ['service', 'daemon', 'process', 'systemd'],
      network: ['network', 'port', 'connection', 'ip'],
      user: ['user', 'permission', 'group', 'owner'],
      package: ['install', 'package', 'apt', 'yum', 'npm'],
    };
    
    let category = 'general';
    let confidence = 0.5;
    
    for (const [cat, words] of Object.entries(keywords)) {
      if (words.some(word => input.toLowerCase().includes(word))) {
        category = cat;
        confidence = 0.8;
        break;
      }
    }
    
    return {
      action: this.extractAction(input),
      target: this.extractTarget(input),
      confidence,
      category,
    };
  }
  
  /**
   * Assess current system state
   */
  async assessSystemState(): Promise<SystemState> {
    // Mock implementation - in production would use system APIs
    return {
      cpuUsage: Math.random() * 100,
      memoryUsage: Math.random() * 100,
      diskUsage: Math.random() * 100,
      activeProcesses: Math.floor(Math.random() * 500),
      systemLoad: [Math.random() * 4, Math.random() * 4, Math.random() * 4],
      uptime: Date.now() - Math.floor(Math.random() * 86400000),
    };
  }
  
  /**
   * Validate a command for safety and correctness
   */
  async validateCommand(command: string): Promise<CommandValidation> {
    const dangerousPatterns = [
      /rm\s+-rf\s+\//,
      /dd\s+if=.*of=\/dev\//,
      />\s*\/dev\/[^n]/,
      /chmod\s+777/,
      /kill\s+-9\s+1/,
    ];
    
    const warnings: string[] = [];
    let riskLevel: CommandValidation['riskLevel'] = 'SAFE';
    
    for (const pattern of dangerousPatterns) {
      if (pattern.test(command)) {
        warnings.push('Potentially dangerous command detected');
        riskLevel = 'HIGH';
        break;
      }
    }
    
    if (command.includes('sudo')) {
      warnings.push('Elevated privileges required');
      if (riskLevel === 'SAFE') riskLevel = 'MEDIUM';
    }

    // Check for truly critical commands
    if (command.includes('rm -rf /') && !command.includes('/tmp')) {
      riskLevel = 'CRITICAL';
      warnings.push('CRITICAL: This command could destroy the system');
    }
    
    return {
      isValid: riskLevel !== 'CRITICAL',
      riskLevel,
      warnings,
      suggestions: this.generateSuggestions(command),
    };
  }
  
  /**
   * Execute command with intelligence and monitoring
   */
  async executeWithIntelligence(command: string): Promise<ExecutionResult> {
    const startTime = Date.now();
    
    // Validate before execution
    const validation = await this.validateCommand(command);
    if (!validation.isValid || validation.riskLevel === 'CRITICAL') {
      return {
        success: false,
        output: '',
        error: 'Command validation failed: ' + validation.warnings.join(', '),
        metrics: {
          executionTime: 0,
          resourceUsage: 0,
        },
      };
    }
    
    // Mock execution - in production would use child_process
    const success = Math.random() > 0.2;
    
    return {
      success,
      output: success ? `Command executed: ${command}` : '',
      error: success ? undefined : 'Command failed',
      metrics: {
        executionTime: Date.now() - startTime,
        resourceUsage: Math.random() * 100,
      },
    };
  }
  
  /**
   * Create backup before risky operations
   */
  async createBackup(target: string): Promise<boolean> {
    // Mock backup creation
    console.log(`Creating backup of ${target}`);
    this.learningData.set(`backup_${Date.now()}`, {
      target,
      timestamp: new Date(),
      type: 'automatic',
    });
    return true;
  }
  
  /**
   * Learn from command execution results
   */
  async learnFromExecution(command: string, result: ExecutionResult): Promise<void> {
    const learningEntry = {
      command,
      success: result.success,
      executionTime: result.metrics.executionTime,
      resourceUsage: result.metrics.resourceUsage,
      timestamp: new Date(),
    };
    
    // Store learning data
    const history = this.learningData.get('execution_history') || [];
    history.push(learningEntry);
    this.learningData.set('execution_history', history);
    
    // Update patterns
    if (result.success) {
      const successPatterns = this.learningData.get('success_patterns') || [];
      successPatterns.push(command);
      this.learningData.set('success_patterns', successPatterns);
    }
  }
  
  /**
   * Create workflow from command sequence
   */
  async createWorkflow(name: string, commands: string[]): Promise<Workflow> {
    const workflow: Workflow = {
      id: `workflow_${Date.now()}`,
      name,
      steps: [],
      created: new Date(),
    };
    
    for (const command of commands) {
      const validation = await this.validateCommand(command);
      workflow.steps.push({
        command,
        description: this.generateDescription(command),
        validation,
      });
    }
    
    this.workflows.set(workflow.id, workflow);
    return workflow;
  }
  
  /**
   * Analyze command for intelligence insights
   */
  async analyzeCommand(command: string): Promise<any> {
    const intent = await this.analyzeUserIntent(command);
    const validation = await this.validateCommand(command);
    const systemState = await this.assessSystemState();
    
    return {
      command,
      intent,
      validation,
      systemState,
      recommendations: this.generateRecommendations(command, systemState),
      alternatives: this.generateAlternatives(command),
    };
  }
  
  // Helper methods
  private extractAction(input: string): string {
    const actions = ['create', 'delete', 'modify', 'list', 'show', 'install', 'remove'];
    for (const action of actions) {
      if (input.toLowerCase().includes(action)) {
        return action;
      }
    }
    return 'unknown';
  }
  
  private extractTarget(input: string): string {
    // Simple extraction - in production would use NLP
    const words = input.split(' ');
    return words[words.length - 1] || 'unknown';
  }
  
  private generateSuggestions(command: string): string[] {
    const suggestions: string[] = [];
    
    if (command.includes('rm') && !command.includes('-i')) {
      suggestions.push('Consider using -i flag for interactive confirmation');
    }
    
    if (command.includes('chmod 777')) {
      suggestions.push('Consider more restrictive permissions like 755 or 644');
    }
    
    return suggestions;
  }
  
  private generateDescription(command: string): string {
    if (command.startsWith('ls')) return 'List directory contents';
    if (command.startsWith('cd')) return 'Change directory';
    if (command.startsWith('mkdir')) return 'Create directory';
    if (command.startsWith('rm')) return 'Remove file or directory';
    return 'Execute system command';
  }
  
  private generateRecommendations(_command: string, state: SystemState): string[] {
    const recommendations: string[] = [];
    
    if (state.memoryUsage > 80) {
      recommendations.push('High memory usage detected - consider freeing resources');
    }
    
    if (state.diskUsage > 90) {
      recommendations.push('Low disk space - clean up unnecessary files');
    }
    
    return recommendations;
  }
  
  private generateAlternatives(command: string): string[] {
    const alternatives: string[] = [];
    
    if (command.includes('find')) {
      alternatives.push('Consider using locate for faster searches');
    }
    
    if (command.includes('grep') && !command.includes('rg')) {
      alternatives.push('Consider using ripgrep (rg) for faster searching');
    }
    
    return alternatives;
  }
}

// Export singleton instance
export const linuxIntelligence = new LinuxIntelligenceEngine();

// Export individual functions for compatibility
export const analyzeUserIntent = (input: string) => linuxIntelligence.analyzeUserIntent(input);
export const assessSystemState = () => linuxIntelligence.assessSystemState();
export const validateCommand = (command: string) => linuxIntelligence.validateCommand(command);
export const executeWithIntelligence = (command: string) => linuxIntelligence.executeWithIntelligence(command);
export const createBackup = (target: string) => linuxIntelligence.createBackup(target);
export const learnFromExecution = (command: string, result: ExecutionResult) => linuxIntelligence.learnFromExecution(command, result);
export const createWorkflow = (name: string, commands: string[]) => linuxIntelligence.createWorkflow(name, commands);
export const analyzeCommand = (command: string) => linuxIntelligence.analyzeCommand(command);