/**
 * Status Command
 * Display comprehensive system status and health information
 */

import { BaseCommand } from '../../../base-command';
import { CommandArgs, CommandContext, CommandResult, CommandExample } from '../../../types';
import { logger } from '../../../../utils/logger';
import * as fs from 'fs/promises';
import * as path from 'path';
import * as os from 'os';

interface SystemStatus {
  system: {
    platform: string;
    architecture: string;
    nodeVersion: string;
    uptime: string;
    hostname: string;
  };
  resources: {
    memory: {
      used: string;
      total: string;
      percentage: string;
      available: string;
    };
    cpu: {
      cores: number;
      model: string;
      usage?: string;
    };
    disk: {
      cwd: string;
      available?: string;
    };
  };
  maria: {
    version: string;
    workingDirectory: string;
    configFiles: {
      packageJson: boolean;
      envLocal: boolean;
      mariaConfig: boolean;
      gitRepository: boolean;
    };
    services: {
      slashCommands: {
        registered: number;
        categories: string[];
      };
    };
  };
  network: {
    connectivity: boolean;
    hostname: string;
  };
  lastUpdated: string;
}

export class StatusCommand extends BaseCommand {
  name = 'status';
  category = 'system' as const;
  description = '📊 Display comprehensive system status and health information';
  override aliases = ['st', 'info', 'sys'];
  override usage = '[--detailed] [--json] [--refresh] [--services] [--resources]';

  override examples: CommandExample[] = [
    {
      input: '/status',
      description: 'Show basic system status overview',
      output: 'System health summary with key metrics',
    },
    {
      input: '/status --detailed',
      description: 'Show detailed system information',
      output: 'Comprehensive system report with all metrics',
    },
    {
      input: '/status --json',
      description: 'Output status in JSON format',
      output: 'Machine-readable status data',
    },
    {
      input: '/status --services',
      description: 'Focus on service status information',
      output: 'Service health and registration details',
    },
    {
      input: '/status --resources',
      description: 'Focus on system resource usage',
      output: 'Memory, CPU, and disk usage details',
    },
  ];

  private statusCache: SystemStatus | null = null;
  private cacheExpiry: number = 0;

  async execute(args: CommandArgs, context: CommandContext): Promise<CommandResult> {
    try {
      const { flags } = args;

      logger.info('Status command executed', {
        user: context.user?.id,
        session: context.session.id,
        flags,
      });

      // Force refresh if requested
      if (flags['refresh']) {
        this.statusCache = null;
        this.cacheExpiry = 0;
      }

      // Get comprehensive status
      const status = await this.getSystemStatus(context);

      // Handle different output formats
      if (flags['json']) {
        return this.success('System status (JSON format)', status);
      }

      if (flags['detailed']) {
        return this.showDetailedStatus(status);
      }

      if (flags['services']) {
        return this.showServicesStatus(status);
      }

      if (flags['resources']) {
        return this.showResourcesStatus(status);
      }

      // Default: show basic status
      return this.showBasicStatus(status);

    } catch (error) {
      logger.error('Status command failed:', error);
      return this.error(
        'Failed to retrieve system status',
        'STATUS_ERROR',
        error instanceof Error ? error.message : 'Unknown error'
      );
    }
  }

  /**
   * Get comprehensive system status
   */
  private async getSystemStatus(context: CommandContext): Promise<SystemStatus> {
    // Use cached status if still valid (cache for 30 seconds)
    if (this.statusCache && Date.now() < this.cacheExpiry) {
      return this.statusCache;
    }

    try {
      const [systemInfo, resourceInfo, mariaInfo, networkInfo] = await Promise.all([
        this.getSystemInfo(),
        this.getResourceInfo(),
        this.getMariaInfo(context),
        this.getNetworkInfo(),
      ]);

      const status: SystemStatus = {
        system: systemInfo,
        resources: resourceInfo,
        maria: mariaInfo,
        network: networkInfo,
        lastUpdated: new Date().toISOString(),
      };

      // Cache the result
      this.statusCache = status;
      this.cacheExpiry = Date.now() + 30000; // 30 seconds cache

      return status;
    } catch (error) {
      logger.error('Failed to gather system status:', error);
      throw error;
    }
  }

  /**
   * Get basic system information
   */
  private async getSystemInfo() {
    return {
      platform: `${os.platform()} ${os.release()}`,
      architecture: os.arch(),
      nodeVersion: process.version,
      uptime: this.formatUptime(os.uptime()),
      hostname: os.hostname(),
    };
  }

  /**
   * Get system resource information
   */
  private async getResourceInfo() {
    const totalMem = os.totalmem();
    const freeMem = os.freemem();
    const usedMem = totalMem - freeMem;

    const cpus = os.cpus();

    return {
      memory: {
        used: this.formatBytes(usedMem),
        total: this.formatBytes(totalMem),
        available: this.formatBytes(freeMem),
        percentage: ((usedMem / totalMem) * 100).toFixed(1) + '%',
      },
      cpu: {
        cores: cpus.length,
        model: cpus[0]?.model || 'Unknown',
      },
      disk: {
        cwd: process.cwd(),
        // Disk usage would require additional system calls
      },
    };
  }

  /**
   * Get MARIA-specific information
   */
  private async getMariaInfo(context: CommandContext) {
    const cwd = context.environment.cwd;
    
    // Check for configuration files
    const configFiles = {
      packageJson: await this.fileExists(path.join(cwd, 'package.json')),
      envLocal: await this.fileExists(path.join(cwd, '.env.local')),
      mariaConfig: await this.fileExists(path.join(cwd, '.maria-code.toml')),
      gitRepository: await this.fileExists(path.join(cwd, '.git')),
    };

    // Get version from package.json
    let version = 'Unknown';
    try {
      const packagePath = path.join(cwd, 'package.json');
      const packageContent = await fs.readFile(packagePath, 'utf-8');
      const packageInfo = JSON.parse(packageContent);
      version = packageInfo.version || 'Unknown';
    } catch {
      // Ignore if package.json doesn't exist
    }

    // Get slash command information
    const { commandRegistry } = await import('../../../registry');
    const commands = commandRegistry.getAll();
    const categories = new Set(commands.map(cmd => cmd.category));

    return {
      version,
      workingDirectory: cwd,
      configFiles,
      services: {
        slashCommands: {
          registered: commands.length,
          categories: Array.from(categories).sort(),
        },
      },
    };
  }

  /**
   * Get network information
   */
  private async getNetworkInfo() {
    return {
      connectivity: true, // Basic assumption - would need actual network test
      hostname: os.hostname(),
    };
  }

  /**
   * Show basic status overview
   */
  private showBasicStatus(status: SystemStatus): CommandResult {
    const lines: string[] = [];

    lines.push('');
    lines.push('📊 **MARIA SYSTEM STATUS**');
    lines.push('═'.repeat(40));
    lines.push('');

    // System Health Indicator
    const healthIndicator = this.getHealthIndicator(status);
    lines.push(`**Overall Health:** ${healthIndicator}`);
    lines.push('');

    // Key Metrics
    lines.push('**🖥️ System:**');
    lines.push(`  Platform: ${status.system.platform}`);
    lines.push(`  Node.js: ${status.system.nodeVersion}`);
    lines.push(`  Uptime: ${status.system.uptime}`);
    lines.push('');

    lines.push('**💾 Resources:**');
    lines.push(`  Memory: ${status.resources.memory.used}/${status.resources.memory.total} (${status.resources.memory.percentage})`);
    lines.push(`  CPU: ${status.resources.cpu.cores} cores`);
    lines.push('');

    lines.push('**🚀 MARIA:**');
    lines.push(`  Version: ${status.maria.version}`);
    lines.push(`  Commands: ${status.maria.services.slashCommands.registered} registered`);
    lines.push(`  Categories: ${status.maria.services.slashCommands.categories.join(', ')}`);
    lines.push('');

    lines.push(`*Last updated: ${new Date(status.lastUpdated).toLocaleTimeString()}*`);
    lines.push('');
    lines.push('💡 Use `/status --detailed` for more information');
    lines.push('');

    return this.success(lines.join('\n'), {
      health: healthIndicator,
      type: 'basic',
      summary: {
        commands: status.maria.services.slashCommands.registered,
        memory: status.resources.memory.percentage,
        version: status.maria.version,
      },
    });
  }

  /**
   * Show detailed system status
   */
  private showDetailedStatus(status: SystemStatus): CommandResult {
    const lines: string[] = [];

    lines.push('');
    lines.push('📊 **DETAILED SYSTEM STATUS**');
    lines.push('═'.repeat(60));
    lines.push('');

    // Overall Health
    const healthIndicator = this.getHealthIndicator(status);
    lines.push(`**Overall Health:** ${healthIndicator}`);
    lines.push('');

    // System Information
    lines.push('**🖥️ System Information:**');
    lines.push(`  Platform: ${status.system.platform}`);
    lines.push(`  Architecture: ${status.system.architecture}`);
    lines.push(`  Hostname: ${status.system.hostname}`);
    lines.push(`  Node.js: ${status.system.nodeVersion}`);
    lines.push(`  System Uptime: ${status.system.uptime}`);
    lines.push('');

    // Resource Usage
    lines.push('**📈 Resource Usage:**');
    lines.push(`  Memory Used: ${status.resources.memory.used} (${status.resources.memory.percentage})`);
    lines.push(`  Memory Available: ${status.resources.memory.available}`);
    lines.push(`  Memory Total: ${status.resources.memory.total}`);
    lines.push(`  CPU Cores: ${status.resources.cpu.cores}`);
    lines.push(`  CPU Model: ${status.resources.cpu.model}`);
    lines.push('');

    // MARIA Configuration
    lines.push('**🚀 MARIA Configuration:**');
    lines.push(`  Version: ${status.maria.version}`);
    lines.push(`  Working Directory: ${status.maria.workingDirectory}`);
    lines.push('');

    lines.push('**📁 Configuration Files:**');
    lines.push(`  package.json: ${status.maria.configFiles.packageJson ? '✅ Found' : '❌ Missing'}`);
    lines.push(`  .env.local: ${status.maria.configFiles.envLocal ? '✅ Found' : '❌ Missing'}`);
    lines.push(`  .maria-code.toml: ${status.maria.configFiles.mariaConfig ? '✅ Found' : '❌ Missing'}`);
    lines.push(`  Git Repository: ${status.maria.configFiles.gitRepository ? '✅ Detected' : '❌ Not found'}`);
    lines.push('');

    // Services Status
    lines.push('**⚙️ Services Status:**');
    lines.push(`  Slash Commands: ${status.maria.services.slashCommands.registered} registered`);
    lines.push(`  Command Categories: ${status.maria.services.slashCommands.categories.join(', ')}`);
    lines.push('');

    // Network
    lines.push('**🌐 Network:**');
    lines.push(`  Connectivity: ${status.network.connectivity ? '✅ Online' : '❌ Offline'}`);
    lines.push(`  Hostname: ${status.network.hostname}`);
    lines.push('');

    lines.push(`**🕒 Last Updated:** ${new Date(status.lastUpdated).toLocaleString()}`);
    lines.push('');

    return this.success(lines.join('\n'), {
      ...status,
      type: 'detailed',
      health: healthIndicator,
    });
  }

  /**
   * Show services-focused status
   */
  private showServicesStatus(status: SystemStatus): CommandResult {
    const lines: string[] = [];

    lines.push('');
    lines.push('⚙️ **SERVICES STATUS**');
    lines.push('═'.repeat(40));
    lines.push('');

    lines.push('**🔧 Slash Commands Service:**');
    lines.push(`  Status: ✅ Active`);
    lines.push(`  Registered Commands: ${status.maria.services.slashCommands.registered}`);
    lines.push(`  Categories: ${status.maria.services.slashCommands.categories.length}`);
    lines.push('');

    lines.push('**📋 Command Categories:**');
    for (const category of status.maria.services.slashCommands.categories) {
      lines.push(`  • ${category}`);
    }
    lines.push('');

    lines.push('**📁 Configuration Status:**');
    lines.push(`  Environment: ${status.maria.configFiles.envLocal ? '✅ Configured' : '⚠️ Missing'}`);
    lines.push(`  Project Config: ${status.maria.configFiles.mariaConfig ? '✅ Configured' : '⚠️ Missing'}`);
    lines.push(`  Git Integration: ${status.maria.configFiles.gitRepository ? '✅ Available' : '❌ Not available'}`);
    lines.push('');

    return this.success(lines.join('\n'), {
      services: status.maria.services,
      configFiles: status.maria.configFiles,
      type: 'services',
    });
  }

  /**
   * Show resources-focused status
   */
  private showResourcesStatus(status: SystemStatus): CommandResult {
    const lines: string[] = [];

    lines.push('');
    lines.push('📈 **SYSTEM RESOURCES**');
    lines.push('═'.repeat(40));
    lines.push('');

    lines.push('**💾 Memory Usage:**');
    lines.push(`  Used: ${status.resources.memory.used}`);
    lines.push(`  Available: ${status.resources.memory.available}`);
    lines.push(`  Total: ${status.resources.memory.total}`);
    lines.push(`  Usage: ${status.resources.memory.percentage}`);
    lines.push('');

    lines.push('**🖥️ CPU Information:**');
    lines.push(`  Cores: ${status.resources.cpu.cores}`);
    lines.push(`  Model: ${status.resources.cpu.model}`);
    lines.push('');

    lines.push('**💽 System:**');
    lines.push(`  Platform: ${status.system.platform}`);
    lines.push(`  Architecture: ${status.system.architecture}`);
    lines.push(`  Uptime: ${status.system.uptime}`);
    lines.push('');

    return this.success(lines.join('\n'), {
      resources: status.resources,
      system: status.system,
      type: 'resources',
    });
  }

  /**
   * Get overall health indicator
   */
  private getHealthIndicator(status: SystemStatus): string {
    const indicators: string[] = [];

    // Memory usage check
    const memoryPercentage = parseFloat(status.resources.memory.percentage.replace('%', ''));
    if (memoryPercentage < 70) {
      indicators.push('✅ Memory');
    } else if (memoryPercentage < 85) {
      indicators.push('⚠️ Memory');
    } else {
      indicators.push('❌ Memory');
    }

    // Services check
    if (status.maria.services.slashCommands.registered > 0) {
      indicators.push('✅ Services');
    } else {
      indicators.push('❌ Services');
    }

    // Configuration check
    const configScore = Object.values(status.maria.configFiles).filter(Boolean).length;
    if (configScore >= 3) {
      indicators.push('✅ Config');
    } else if (configScore >= 2) {
      indicators.push('⚠️ Config');
    } else {
      indicators.push('❌ Config');
    }

    return indicators.join(' ');
  }

  /**
   * Helper methods
   */
  private formatUptime(seconds: number): string {
    const days = Math.floor(seconds / 86400);
    const hours = Math.floor((seconds % 86400) / 3600);
    const minutes = Math.floor((seconds % 3600) / 60);

    const parts: string[] = [];
    if (days > 0) parts.push(`${days}d`);
    if (hours > 0) parts.push(`${hours}h`);
    if (minutes > 0) parts.push(`${minutes}m`);
    if (parts.length === 0) parts.push('<1m');

    return parts.join(' ');
  }

  private formatBytes(bytes: number): string {
    const sizes = ['B', 'KB', 'MB', 'GB', 'TB'];
    if (bytes === 0) return '0 B';
    const i = Math.floor(Math.log(bytes) / Math.log(1024));
    return `${(bytes / Math.pow(1024, i)).toFixed(1)} ${sizes[i]}`;
  }

  private async fileExists(filePath: string): Promise<boolean> {
    try {
      await fs.access(filePath);
      return true;
    } catch {
      return false;
    }
  }

  /**
   * Validation for status command
   */
  override async validate(args: CommandArgs): Promise<{ success: boolean; error?: string }> {
    const { parsed } = args;
    const positional = (parsed['positional'] as string[]) || [];

    // Status command doesn't accept positional arguments
    if (positional.length > 0) {
      return {
        success: false,
        error: `Unexpected arguments: ${positional.join(', ')}. Use flags like --detailed instead.`,
      };
    }

    return { success: true };
  }
}