import { SlashCommandCategory, SlashCommand } from '../../../types/slash-commands';
import { DashboardEngine } from '../../../services/cli-native/monitoring/dashboard-engine';
import { RealTimeStreamingSystem } from '../../../services/cli-native/monitoring/real-time-streaming';
import { MonitoringWebSocketServer, WebSocketConfig } from '../../../services/cli-native/monitoring/websocket-server';
import { DashboardTemplateLibrary } from '../../../services/cli-native/monitoring/dashboard-templates';
import { ASCIIChartRenderer, HTMLChartRenderer } from '../../../services/cli-native/monitoring/visualization-components';

export interface MonitoringCommandOptions {
  format?: 'ascii' | 'html' | 'json';
  refresh?: number;
  filter?: string;
  template?: string;
  port?: number;
  auth?: boolean;
}

export class MonitoringCommands implements SlashCommandCategory {
  private dashboardEngine: DashboardEngine;
  private streamingSystem: RealTimeStreamingSystem;
  private websocketServer: MonitoringWebSocketServer | null = null;
  private templateLibrary: DashboardTemplateLibrary;
  private asciiRenderer: ASCIIChartRenderer;
  private htmlRenderer: HTMLChartRenderer;

  constructor() {
    this.dashboardEngine = new DashboardEngine();
    this.streamingSystem = new RealTimeStreamingSystem();
    this.templateLibrary = new DashboardTemplateLibrary();
    this.asciiRenderer = new ASCIIChartRenderer();
    this.htmlRenderer = new HTMLChartRenderer();
  }

  getCommands(): SlashCommand[] {
    return [
      {
        name: 'monitor',
        description: 'Start real-time monitoring dashboard',
        category: 'monitoring',
        usage: '/monitor [options]',
        examples: [
          '/monitor --format ascii --refresh 5',
          '/monitor system --template system-overview',
          '/monitor --port 3001 --auth'
        ],
        handler: this.handleMonitor.bind(this),
        options: {
          format: 'Output format (ascii, html, json)',
          refresh: 'Refresh interval in seconds',
          template: 'Dashboard template to use',
          filter: 'Filter data by pattern',
          port: 'WebSocket server port',
          auth: 'Enable authentication'
        }
      },
      {
        name: 'dashboard',
        description: 'Create and manage monitoring dashboards',
        category: 'monitoring',
        usage: '/dashboard <action> [options]',
        examples: [
          '/dashboard create --template system-overview',
          '/dashboard list',
          '/dashboard show my-dashboard --format html',
          '/dashboard export my-dashboard'
        ],
        handler: this.handleDashboard.bind(this),
        options: {
          template: 'Template to use for creation',
          format: 'Display format',
          name: 'Dashboard name',
          config: 'Configuration file path'
        }
      },
      {
        name: 'stream',
        description: 'Manage real-time data streams',
        category: 'monitoring',
        usage: '/stream <action> [channel] [options]',
        examples: [
          '/stream start system:metrics',
          '/stream list',
          '/stream subscribe app:logs --filter error',
          '/stream stop system:metrics'
        ],
        handler: this.handleStream.bind(this),
        options: {
          filter: 'Filter stream data',
          format: 'Output format',
          rate: 'Rate limit (messages/second)'
        }
      },
      {
        name: 'websocket',
        description: 'Control WebSocket monitoring server',
        category: 'monitoring',
        usage: '/websocket <action> [options]',
        examples: [
          '/websocket start --port 3001',
          '/websocket stop',
          '/websocket status',
          '/websocket clients'
        ],
        handler: this.handleWebSocket.bind(this),
        options: {
          port: 'Server port number',
          host: 'Server host address',
          auth: 'Enable authentication',
          maxConnections: 'Maximum client connections'
        }
      },
      {
        name: 'chart',
        description: 'Create and display charts from data',
        category: 'monitoring',
        usage: '/chart <type> [data] [options]',
        examples: [
          '/chart line --data "./metrics.json" --format ascii',
          '/chart bar --data "cpu,memory,disk" --format html',
          '/chart gauge system.cpu --threshold 80'
        ],
        handler: this.handleChart.bind(this),
        options: {
          data: 'Data source or values',
          format: 'Output format (ascii, html)',
          title: 'Chart title',
          width: 'Chart width',
          height: 'Chart height',
          theme: 'Color theme'
        }
      },
      {
        name: 'templates',
        description: 'Manage dashboard templates',
        category: 'monitoring',
        usage: '/templates <action> [options]',
        examples: [
          '/templates list',
          '/templates show system-overview',
          '/templates create --name my-template',
          '/templates generate --from-data metrics.json'
        ],
        handler: this.handleTemplates.bind(this),
        options: {
          name: 'Template name',
          category: 'Template category',
          fromData: 'Generate from data source'
        }
      }
    ];
  }

  private async handleMonitor(args: string[], options: MonitoringCommandOptions = {}): Promise<string> {
    try {
      const format = options.format || 'ascii';
      const refresh = options.refresh || 5;
      const template = options.template || 'system-overview';

      // Start WebSocket server if not running and port specified
      if (options.port && !this.websocketServer?.isRunning()) {
        const wsConfig: WebSocketConfig = {
          port: options.port,
          auth: options.auth ? { enabled: true } : { enabled: false }
        };
        
        this.websocketServer = new MonitoringWebSocketServer(wsConfig, this.streamingSystem, this.dashboardEngine);
        await this.websocketServer.start();
      }

      // Create dashboard from template
      const dashboardConfig = await this.templateLibrary.getTemplate(template);
      if (!dashboardConfig) {
        return `❌ Template '${template}' not found. Use /templates list to see available templates.`;
      }

      // Load dashboard
      await this.dashboardEngine.loadDashboard('monitor-session', dashboardConfig);
      
      // Start streaming data
      const channels = this.extractChannelsFromDashboard(dashboardConfig);
      for (const channel of channels) {
        await this.streamingSystem.startStream(channel, {
          source: 'system',
          format: 'json',
          interval: refresh * 1000
        });
      }

      const output = await this.dashboardEngine.renderDashboard('monitor-session', format.toUpperCase() as any);
      
      let result = `🖥️  Real-time monitoring started\n`;
      result += `📊 Template: ${template}\n`;
      result += `🔄 Refresh: ${refresh}s\n`;
      result += `📝 Format: ${format}\n`;
      
      if (this.websocketServer?.isRunning()) {
        result += `🌐 WebSocket: ws://localhost:${options.port}/ws\n`;
      }
      
      result += `\n${output}`;
      return result;

    } catch (error) {
      return `❌ Failed to start monitoring: ${error}`;
    }
  }

  private async handleDashboard(args: string[], options: MonitoringCommandOptions = {}): Promise<string> {
    const action = args[0];
    
    try {
      switch (action) {
        case 'create': {
          const name = args[1] || options.template || `dashboard-${Date.now()}`;
          const template = options.template || 'system-overview';
          
          const templateConfig = await this.templateLibrary.getTemplate(template);
          if (!templateConfig) {
            return `❌ Template '${template}' not found`;
          }

          await this.dashboardEngine.loadDashboard(name, templateConfig);
          return `✅ Dashboard '${name}' created from template '${template}'`;
        }

        case 'list': {
          const dashboards = this.dashboardEngine.listDashboards();
          if (dashboards.length === 0) {
            return '📭 No dashboards found';
          }
          
          let result = '📊 Available Dashboards:\n';
          dashboards.forEach(dashboard => {
            result += `• ${dashboard.id} - ${dashboard.title}\n`;
          });
          return result;
        }

        case 'show': {
          const dashboardId = args[1];
          if (!dashboardId) {
            return '❌ Dashboard ID required. Use /dashboard list to see available dashboards.';
          }

          const format = (options.format || 'ascii').toUpperCase() as any;
          const output = await this.dashboardEngine.renderDashboard(dashboardId, format);
          
          return `📊 Dashboard: ${dashboardId}\n\n${output}`;
        }

        case 'export': {
          const dashboardId = args[1];
          if (!dashboardId) {
            return '❌ Dashboard ID required';
          }

          const config = this.dashboardEngine.getDashboardConfig(dashboardId);
          if (!config) {
            return `❌ Dashboard '${dashboardId}' not found`;
          }

          return `📄 Dashboard Configuration:\n\n\`\`\`json\n${JSON.stringify(config, null, 2)}\n\`\`\``;
        }

        default:
          return '❌ Unknown dashboard action. Use: create, list, show, export';
      }
    } catch (error) {
      return `❌ Dashboard operation failed: ${error}`;
    }
  }

  private async handleStream(args: string[], options: MonitoringCommandOptions = {}): Promise<string> {
    const action = args[0];
    const channel = args[1];

    try {
      switch (action) {
        case 'start': {
          if (!channel) {
            return '❌ Channel name required';
          }

          await this.streamingSystem.startStream(channel, {
            source: 'system',
            format: 'json',
            interval: 5000,
            filter: options.filter
          });

          return `🚀 Stream started for channel '${channel}'`;
        }

        case 'stop': {
          if (!channel) {
            return '❌ Channel name required';
          }

          await this.streamingSystem.stopStream(channel);
          return `⏹️  Stream stopped for channel '${channel}'`;
        }

        case 'list': {
          const streams = this.streamingSystem.getActiveStreams();
          if (streams.length === 0) {
            return '📭 No active streams';
          }

          let result = '🌊 Active Streams:\n';
          streams.forEach(stream => {
            result += `• ${stream.channel} (${stream.subscribers} subscribers)\n`;
          });
          return result;
        }

        case 'subscribe': {
          if (!channel) {
            return '❌ Channel name required';
          }

          await this.streamingSystem.subscribe({
            clientId: `cli-${Date.now()}`,
            channel,
            filters: options.filter ? { pattern: options.filter } : {},
            callback: (data) => {
              console.log(`📡 ${channel}:`, JSON.stringify(data, null, 2));
            }
          });

          return `✅ Subscribed to channel '${channel}'`;
        }

        default:
          return '❌ Unknown stream action. Use: start, stop, list, subscribe';
      }
    } catch (error) {
      return `❌ Stream operation failed: ${error}`;
    }
  }

  private async handleWebSocket(args: string[], options: MonitoringCommandOptions = {}): Promise<string> {
    const action = args[0];

    try {
      switch (action) {
        case 'start': {
          if (this.websocketServer?.isRunning()) {
            return '⚠️  WebSocket server is already running';
          }

          const config: WebSocketConfig = {
            port: options.port || 3001,
            host: 'localhost',
            auth: options.auth ? { enabled: true } : { enabled: false },
            maxConnections: 100
          };

          this.websocketServer = new MonitoringWebSocketServer(config, this.streamingSystem, this.dashboardEngine);
          await this.websocketServer.start();

          return `🌐 WebSocket server started on ws://localhost:${config.port}/ws`;
        }

        case 'stop': {
          if (!this.websocketServer?.isRunning()) {
            return '⚠️  WebSocket server is not running';
          }

          await this.websocketServer.stop();
          return '⏹️  WebSocket server stopped';
        }

        case 'status': {
          if (!this.websocketServer) {
            return '❌ WebSocket server not initialized';
          }

          const isRunning = this.websocketServer.getIsRunning();
          const clientCount = this.websocketServer.getClientCount();
          const channels = this.websocketServer.getChannels();

          let result = `🌐 WebSocket Server Status: ${isRunning ? '🟢 Running' : '🔴 Stopped'}\n`;
          result += `👥 Connected Clients: ${clientCount}\n`;
          result += `📡 Active Channels: ${channels.length}\n`;
          
          if (channels.length > 0) {
            result += `📋 Channels: ${channels.join(', ')}\n`;
          }

          return result;
        }

        case 'clients': {
          if (!this.websocketServer) {
            return '❌ WebSocket server not initialized';
          }

          const clients = this.websocketServer.getConnectedClients();
          if (clients.length === 0) {
            return '📭 No connected clients';
          }

          let result = '👥 Connected Clients:\n';
          clients.forEach(client => {
            result += `• ${client.id} - ${client.metadata.ipAddress} (${client.subscriptions.size} subscriptions)\n`;
            result += `  Connected: ${client.metadata.connectedAt.toISOString()}\n`;
            result += `  Last Activity: ${client.metadata.lastActivity.toISOString()}\n`;
          });

          return result;
        }

        default:
          return '❌ Unknown WebSocket action. Use: start, stop, status, clients';
      }
    } catch (error) {
      return `❌ WebSocket operation failed: ${error}`;
    }
  }

  private async handleChart(args: string[], options: MonitoringCommandOptions = {}): Promise<string> {
    const chartType = args[0];
    const dataSource = args[1] || options.data;

    if (!chartType) {
      return '❌ Chart type required. Use: line, bar, gauge, heatmap, histogram';
    }

    try {
      // Parse data source
      let data: number[] | number[][] = [];
      if (dataSource) {
        if (dataSource.startsWith('./') || dataSource.startsWith('/')) {
          // File path - would need to implement file reading
          return '❌ File data sources not yet implemented';
        } else {
          // Comma-separated values or live data
          data = dataSource.split(',').map(v => parseFloat(v.trim())).filter(v => !isNaN(v));
        }
      } else {
        // Generate sample data for demonstration
        data = Array.from({ length: 20 }, () => Math.random() * 100);
      }

      const format = options.format || 'ascii';
      const config = {
        title: chartType.charAt(0).toUpperCase() + chartType.slice(1) + ' Chart',
        width: 80,
        height: 20,
        theme: 'default' as any
      };

      let output: string;
      if (format === 'html') {
        output = await this.htmlRenderer.renderChart(chartType as any, data as any, config);
      } else {
        output = this.asciiRenderer.renderChart(chartType as any, data as any, config);
      }

      return `📊 ${config.title}\n\n${output}`;
    } catch (error) {
      return `❌ Chart creation failed: ${error}`;
    }
  }

  private async handleTemplates(args: string[], options: MonitoringCommandOptions = {}): Promise<string> {
    const action = args[0];

    try {
      switch (action) {
        case 'list': {
          const templates = this.templateLibrary.listTemplates();
          if (templates.length === 0) {
            return '📭 No templates available';
          }

          let result = '📋 Available Templates:\n';
          templates.forEach(template => {
            result += `• ${template.id} - ${template.name}\n`;
            result += `  Category: ${template.category}\n`;
            result += `  Description: ${template.description}\n\n`;
          });
          return result;
        }

        case 'show': {
          const templateId = args[1];
          if (!templateId) {
            return '❌ Template ID required';
          }

          const template = await this.templateLibrary.getTemplate(templateId);
          if (!template) {
            return `❌ Template '${templateId}' not found`;
          }

          return `📋 Template: ${templateId}\n\n\`\`\`json\n${JSON.stringify(template, null, 2)}\n\`\`\``;
        }

        case 'create': {
          const name = options.name || args[1];
          if (!name) {
            return '❌ Template name required';
          }

          // Create basic template structure
          const template = {
            id: name.toLowerCase().replace(/\s+/g, '-'),
            name: name,
            category: 'custom',
            description: `Custom template: ${name}`,
            panels: [
              {
                id: 'main-panel',
                title: 'Main Panel',
                type: 'metric' as any,
                dataSource: { type: 'system', query: 'metrics' },
                visualization: { type: 'line', theme: 'default' },
                position: { x: 0, y: 0, width: 12, height: 6 }
              }
            ],
            layout: { columns: 12, rows: 12 },
            refreshInterval: 30
          };

          await this.templateLibrary.saveTemplate(template.id, template);
          return `✅ Template '${name}' created successfully`;
        }

        case 'generate': {
          if (!options.fromData) {
            return '❌ Data source required for template generation';
          }

          // This would need actual data analysis implementation
          return '❌ Template generation from data not yet implemented';
        }

        default:
          return '❌ Unknown templates action. Use: list, show, create, generate';
      }
    } catch (error) {
      return `❌ Templates operation failed: ${error}`;
    }
  }

  private extractChannelsFromDashboard(config: any): string[] {
    const channels: string[] = [];
    
    if (config.panels) {
      for (const panel of config.panels) {
        if (panel.dataSource?.query) {
          channels.push(panel.dataSource.query);
        }
      }
    }

    return channels.length > 0 ? channels : ['system:metrics'];
  }
}

export default MonitoringCommands;