/**
 * File Drop Handler - Manages drag & drop functionality for files and images
 */
import * as fs from 'fs-extra';
import * as path from 'path';
import { fileTypeFromFile } from 'file-type';
import chalk from 'chalk';

export interface DroppedFile {
  id: string;
  path: string;
  name: string;
  size: number;
  type: string;
  mimeType?: string;
  isImage: boolean;
  isText: boolean;
  content?: string;
  imageBuffer?: Buffer;
  metadata?: any;
}

export interface FileDropConfig {
  maxFileSize: number; // in bytes
  supportedTypes: string[];
  enableOCR: boolean;
  enableImageAnalysis: boolean;
  maxFiles: number;
}

export class FileDropHandler {
  private config: FileDropConfig;
  private droppedFiles: Map<string, DroppedFile> = new Map();
  private dropZoneActive: boolean = false;

  constructor(config: Partial<FileDropConfig> = {}) {
    this.config = {
      maxFileSize: 50 * 1024 * 1024, // 50MB
      supportedTypes: ['.txt', '.md', '.js', '.ts', '.json', '.py', '.java', '.cpp', '.c', '.png', '.jpg', '.jpeg', '.gif', '.pdf'],
      enableOCR: true,
      enableImageAnalysis: true,
      maxFiles: 10,
      ...config,
    };
  }

  /**
   * Initialize file drop detection
   */
  async initialize(): Promise<void> {
    // Set up terminal event listeners for file drop detection
    this.setupDropZone();
  }

  /**
   * Set up drop zone detection (simplified for CLI)
   */
  private setupDropZone(): void {
    // In a real implementation, this would integrate with terminal capabilities
    // For now, we'll provide a method to manually add files
    console.log(chalk.gray('📎 File drop zone initialized. Use addFile() method to add files.'));
  }

  /**
   * Manually add a file (simulates drag & drop)
   */
  async addFile(filePath: string): Promise<DroppedFile | null> {
    try {
      // Validate file exists
      const stats = await fs.stat(filePath);
      if (!stats.isFile()) {
        throw new Error('Path is not a file');
      }

      // Check file size
      if (stats.size > this.config.maxFileSize) {
        console.log(chalk.red(`❌ File too large: ${this.formatFileSize(stats.size)} > ${this.formatFileSize(this.config.maxFileSize)}`));
        return null;
      }

      // Check if we've reached max files
      if (this.droppedFiles.size >= this.config.maxFiles) {
        console.log(chalk.red(`❌ Maximum files limit reached (${this.config.maxFiles})`));
        return null;
      }

      // Determine file type
      const fileType = await fileTypeFromFile(filePath);
      const extension = path.extname(filePath).toLowerCase();
      
      // Check if file type is supported
      if (!this.config.supportedTypes.includes(extension) && !fileType?.mime.startsWith('image/')) {
        console.log(chalk.yellow(`⚠️ Unsupported file type: ${extension}`));
        return null;
      }

      // Create dropped file object
      const fileId = this.generateFileId();
      const fileName = path.basename(filePath);
      const isImage = fileType?.mime?.startsWith('image/') || ['.png', '.jpg', '.jpeg', '.gif', '.bmp', '.webp'].includes(extension);
      const isText = ['.txt', '.md', '.js', '.ts', '.json', '.py', '.java', '.cpp', '.c', '.html', '.css', '.xml'].includes(extension);

      const droppedFile: DroppedFile = {
        id: fileId,
        path: filePath,
        name: fileName,
        size: stats.size,
        type: extension,
        mimeType: fileType?.mime,
        isImage,
        isText,
      };

      // Process file content
      await this.processFileContent(droppedFile);

      // Add to collection
      this.droppedFiles.set(fileId, droppedFile);

      console.log(chalk.green(`✅ Added file: ${fileName} (${this.formatFileSize(stats.size)})`));
      return droppedFile;

    } catch (error) {
      console.log(chalk.red(`❌ Failed to add file: ${error instanceof Error ? error.message : 'Unknown error'}`));
      return null;
    }
  }

  /**
   * Process file content based on type
   */
  private async processFileContent(file: DroppedFile): Promise<void> {
    try {
      if (file.isImage) {
        // Load image buffer for analysis
        file.imageBuffer = await fs.readFile(file.path);
        
        if (this.config.enableOCR) {
          // OCR processing will be handled by OCRProcessor
          file.metadata = { requiresOCR: true };
        }
      } else if (file.isText) {
        // Read text content
        const content = await fs.readFile(file.path, 'utf-8');
        file.content = content.length > 10000 ? content.substring(0, 10000) + '...' : content;
      } else if (file.type === '.pdf') {
        // PDF processing placeholder
        file.metadata = { requiresPDFExtraction: true };
      }
    } catch (error) {
      console.log(chalk.yellow(`⚠️ Could not process content for ${file.name}: ${error instanceof Error ? error.message : 'Unknown error'}`));
    }
  }

  /**
   * Get all dropped files
   */
  getDroppedFiles(): DroppedFile[] {
    return Array.from(this.droppedFiles.values());
  }

  /**
   * Get file by ID
   */
  getFile(fileId: string): DroppedFile | undefined {
    return this.droppedFiles.get(fileId);
  }

  /**
   * Remove file by ID
   */
  removeFile(fileId: string): boolean {
    return this.droppedFiles.delete(fileId);
  }

  /**
   * Clear all dropped files
   */
  clearFiles(): void {
    this.droppedFiles.clear();
  }

  /**
   * Get files summary for display
   */
  getFilesSummary(): string {
    const files = Array.from(this.droppedFiles.values());
    if (files.length === 0) {
      return 'No files attached';
    }

    const summary = files.map(file => {
      const icon = file.isImage ? '🖼️' : '📄';
      return `${icon} ${file.name} (${this.formatFileSize(file.size)})`;
    });

    return summary.join(', ');
  }

  /**
   * Generate context string for AI processing
   */
  generateContextString(): string {
    const files = Array.from(this.droppedFiles.values());
    if (files.length === 0) {
      return '';
    }

    let context = '\n\n--- Attached Files ---\n';
    
    for (const file of files) {
      context += `\nFile: ${file.name} (${this.formatFileSize(file.size)})\n`;
      context += `Type: ${file.mimeType || file.type}\n`;
      
      if (file.content) {
        context += `Content:\n${file.content}\n`;
      } else if (file.isImage) {
        context += `Image attached - OCR and analysis will be performed\n`;
      }
      
      context += '---\n';
    }
    
    return context;
  }

  /**
   * Get images for processing
   */
  getImagesForProcessing(): DroppedFile[] {
    return Array.from(this.droppedFiles.values()).filter(file => file.isImage && file.imageBuffer);
  }

  /**
   * Format file size for display
   */
  private formatFileSize(bytes: number): string {
    const units = ['B', 'KB', 'MB', 'GB'];
    let size = bytes;
    let unitIndex = 0;
    
    while (size >= 1024 && unitIndex < units.length - 1) {
      size /= 1024;
      unitIndex++;
    }
    
    return `${size.toFixed(1)}${units[unitIndex]}`;
  }

  /**
   * Generate unique file ID
   */
  private generateFileId(): string {
    return `file_${Date.now()}_${Math.random().toString(36).substr(2, 9)}`;
  }

  /**
   * Check if drop zone is active
   */
  isDropZoneActive(): boolean {
    return this.dropZoneActive;
  }

  /**
   * Activate drop zone
   */
  activateDropZone(): void {
    this.dropZoneActive = true;
  }

  /**
   * Deactivate drop zone
   */
  deactivateDropZone(): void {
    this.dropZoneActive = false;
  }

  /**
   * Get supported file types
   */
  getSupportedTypes(): string[] {
    return this.config.supportedTypes;
  }

  /**
   * Validate file type
   */
  isFileTypeSupported(filePath: string): boolean {
    const extension = path.extname(filePath).toLowerCase();
    return this.config.supportedTypes.includes(extension);
  }
}