import { BaseCommandService } from '../../shared/BaseCommandService';
import { DiagramHandler } from '../../handlers/creative/diagram.handler';

export class CreativeCommandService extends BaseCommandService {
  private diagramHandler: DiagramHandler;

  constructor() {
    super();
    this.diagramHandler = new DiagramHandler();
  }

  async execute(command: string, args: string[]): Promise<string> {
    switch (command) {
      case '/diagram':
        return this.diagramHandler.execute(args);
      default:
        return `Unknown creative command: ${command}`;
    }
  }

  getCommands(): string[] {
    return ['/diagram'];
  }

  getCategory(): string {
    return 'creative';
  }
}