/**
 * Context Analyzer
 * Analyzes system context and user intent
 */

import { linuxIntelligence } from './LinuxIntelligenceEngine';

export class ContextAnalyzer {
  private context: Map<string, any> = new Map();
  
  async analyze(input: string): Promise<any> {
    const intent = await linuxIntelligence.analyzeUserIntent(input);
    const systemState = await linuxIntelligence.assessSystemState();
    
    this.context.set('lastIntent', intent);
    this.context.set('systemState', systemState);
    
    return {
      intent,
      systemState,
      timestamp: new Date(),
    };
  }
  
  getContext(): Map<string, any> {
    return new Map(this.context);
  }
  
  clearContext(): void {
    this.context.clear();
  }
}