/**
 * RewardBuilder - Aggregates and normalizes reward signals
 * Combines verifiable rewards, rubric scores, and user signals
 */

import {
  RewardSignals,
  VerifiableRewards,
  RubricScores,
  UserSignals,
  Penalties,
  Episode,
} from './types';

export interface RewardWeights {
  verifiable: number;
  rubric: number;
  userSignals: number;
  performance: number;
  penaltyMultiplier: number;
}

export class RewardBuilder {
  private weights: RewardWeights;
  private recentStats: {
    avgTestPassRate: number;
    avgUserSatisfaction: number;
    avgExecutionTime: number;
  };

  constructor(
    weights: RewardWeights = {
      verifiable: 0.4,
      rubric: 0.3,
      userSignals: 0.2,
      performance: 0.1,
      penaltyMultiplier: 1.0,
    }
  ) {
    this.weights = weights;
    this.recentStats = {
      avgTestPassRate: 0.8,
      avgUserSatisfaction: 0.7,
      avgExecutionTime: 1000,
    };
  }

  /**
   * Build complete reward signal from an episode
   */
  buildReward(episode: Episode): RewardSignals {
    const { outcome } = episode;
    
    // Calculate individual reward components
    const verifiableReward = this.calculateVerifiableReward(outcome.rewards.verifiable);
    const rubricReward = this.calculateRubricReward(outcome.rewards.rubricScores);
    const userReward = this.calculateUserReward(outcome.rewards.userSignals);
    const performanceReward = this.calculatePerformanceReward(outcome.rewards.verifiable.performanceMetrics);
    const penaltyScore = this.calculatePenalties(outcome.rewards.penalties);

    // Calculate total reward with dynamic weights
    const totalReward = this.calculateTotalReward(
      verifiableReward,
      rubricReward,
      userReward,
      performanceReward,
      penaltyScore
    );

    return {
      ...outcome.rewards,
      totalReward,
    };
  }

  /**
   * Calculate verifiable rewards (RLVR approach)
   */
  private calculateVerifiableReward(verifiable: VerifiableRewards): number {
    let reward = 0;

    // Test pass rate (highest weight)
    reward += verifiable.testPassRate * 40;

    // Build success
    reward += verifiable.buildSuccess ? 20 : -10;

    // Type check
    reward += verifiable.typeCheckPass ? 15 : -5;

    // Lint errors (penalty for errors)
    reward -= Math.min(verifiable.lintErrors * 2, 20);

    // Performance metrics
    const perfScore = this.normalizePerformanceMetrics(verifiable.performanceMetrics);
    reward += perfScore * 25;

    return Math.max(0, Math.min(100, reward)); // Clamp to 0-100
  }

  /**
   * Calculate rubric-based rewards for subjective quality
   */
  private calculateRubricReward(rubricScores: RubricScores): number {
    const weights = {
      codeQuality: 0.3,
      documentation: 0.2,
      userSatisfaction: 0.25,
      innovativeness: 0.15,
      efficiency: 0.1,
    };

    const weightedScore = 
      rubricScores.codeQuality * weights.codeQuality +
      rubricScores.documentation * weights.documentation +
      rubricScores.userSatisfaction * weights.userSatisfaction +
      rubricScores.innovativeness * weights.innovativeness +
      rubricScores.efficiency * weights.efficiency;

    return weightedScore;
  }

  /**
   * Calculate user signal rewards
   */
  private calculateUserReward(userSignals: UserSignals): number {
    let reward = 50; // Start at neutral

    // Thumbs up/down has high impact
    if (userSignals.thumbsUp) reward += 30;
    if (userSignals.thumbsDown) reward -= 30;

    // Acceptance rate
    reward += (userSignals.acceptanceRate - 0.5) * 40;

    // Modification rate (lower is better)
    reward += (1 - userSignals.modificationRate) * 20;

    // Session duration (engagement)
    const engagementScore = this.normalizeSessionDuration(userSignals.sessionDuration);
    reward += engagementScore * 10;

    return Math.max(0, Math.min(100, reward));
  }

  /**
   * Calculate performance rewards
   */
  private calculatePerformanceReward(metrics: VerifiableRewards['performanceMetrics']): number {
    let reward = 50;

    // Execution time (compare to average)
    const timeRatio = this.recentStats.avgExecutionTime / metrics.executionTime;
    reward += (timeRatio - 1) * 20; // Bonus for faster, penalty for slower

    // Memory usage (lower is better)
    const memoryMB = metrics.memoryUsage / (1024 * 1024);
    if (memoryMB < 50) reward += 20;
    else if (memoryMB < 100) reward += 10;
    else if (memoryMB > 200) reward -= 10;

    // Bundle size (if applicable)
    if (metrics.bundleSize !== undefined) {
      const bundleMB = metrics.bundleSize / (1024 * 1024);
      if (bundleMB < 1) reward += 20;
      else if (bundleMB < 5) reward += 10;
      else if (bundleMB > 10) reward -= 10;
    }

    return Math.max(0, Math.min(100, reward));
  }

  /**
   * Calculate penalties
   */
  private calculatePenalties(penalties: Penalties): number {
    let penaltyScore = 0;

    // Regressions are severe
    penaltyScore += penalties.regressionCount * 20;

    // Error frequency
    penaltyScore += penalties.errorFrequency * 10;

    // Security issues are critical
    penaltyScore += penalties.securityIssues * 30;

    // Performance degradation
    penaltyScore += penalties.performanceDegradation * 15;

    return penaltyScore;
  }

  /**
   * Calculate total reward with dynamic weighting
   */
  private calculateTotalReward(
    verifiable: number,
    rubric: number,
    user: number,
    performance: number,
    penalties: number
  ): number {
    // Apply dynamic weight adjustment based on recent performance
    const adjustedWeights = this.adjustWeights();

    const positiveReward = 
      verifiable * adjustedWeights.verifiable +
      rubric * adjustedWeights.rubric +
      user * adjustedWeights.userSignals +
      performance * adjustedWeights.performance;

    // Apply penalties
    const totalReward = positiveReward - (penalties * adjustedWeights.penaltyMultiplier);

    return Math.max(-100, Math.min(100, totalReward));
  }

  /**
   * Dynamically adjust weights based on recent performance gaps
   */
  private adjustWeights(): RewardWeights {
    const adjusted = { ...this.weights };

    // If test pass rate is low, increase verifiable weight
    if (this.recentStats.avgTestPassRate < 0.7) {
      adjusted.verifiable *= 1.2;
      adjusted.rubric *= 0.9;
    }

    // If user satisfaction is low, increase user signal weight
    if (this.recentStats.avgUserSatisfaction < 0.6) {
      adjusted.userSignals *= 1.3;
      adjusted.verifiable *= 0.9;
    }

    // Normalize weights to sum to 1
    const sum = adjusted.verifiable + adjusted.rubric + adjusted.userSignals + adjusted.performance;
    adjusted.verifiable /= sum;
    adjusted.rubric /= sum;
    adjusted.userSignals /= sum;
    adjusted.performance /= sum;

    return adjusted;
  }

  /**
   * Normalize performance metrics
   */
  private normalizePerformanceMetrics(metrics: VerifiableRewards['performanceMetrics']): number {
    // Simple normalization for now
    const timeScore = Math.max(0, 1 - metrics.executionTime / 5000); // 5s baseline
    const memoryScore = Math.max(0, 1 - metrics.memoryUsage / (100 * 1024 * 1024)); // 100MB baseline
    
    return (timeScore + memoryScore) / 2;
  }

  /**
   * Normalize session duration to 0-1 scale
   */
  private normalizeSessionDuration(duration: number): number {
    // Optimal session is around 5-30 minutes
    const optimalMin = 5 * 60 * 1000;
    const optimalMax = 30 * 60 * 1000;

    if (duration < optimalMin) {
      return duration / optimalMin;
    } else if (duration <= optimalMax) {
      return 1.0;
    } else {
      // Diminishing returns after 30 minutes
      return Math.max(0.5, 1 - (duration - optimalMax) / optimalMax);
    }
  }

  /**
   * Update recent statistics for dynamic weighting
   */
  updateRecentStats(episodes: Episode[]): void {
    if (episodes.length === 0) return;

    let totalTestPass = 0;
    let totalSatisfaction = 0;
    let totalTime = 0;
    let count = 0;

    for (const episode of episodes) {
      const rewards = episode.outcome.rewards;
      totalTestPass += rewards.verifiable.testPassRate;
      totalSatisfaction += rewards.rubricScores.userSatisfaction / 100;
      totalTime += rewards.verifiable.performanceMetrics.executionTime;
      count++;
    }

    this.recentStats = {
      avgTestPassRate: totalTestPass / count,
      avgUserSatisfaction: totalSatisfaction / count,
      avgExecutionTime: totalTime / count,
    };
  }

  /**
   * Get current weights
   */
  getWeights(): RewardWeights {
    return { ...this.weights };
  }

  /**
   * Set custom weights
   */
  setWeights(weights: Partial<RewardWeights>): void {
    this.weights = { ...this.weights, ...weights };
  }
}