/**
 * EnhancedProgressReporter Component
 * Provides advanced progress reporting with animations and status indicators
 */

import chalk from 'chalk';
import { EventEmitter } from 'events';

/**
 * Progress step status
 */
export type ProgressStatus = 'pending' | 'running' | 'completed' | 'error' | 'skipped';

/**
 * Progress step definition
 */
export interface ProgressStep {
  id: string;
  name: string;
  description?: string;
  status: ProgressStatus;
  progress?: number; // 0-100
  startTime?: Date;
  endTime?: Date;
  error?: string;
  metadata?: Record<string, any>;
}

/**
 * Progress session configuration
 */
export interface ProgressSessionConfig {
  title: string;
  showTimestamps?: boolean;
  showElapsedTime?: boolean;
  animateSpinner?: boolean;
  compactMode?: boolean;
  autoComplete?: boolean;
}

/**
 * Enhanced progress reporter class
 */
export class EnhancedProgressReporter extends EventEmitter {
  private steps: Map<string, ProgressStep> = new Map();
  private stepOrder: string[] = [];
  private config: Required<ProgressSessionConfig>;
  private sessionStartTime: Date;
  private currentSpinnerFrame: number = 0;
  private spinnerInterval: NodeJS.Timeout | null = null;
  private isActive: boolean = false;

  // Spinner frames for animation
  private readonly spinnerFrames = ['⠋', '⠙', '⠹', '⠸', '⠼', '⠴', '⠦', '⠧', '⠇', '⠏'];
  
  // Status icons
  private readonly statusIcons = {
    pending: chalk.gray('⏳'),
    running: chalk.blue('🔄'),
    completed: chalk.green('✅'),
    error: chalk.red('❌'),
    skipped: chalk.yellow('⏭️'),
  };

  constructor(config: ProgressSessionConfig) {
    super();
    this.config = {
      title: config.title,
      showTimestamps: config.showTimestamps ?? true,
      showElapsedTime: config.showElapsedTime ?? true,
      animateSpinner: config.animateSpinner ?? true,
      compactMode: config.compactMode ?? false,
      autoComplete: config.autoComplete ?? true,
    };
    this.sessionStartTime = new Date();
  }

  /**
   * Start the progress session
   */
  start(): void {
    this.isActive = true;
    this.sessionStartTime = new Date();
    
    if (!this.config.compactMode) {
      console.log(chalk.cyan('\n' + '═'.repeat(80)));
      console.log(chalk.cyan.bold(`  ${this.config.title}`));
      if (this.config.showTimestamps) {
        console.log(chalk.gray(`  Started: ${this.sessionStartTime.toLocaleTimeString()}`));
      }
      console.log(chalk.cyan('═'.repeat(80)));
    } else {
      console.log(chalk.cyan(`\n🚀 ${this.config.title}`));
    }
    
    this.emit('session-start', { startTime: this.sessionStartTime });
  }

  /**
   * Add a progress step
   */
  addStep(step: Omit<ProgressStep, 'status'>): void {
    const progressStep: ProgressStep = {
      ...step,
      status: 'pending',
      startTime: undefined,
      endTime: undefined,
    };
    
    this.steps.set(step.id, progressStep);
    this.stepOrder.push(step.id);
    
    this.emit('step-added', progressStep);
    
    if (this.isActive) {
      this.renderCurrentStatus();
    }
  }

  /**
   * Update step status
   */
  updateStep(stepId: string, updates: Partial<ProgressStep>): void {
    const step = this.steps.get(stepId);
    if (!step) {
      console.warn(`Step ${stepId} not found`);
      return;
    }
    
    // Track timing
    if (updates.status === 'running' && step.status !== 'running') {
      updates.startTime = new Date();
    } else if (updates.status === 'completed' || updates.status === 'error') {
      updates.endTime = new Date();
    }
    
    // Update step
    Object.assign(step, updates);
    this.steps.set(stepId, step);
    
    this.emit('step-updated', step);
    
    if (this.isActive) {
      this.renderCurrentStatus();
    }
    
    // Auto-complete session if all steps are done
    if (this.config.autoComplete && this.areAllStepsComplete()) {
      this.complete();
    }
  }

  /**
   * Start a specific step
   */
  startStep(stepId: string, progress?: number): void {
    this.updateStep(stepId, {
      status: 'running',
      progress,
    });
    
    // Start spinner for running step
    if (this.config.animateSpinner) {
      this.startSpinner(stepId);
    }
  }

  /**
   * Complete a specific step
   */
  completeStep(stepId: string, metadata?: Record<string, any>): void {
    this.updateStep(stepId, {
      status: 'completed',
      progress: 100,
      metadata,
    });
    
    this.stopSpinner();
  }

  /**
   * Fail a specific step
   */
  failStep(stepId: string, error: string): void {
    this.updateStep(stepId, {
      status: 'error',
      error,
    });
    
    this.stopSpinner();
  }

  /**
   * Skip a specific step
   */
  skipStep(stepId: string, reason?: string): void {
    this.updateStep(stepId, {
      status: 'skipped',
      error: reason,
    });
  }

  /**
   * Update progress for a running step
   */
  updateProgress(stepId: string, progress: number, description?: string): void {
    this.updateStep(stepId, {
      progress: Math.min(100, Math.max(0, progress)),
      description,
    });
  }

  /**
   * Complete the entire session
   */
  complete(): void {
    this.isActive = false;
    this.stopSpinner();
    
    const endTime = new Date();
    const duration = endTime.getTime() - this.sessionStartTime.getTime();
    
    if (!this.config.compactMode) {
      console.log(chalk.cyan('\n' + '═'.repeat(80)));
      console.log(chalk.green.bold('  ✅ Session Complete!'));
      
      if (this.config.showElapsedTime) {
        console.log(chalk.gray(`  Duration: ${this.formatDuration(duration)}`));
      }
      
      if (this.config.showTimestamps) {
        console.log(chalk.gray(`  Completed: ${endTime.toLocaleTimeString()}`));
      }
      
      // Show summary
      this.renderSummary();
      console.log(chalk.cyan('═'.repeat(80) + '\n'));
    } else {
      console.log(chalk.green(`✅ ${this.config.title} completed in ${this.formatDuration(duration)}`));
    }
    
    this.emit('session-complete', {
      startTime: this.sessionStartTime,
      endTime,
      duration,
      steps: Array.from(this.steps.values()),
    });
  }

  /**
   * Render current status
   */
  private renderCurrentStatus(): void {
    if (this.config.compactMode) {
      this.renderCompactStatus();
    } else {
      this.renderDetailedStatus();
    }
  }

  /**
   * Render detailed status
   */
  private renderDetailedStatus(): void {
    // Clear previous output (move up and clear lines)
    const linesToClear = this.stepOrder.length + 2;
    for (let i = 0; i < linesToClear; i++) {
      process.stdout.write('\x1b[1A\x1b[2K');
    }
    
    console.log(chalk.gray('\n  Progress:'));
    
    for (const stepId of this.stepOrder) {
      const step = this.steps.get(stepId)!;
      const icon = this.getStepIcon(step);
      const name = step.name;
      const progressBar = this.renderProgressBar(step);
      const timing = this.renderTiming(step);
      
      console.log(`  ${icon} ${name} ${progressBar} ${timing}`);
      
      if (step.description && step.status === 'running') {
        console.log(chalk.gray(`     ${step.description}`));
      }
      
      if (step.error && step.status === 'error') {
        console.log(chalk.red(`     Error: ${step.error}`));
      }
    }
  }

  /**
   * Render compact status
   */
  private renderCompactStatus(): void {
    const runningStep = this.stepOrder.find(id => this.steps.get(id)?.status === 'running');
    if (runningStep) {
      const step = this.steps.get(runningStep)!;
      const icon = this.getStepIcon(step);
      const progress = step.progress ? ` (${step.progress}%)` : '';
      process.stdout.write(`\r  ${icon} ${step.name}${progress}...`);
    }
  }

  /**
   * Get step icon with animation
   */
  private getStepIcon(step: ProgressStep): string {
    if (step.status === 'running' && this.config.animateSpinner) {
      return chalk.blue(this.spinnerFrames[this.currentSpinnerFrame]);
    }
    return this.statusIcons[step.status];
  }

  /**
   * Render progress bar
   */
  private renderProgressBar(step: ProgressStep): string {
    if (step.progress === undefined || step.status === 'pending') {
      return '';
    }
    
    const barLength = 20;
    const filled = Math.round((step.progress / 100) * barLength);
    const empty = barLength - filled;
    
    const filledBar = '█'.repeat(filled);
    const emptyBar = '░'.repeat(empty);
    
    let color = chalk.blue;
    if (step.status === 'completed') color = chalk.green;
    if (step.status === 'error') color = chalk.red;
    
    return `${color(filledBar)}${chalk.gray(emptyBar)} ${step.progress.toFixed(0)}%`;
  }

  /**
   * Render timing information
   */
  private renderTiming(step: ProgressStep): string {
    if (!this.config.showElapsedTime) return '';
    
    if (step.status === 'completed' && step.startTime && step.endTime) {
      const duration = step.endTime.getTime() - step.startTime.getTime();
      return chalk.gray(`(${this.formatDuration(duration)})`);
    } else if (step.status === 'running' && step.startTime) {
      const elapsed = Date.now() - step.startTime.getTime();
      return chalk.gray(`(${this.formatDuration(elapsed)})`);
    }
    
    return '';
  }

  /**
   * Render session summary
   */
  private renderSummary(): void {
    const completed = this.stepOrder.filter(id => this.steps.get(id)?.status === 'completed').length;
    const failed = this.stepOrder.filter(id => this.steps.get(id)?.status === 'error').length;
    const skipped = this.stepOrder.filter(id => this.steps.get(id)?.status === 'skipped').length;
    const total = this.stepOrder.length;
    
    console.log(chalk.gray('  Summary:'));
    console.log(chalk.green(`    ✅ Completed: ${completed}`));
    if (failed > 0) console.log(chalk.red(`    ❌ Failed: ${failed}`));
    if (skipped > 0) console.log(chalk.yellow(`    ⏭️ Skipped: ${skipped}`));
    console.log(chalk.blue(`    📊 Total: ${total}`));
  }

  /**
   * Start spinner animation
   */
  private startSpinner(_stepId: string): void {
    this.stopSpinner();
    this.spinnerInterval = setInterval(() => {
      this.currentSpinnerFrame = (this.currentSpinnerFrame + 1) % this.spinnerFrames.length;
      if (this.isActive) {
        this.renderCurrentStatus();
      }
    }, 100);
  }

  /**
   * Stop spinner animation
   */
  private stopSpinner(): void {
    if (this.spinnerInterval) {
      clearInterval(this.spinnerInterval);
      this.spinnerInterval = null;
    }
  }

  /**
   * Check if all steps are complete
   */
  private areAllStepsComplete(): boolean {
    return this.stepOrder.every(id => {
      const status = this.steps.get(id)?.status;
      return status === 'completed' || status === 'error' || status === 'skipped';
    });
  }

  /**
   * Format duration in human readable format
   */
  private formatDuration(ms: number): string {
    if (ms < 1000) return `${ms}ms`;
    if (ms < 60000) return `${(ms / 1000).toFixed(1)}s`;
    const minutes = Math.floor(ms / 60000);
    const seconds = Math.floor((ms % 60000) / 1000);
    return `${minutes}m ${seconds}s`;
  }

  /**
   * Get all steps
   */
  getSteps(): ProgressStep[] {
    return this.stepOrder.map(id => this.steps.get(id)!);
  }

  /**
   * Get step by ID
   */
  getStep(stepId: string): ProgressStep | undefined {
    return this.steps.get(stepId);
  }

  /**
   * Clean up resources
   */
  destroy(): void {
    this.stopSpinner();
    this.isActive = false;
    this.removeAllListeners();
  }
}

export default EnhancedProgressReporter;