/**
 * ReferenceManager Component
 * Manages file references, URLs, and images in conversation context
 */

import * as fs from 'fs';
import * as path from 'path';
import chalk from 'chalk';
import { FileDropEvent } from './FileDropHandler.js';

/**
 * Reference types
 */
export type ReferenceType = 'file' | 'directory' | 'url' | 'image' | 'code';

/**
 * Reference item
 */
export interface ReferenceItem {
  id: string;
  type: ReferenceType;
  path: string;
  name: string;
  content?: string;
  metadata?: {
    size?: number;
    mimeType?: string;
    timestamp?: Date;
    extracted?: boolean;
    summary?: string;
  };
}

/**
 * Reference manager configuration
 */
export interface ReferenceManagerConfig {
  maxReferences?: number;
  autoExtractContent?: boolean;
  persistReferences?: boolean;
  referenceCachePath?: string;
}

/**
 * Reference manager class
 */
export class ReferenceManager {
  private references: Map<string, ReferenceItem> = new Map();
  private config: Required<ReferenceManagerConfig>;
  private referenceOrder: string[] = [];
  
  constructor(config: ReferenceManagerConfig = {}) {
    this.config = {
      maxReferences: config.maxReferences || 100,
      autoExtractContent: config.autoExtractContent ?? true,
      persistReferences: config.persistReferences ?? false,
      referenceCachePath: config.referenceCachePath || path.join(process.cwd(), '.maria-refs'),
    };
    
    // Load persisted references if enabled
    if (this.config.persistReferences) {
      this.loadPersistedReferences();
    }
  }

  /**
   * Add a reference from FileDropEvent
   */
  async addReference(event: FileDropEvent): Promise<ReferenceItem> {
    const id = this.generateId(event.path);
    
    // Check if reference already exists
    if (this.references.has(id)) {
      return this.references.get(id)!;
    }
    
    // Check max references limit
    if (this.references.size >= this.config.maxReferences) {
      // Remove oldest reference
      const oldestId = this.referenceOrder.shift();
      if (oldestId) {
        this.references.delete(oldestId);
      }
    }
    
    // Create reference item
    const reference: ReferenceItem = {
      id,
      type: this.mapEventType(event.type),
      path: event.path,
      name: event.name,
      metadata: {
        size: event.size,
        mimeType: event.mimeType,
        timestamp: new Date(),
        extracted: false,
      },
    };
    
    // Auto-extract content if enabled
    if (this.config.autoExtractContent && event.type === 'file') {
      try {
        reference.content = await this.extractContent(event.path);
        reference.metadata!.extracted = true;
      } catch (error) {
        // Content extraction failed, continue without content
      }
    }
    
    // Store reference
    this.references.set(id, reference);
    this.referenceOrder.push(id);
    
    // Persist if enabled
    if (this.config.persistReferences) {
      this.persistReferences();
    }
    
    return reference;
  }

  /**
   * Add a code snippet reference
   */
  addCodeReference(code: string, language?: string): ReferenceItem {
    const id = this.generateId(`code-${Date.now()}`);
    
    const reference: ReferenceItem = {
      id,
      type: 'code',
      path: `code-snippet-${id}`,
      name: `Code Snippet (${language || 'plain'})`,
      content: code,
      metadata: {
        size: code.length,
        mimeType: 'text/plain',
        timestamp: new Date(),
        extracted: true,
      },
    };
    
    this.references.set(id, reference);
    this.referenceOrder.push(id);
    
    return reference;
  }

  /**
   * Get reference by ID
   */
  getReference(id: string): ReferenceItem | undefined {
    return this.references.get(id);
  }

  /**
   * Get all references
   */
  getAllReferences(): ReferenceItem[] {
    return this.referenceOrder.map(id => this.references.get(id)!).filter(Boolean);
  }

  /**
   * Get references by type
   */
  getReferencesByType(type: ReferenceType): ReferenceItem[] {
    return this.getAllReferences().filter(ref => ref.type === type);
  }

  /**
   * Remove reference
   */
  removeReference(id: string): boolean {
    const index = this.referenceOrder.indexOf(id);
    if (index > -1) {
      this.referenceOrder.splice(index, 1);
    }
    const deleted = this.references.delete(id);
    
    if (deleted && this.config.persistReferences) {
      this.persistReferences();
    }
    
    return deleted;
  }

  /**
   * Clear all references
   */
  clearReferences(): void {
    this.references.clear();
    this.referenceOrder = [];
    
    if (this.config.persistReferences) {
      this.persistReferences();
    }
  }

  /**
   * Extract content from file
   */
  private async extractContent(filePath: string): Promise<string> {
    const stats = await fs.promises.stat(filePath);
    
    // Don't extract content from large files
    if (stats.size > 1024 * 1024) { // 1MB limit
      throw new Error('File too large for content extraction');
    }
    
    // Read file content
    const content = await fs.promises.readFile(filePath, 'utf-8');
    
    // Truncate if too long
    if (content.length > 50000) {
      return content.substring(0, 50000) + '\n... [truncated]';
    }
    
    return content;
  }

  /**
   * Generate unique ID for reference
   */
  private generateId(path: string): string {
    const hash = Buffer.from(path).toString('base64').replace(/[^a-zA-Z0-9]/g, '');
    return `ref-${hash.substring(0, 8)}-${Date.now()}`;
  }

  /**
   * Map FileDropEvent type to ReferenceType
   */
  private mapEventType(eventType: FileDropEvent['type']): ReferenceType {
    switch (eventType) {
      case 'file': return 'file';
      case 'directory': return 'directory';
      case 'url': return 'url';
      case 'image': return 'image';
      default: return 'file';
    }
  }

  /**
   * Build context string from references
   */
  buildContext(): string {
    const references = this.getAllReferences();
    if (references.length === 0) {
      return '';
    }
    
    let context = '\n=== Referenced Materials ===\n';
    
    for (const ref of references) {
      context += `\n[${ref.type.toUpperCase()}] ${ref.name}\n`;
      
      if (ref.content) {
        const preview = ref.content.substring(0, 500);
        context += `${preview}${ref.content.length > 500 ? '...' : ''}\n`;
      } else if (ref.type === 'file' || ref.type === 'image') {
        context += `Path: ${ref.path}\n`;
        if (ref.metadata?.size) {
          context += `Size: ${this.formatFileSize(ref.metadata.size)}\n`;
        }
      }
    }
    
    context += '\n=== End of References ===\n';
    return context;
  }

  /**
   * Display references summary
   */
  displaySummary(): void {
    const references = this.getAllReferences();
    
    if (references.length === 0) {
      console.log(chalk.gray('No references in context'));
      return;
    }
    
    console.log(chalk.cyan('\n📚 Active References:'));
    
    // Group by type
    const grouped = new Map<ReferenceType, ReferenceItem[]>();
    for (const ref of references) {
      if (!grouped.has(ref.type)) {
        grouped.set(ref.type, []);
      }
      grouped.get(ref.type)!.push(ref);
    }
    
    // Display grouped references
    for (const [type, refs] of grouped) {
      const icon = this.getTypeIcon(type);
      console.log(chalk.yellow(`\n  ${icon} ${type.charAt(0).toUpperCase() + type.slice(1)}s:`));
      
      for (const ref of refs) {
        const sizeStr = ref.metadata?.size 
          ? chalk.gray(` (${this.formatFileSize(ref.metadata.size)})`)
          : '';
        const extractedStr = ref.metadata?.extracted 
          ? chalk.green(' ✓')
          : '';
        console.log(`    • ${chalk.white(ref.name)}${sizeStr}${extractedStr}`);
      }
    }
    
    console.log(chalk.gray(`\n  Total: ${references.length} reference(s)`));
  }

  /**
   * Get icon for reference type
   */
  private getTypeIcon(type: ReferenceType): string {
    const icons: Record<ReferenceType, string> = {
      file: '📄',
      directory: '📁',
      url: '🔗',
      image: '🖼️',
      code: '💻',
    };
    return icons[type] || '📎';
  }

  /**
   * Format file size
   */
  private formatFileSize(bytes: number): string {
    const units = ['B', 'KB', 'MB', 'GB'];
    let size = bytes;
    let unitIndex = 0;
    
    while (size >= 1024 && unitIndex < units.length - 1) {
      size /= 1024;
      unitIndex++;
    }
    
    return `${size.toFixed(1)} ${units[unitIndex]}`;
  }

  /**
   * Persist references to disk
   */
  private persistReferences(): void {
    if (!this.config.persistReferences) return;
    
    try {
      const data = {
        references: Array.from(this.references.entries()),
        order: this.referenceOrder,
      };
      
      fs.mkdirSync(path.dirname(this.config.referenceCachePath), { recursive: true });
      fs.writeFileSync(
        this.config.referenceCachePath,
        JSON.stringify(data, null, 2),
        'utf-8'
      );
    } catch (error) {
      // Silently fail persistence
    }
  }

  /**
   * Load persisted references from disk
   */
  private loadPersistedReferences(): void {
    if (!this.config.persistReferences) return;
    
    try {
      if (fs.existsSync(this.config.referenceCachePath)) {
        const data = JSON.parse(fs.readFileSync(this.config.referenceCachePath, 'utf-8'));
        
        if (data.references && Array.isArray(data.references)) {
          this.references = new Map(data.references);
        }
        
        if (data.order && Array.isArray(data.order)) {
          this.referenceOrder = data.order;
        }
      }
    } catch (error) {
      // Silently fail loading
    }
  }
}

export default ReferenceManager;