/**
 * Learning Engine
 * Machine learning for command patterns
 */

import { learnFromExecution } from './LinuxIntelligenceEngine';

export class LearningEngine {
  private patterns: Map<string, any> = new Map();
  
  async learn(command: string, result: any): Promise<void> {
    await learnFromExecution(command, result);
    
    // Update patterns
    const pattern = this.extractPattern(command);
    const count = this.patterns.get(pattern) || 0;
    this.patterns.set(pattern, count + 1);
  }
  
  private extractPattern(command: string): string {
    // Extract command pattern
    const parts = command.split(' ');
    return parts[0] || 'unknown';
  }
  
  getPatterns(): Map<string, any> {
    return new Map(this.patterns);
  }
}