/**
 * Response Renderer - Displays AI responses outside the input box area
 */
import chalk from 'chalk';
import { TEXT_HIERARCHY } from '../../ui/design-system/UnifiedColorPalette';

export interface ResponseConfig {
  maxWidth: number;
  showProgress: boolean;
  showModes: boolean;
  enableColors: boolean;
  responsePrefix: string;
}

export interface ProgressStep {
  id: string;
  description: string;
  status: 'pending' | 'processing' | 'completed' | 'failed';
  details?: string;
  timestamp: Date;
}

export class ResponseRenderer {
  private config: ResponseConfig;
  private currentSteps: Map<string, ProgressStep> = new Map();
  private responseArea = { startRow: 0, height: 0 };

  constructor(config: Partial<ResponseConfig> = {}) {
    this.config = {
      maxWidth: 100,
      showProgress: true,
      showModes: true,
      enableColors: true,
      responsePrefix: 'MARIA: ',
      ...config,
    };
  }

  /**
   * Initialize response area below input box
   */
  initializeResponseArea(inputBoxHeight: number): void {
    this.responseArea.startRow = inputBoxHeight + 2;
    this.moveToResponseArea();
    console.log(chalk.gray('─'.repeat(this.config.maxWidth)));
  }

  /**
   * Move cursor to response area
   */
  private moveToResponseArea(): void {
    process.stdout.write(`\x1b[${this.responseArea.startRow};1H`);
  }

  /**
   * Display progress step
   */
  displayProgressStep(step: ProgressStep): void {
    if (!this.config.showProgress) return;

    this.currentSteps.set(step.id, step);
    this.moveToResponseArea();
    
    const icon = this.getStatusIcon(step.status);
    const statusColor = this.getStatusColor(step.status);
    const timestamp = step.timestamp.toLocaleTimeString();
    
    console.log(
      `${icon} ${statusColor(step.description)} ${chalk.gray(`(${timestamp})`)}`
    );
    
    if (step.details) {
      console.log(chalk.gray(`   ${step.details}`));
    }
  }

  /**
   * Update existing progress step
   */
  updateProgressStep(stepId: string, updates: Partial<ProgressStep>): void {
    const existingStep = this.currentSteps.get(stepId);
    if (!existingStep) return;

    const updatedStep: ProgressStep = {
      ...existingStep,
      ...updates,
      timestamp: new Date(),
    };

    this.currentSteps.set(stepId, updatedStep);
    this.displayProgressStep(updatedStep);
  }

  /**
   * Start AI response display
   */
  startResponse(mode?: { symbol: string; name: string }): void {
    this.moveToResponseArea();
    console.log(); // Add spacing
    
    // Show header with mode indicator
    let header = TEXT_HIERARCHY.SUBTITLE(this.config.responsePrefix);
    
    if (this.config.showModes && mode) {
      header += chalk.dim(`[${mode.symbol} ${mode.name}] `);
    }
    
    process.stdout.write(header);
  }

  /**
   * Stream response content
   */
  streamContent(chunk: string, isFirstChunk: boolean = false): void {
    if (isFirstChunk) {
      process.stdout.write('\n'); // New line before response content
    }
    process.stdout.write(chunk);
  }

  /**
   * Complete response display
   */
  completeResponse(): void {
    console.log('\n');
    this.showCompletionSummary();
  }

  /**
   * Display error message
   */
  displayError(error: string, details?: string): void {
    this.moveToResponseArea();
    console.log();
    console.log(chalk.red(`❌ Error: ${error}`));
    
    if (details) {
      console.log(chalk.gray(`   ${details}`));
    }
    
    console.log();
  }

  /**
   * Display warning message
   */
  displayWarning(warning: string, details?: string): void {
    this.moveToResponseArea();
    console.log(chalk.yellow(`⚠️ Warning: ${warning}`));
    
    if (details) {
      console.log(chalk.gray(`   ${details}`));
    }
  }

  /**
   * Display info message
   */
  displayInfo(info: string, details?: string): void {
    this.moveToResponseArea();
    console.log(chalk.blue(`ℹ️ ${info}`));
    
    if (details) {
      console.log(chalk.gray(`   ${details}`));
    }
  }

  /**
   * Display success message
   */
  displaySuccess(success: string, details?: string): void {
    this.moveToResponseArea();
    console.log(chalk.green(`✅ ${success}`));
    
    if (details) {
      console.log(chalk.gray(`   ${details}`));
    }
  }

  /**
   * Show processing animation
   */
  showProcessingAnimation(message: string): NodeJS.Timeout {
    const frames = ['⠋', '⠙', '⠹', '⠸', '⠼', '⠴', '⠦', '⠧', '⠇', '⠏'];
    let frame = 0;
    
    return setInterval(() => {
      this.moveToResponseArea();
      process.stdout.write(`\r${chalk.cyan(frames[frame])} ${message}   `);
      frame = (frame + 1) % frames.length;
    }, 100);
  }

  /**
   * Stop processing animation
   */
  stopProcessingAnimation(interval: NodeJS.Timeout): void {
    clearInterval(interval);
    this.moveToResponseArea();
    process.stdout.write('\r' + ' '.repeat(50) + '\r'); // Clear line
  }

  /**
   * Display reference processing status
   */
  displayReferenceStatus(references: { name: string; status: string; details?: string }[]): void {
    if (references.length === 0) return;

    this.moveToResponseArea();
    console.log(chalk.blue('\n📎 Reference Processing:'));
    
    references.forEach(ref => {
      const statusIcon = ref.status === 'completed' ? '✅' : ref.status === 'processing' ? '🔄' : '❌';
      console.log(`  ${statusIcon} ${ref.name}`);
      
      if (ref.details) {
        console.log(chalk.gray(`     ${ref.details}`));
      }
    });
    
    console.log();
  }

  /**
   * Display task breakdown
   */
  displayTaskBreakdown(tasks: { name: string; status: string; progress?: number }[]): void {
    this.moveToResponseArea();
    console.log(chalk.blue('\n📋 Task Breakdown:'));
    
    tasks.forEach((task, index) => {
      const statusIcon = this.getTaskStatusIcon(task.status);
      const statusColor = this.getStatusColor(task.status);
      
      let line = `  ${index + 1}. ${statusIcon} ${statusColor(task.name)}`;
      
      if (task.progress !== undefined) {
        const progressBar = this.createProgressBar(task.progress);
        line += ` ${progressBar} ${task.progress}%`;
      }
      
      console.log(line);
    });
    
    console.log();
  }

  /**
   * Create a simple progress bar
   */
  private createProgressBar(percentage: number, width: number = 20): string {
    const filled = Math.round((percentage / 100) * width);
    const empty = width - filled;
    return `[${'█'.repeat(filled)}${' '.repeat(empty)}]`;
  }

  /**
   * Get status icon based on status
   */
  private getStatusIcon(status: string): string {
    switch (status) {
      case 'completed': return '✅';
      case 'processing': return '🔄';
      case 'failed': return '❌';
      case 'pending': return '⏳';
      default: return '📋';
    }
  }

  /**
   * Get task status icon
   */
  private getTaskStatusIcon(status: string): string {
    switch (status) {
      case 'completed': return '✅';
      case 'processing': return '⚡';
      case 'failed': return '❌';
      case 'pending': return '📝';
      default: return '📋';
    }
  }

  /**
   * Get status color function
   */
  private getStatusColor(status: string): (text: string) => string {
    switch (status) {
      case 'completed': return chalk.green;
      case 'processing': return chalk.yellow;
      case 'failed': return chalk.red;
      case 'pending': return chalk.gray;
      default: return chalk.white;
    }
  }

  /**
   * Show completion summary
   */
  private showCompletionSummary(): void {
    const completedSteps = Array.from(this.currentSteps.values())
      .filter(step => step.status === 'completed');
    
    if (completedSteps.length > 0) {
      console.log(chalk.gray(`📊 Completed ${completedSteps.length} processing steps`));
    }
    
    // Clear steps for next response
    this.currentSteps.clear();
  }

  /**
   * Clear response area
   */
  clearResponseArea(): void {
    this.moveToResponseArea();
    // Clear multiple lines
    for (let i = 0; i < 20; i++) {
      process.stdout.write('\x1b[2K'); // Clear line
      if (i < 19) process.stdout.write('\n');
    }
    // Move back to start
    process.stdout.write(`\x1b[20A`);
  }

  /**
   * Set response area configuration
   */
  setConfig(config: Partial<ResponseConfig>): void {
    this.config = { ...this.config, ...config };
  }

  /**
   * Get current configuration
   */
  getConfig(): ResponseConfig {
    return { ...this.config };
  }
}