/**
 * Anomaly Detector
 * Detects unusual system behavior and commands
 */

export class AnomalyDetector {
  private baseline: Map<string, number> = new Map();
  private anomalies: any[] = [];
  
  async detect(metric: string, value: number): Promise<boolean> {
    const baseline = this.baseline.get(metric) || 0;
    const deviation = Math.abs(value - baseline);
    const threshold = baseline * 0.5; // 50% deviation threshold
    
    if (deviation > threshold) {
      this.anomalies.push({
        metric,
        value,
        baseline,
        deviation,
        timestamp: new Date(),
      });
      return true;
    }
    
    // Update baseline with moving average
    this.baseline.set(metric, (baseline * 0.9) + (value * 0.1));
    return false;
  }
  
  getAnomalies(): any[] {
    return [...this.anomalies];
  }
  
  clearAnomalies(): void {
    this.anomalies = [];
  }
}