/**
 * Safety Validator
 * Validates commands for safety and security
 */

import { validateCommand, createBackup } from './LinuxIntelligenceEngine';

export class SafetyValidator {
  async validate(command: string): Promise<any> {
    const validation = await validateCommand(command);
    
    if (validation.riskLevel === 'HIGH' || validation.riskLevel === 'CRITICAL') {
      // Auto-backup for risky operations
      await createBackup('system');
    }
    
    return validation;
  }
  
  isCommandSafe(command: string): boolean {
    const dangerousCommands = ['rm -rf /', 'dd', 'format'];
    return !dangerousCommands.some(dangerous => command.includes(dangerous));
  }
}