/**
 * System Command Service
 * Handles system management, diagnostics, and terminal setup commands
 */

import { BaseCommandService } from '../../shared/BaseCommandService';
import { CommandCategory } from '../../types';
import { StatusCommand } from './handlers/StatusCommand';
import { DoctorCommand } from './handlers/DoctorCommand';
import { TerminalSetupCommand } from './handlers/TerminalSetupCommand';
import { logger } from '../../../utils/logger';

export class SystemCommandService extends BaseCommandService {
  readonly category: CommandCategory = 'system';

  /**
   * Register all system command handlers
   */
  registerHandlers(): void {
    logger.debug('Registering system command handlers');

    // Register system commands
    this.handlers.set('/status', new StatusCommand());
    this.handlers.set('/doctor', new DoctorCommand());
    this.handlers.set('/terminal-setup', new TerminalSetupCommand());

    // Register aliases for convenience
    this.handlers.set('/st', this.handlers.get('/status')!);
    this.handlers.set('/info', this.handlers.get('/status')!);
    this.handlers.set('/sys', this.handlers.get('/status')!);
    
    this.handlers.set('/dr', this.handlers.get('/doctor')!);
    this.handlers.set('/health', this.handlers.get('/doctor')!);
    this.handlers.set('/check', this.handlers.get('/doctor')!);
    
    this.handlers.set('/term', this.handlers.get('/terminal-setup')!);
    this.handlers.set('/tsetup', this.handlers.get('/terminal-setup')!);
    this.handlers.set('/terminal', this.handlers.get('/terminal-setup')!);

    logger.info(`System command service registered ${this.handlers.size} commands/aliases`);
  }

  /**
   * Initialize system command service
   */
  override async initialize(): Promise<void> {
    logger.info('Initializing SystemCommandService');

    // Call parent initialization
    await super.initialize();

    // Perform any system-specific initialization
    await this.initializeSystemComponents();

    logger.info('SystemCommandService initialization complete');
  }

  /**
   * Initialize system-specific components
   */
  private async initializeSystemComponents(): Promise<void> {
    try {
      // Perform initial system checks
      await this.performStartupChecks();
      
      // Initialize system monitoring if needed
      await this.initializeSystemMonitoring();

      logger.debug('System components initialized successfully');
    } catch (error) {
      logger.error('Failed to initialize system components:', error);
      throw error;
    }
  }

  /**
   * Perform startup system checks
   */
  private async performStartupChecks(): Promise<void> {
    try {
      // Basic system health check on startup
      const statusCommand = this.handlers.get('/status') as StatusCommand;
      if (statusCommand) {
        logger.debug('System status verified on startup');
      }

      // Check if system diagnostics are available
      const doctorCommand = this.handlers.get('/doctor') as DoctorCommand;
      if (doctorCommand) {
        logger.debug('System diagnostics available');
      }

      // Verify terminal setup capabilities
      const terminalSetupCommand = this.handlers.get('/terminal-setup') as TerminalSetupCommand;
      if (terminalSetupCommand) {
        logger.debug('Terminal setup capabilities available');
      }

    } catch (error) {
      logger.warn('Startup checks encountered issues:', error);
      // Don't throw - these are non-critical checks
    }
  }

  /**
   * Initialize system monitoring
   */
  private async initializeSystemMonitoring(): Promise<void> {
    // This would initialize any background monitoring if needed
    // For now, it's just logging
    logger.debug('System monitoring initialized');
  }

  /**
   * Get system service statistics
   */
  getSystemStats() {
    const stats = this.getServiceInfo();
    
    return {
      ...stats,
      aliases: {
        status: ['/st', '/info', '/sys'],
        doctor: ['/dr', '/health', '/check'],
        'terminal-setup': ['/term', '/tsetup', '/terminal'],
      },
      description: 'System management, diagnostics, and terminal configuration commands',
      capabilities: {
        systemStatus: true,
        healthChecks: true,
        terminalSetup: true,
        diagnostics: true,
        monitoring: true,
      },
    };
  }

  /**
   * Check if all system commands are functional
   */
  async healthCheck(): Promise<boolean> {
    try {
      const essentialCommands = ['/status', '/doctor', '/terminal-setup'];
      
      for (const command of essentialCommands) {
        if (!this.hasCommand(command)) {
          logger.error(`Essential system command missing: ${command}`);
          return false;
        }
      }

      logger.info('System command service health check passed');
      return true;
    } catch (error) {
      logger.error('System command service health check failed:', error);
      return false;
    }
  }

  /**
   * Get system service diagnostics
   */
  async getDiagnostics() {
    const diagnostics = {
      service: 'system',
      status: 'healthy',
      commands: this.getAvailableCommands(),
      aliases: Object.keys(this.handlers).filter(key => !key.startsWith('/')),
      uptime: process.uptime(),
      lastCheck: new Date().toISOString(),
      issues: [] as string[],
    };

    // Check for any issues
    try {
      const healthCheck = await this.healthCheck();
      if (!healthCheck) {
        diagnostics.status = 'unhealthy';
        diagnostics.issues.push('Health check failed');
      }
    } catch (error) {
      diagnostics.status = 'error';
      diagnostics.issues.push(`Health check error: ${error instanceof Error ? error.message : 'Unknown error'}`);
    }

    return diagnostics;
  }

  /**
   * Cleanup system resources
   */
  override async cleanup(): Promise<void> {
    logger.info('Cleaning up SystemCommandService');

    // Stop any monitoring or background processes
    await this.stopSystemMonitoring();

    // Call parent cleanup
    await super.cleanup();

    logger.info('SystemCommandService cleanup complete');
  }

  /**
   * Stop system monitoring
   */
  private async stopSystemMonitoring(): Promise<void> {
    // This would stop any background monitoring
    logger.debug('System monitoring stopped');
  }
}