/**
 * Help Command
 * Displays help information for commands and system usage
 */

import { BaseCommand } from '../../../base-command';
import { CommandArgs, CommandContext, CommandResult, CommandExample } from '../../../types';
import { commandRegistry } from '../../../registry';
import { logger } from '../../../../utils/logger';

export class HelpCommand extends BaseCommand {
  name = 'help';
  category = 'core' as const;
  description = '📚 Display help information for commands and system usage';
  override aliases = ['h', '?'];
  override usage = '[command] [--category <category>] [--search <term>]';
  
  override examples: CommandExample[] = [
    {
      input: '/help',
      description: 'Show general help and command overview',
      output: 'Complete command reference with categories',
    },
    {
      input: '/help clear',
      description: 'Show detailed help for the clear command',
      output: 'Usage, examples, and options for /clear',
    },
    {
      input: '/help --category core',
      description: 'Show all commands in the core category',
      output: 'List of core system commands',
    },
    {
      input: '/help --search "config"',
      description: 'Search for commands related to configuration',
      output: 'Commands matching "config" in name or description',
    },
  ];

  async execute(args: CommandArgs, _context: CommandContext): Promise<CommandResult> {
    try {
      const { options, parsed } = args;
      const positional = (parsed['positional'] as string[]) || [];

      // If specific command requested
      if (positional.length > 0) {
        const commandName = positional[0];
        if (commandName) {
          return await this.showCommandHelp(commandName);
        }
      }

      // If category filter requested
      if (options['category']) {
        return await this.showCategoryHelp(options['category']);
      }

      // If search requested
      if (options['search']) {
        return await this.searchCommands(options['search']);
      }

      // Show general help
      return await this.showGeneralHelp();

    } catch (error) {
      logger.error('Help command failed:', error);
      return this.error(
        'Failed to display help information',
        'HELP_ERROR',
        error instanceof Error ? error.message : 'Unknown error'
      );
    }
  }

  /**
   * Show help for a specific command
   */
  private async showCommandHelp(commandName: string): Promise<CommandResult> {
    // Remove leading slash if present
    const cleanName = commandName.startsWith('/') ? commandName.slice(1) : commandName;
    const fullName = `/${cleanName}`;

    // Check if command exists in new system
    const command = commandRegistry.get(fullName);
    if (command) {
      // Format help text for the command
      const helpText = `Help for ${fullName}\n\nDescription: ${command.description}\nUsage: ${command.usage || 'No usage information available'}\nCategory: ${command.category}`;
      return this.success(helpText, {
        command: fullName,
        type: 'command-specific',
        source: 'new-system',
      });
    }

    // TODO: Check legacy system for command help
    return this.error(
      `Command not found: ${fullName}`,
      'COMMAND_NOT_FOUND',
      {
        suggestions: this.getCommandSuggestions(cleanName),
      }
    );
  }

  /**
   * Show all commands in a category
   */
  private async showCategoryHelp(category: string): Promise<CommandResult> {
    const commands = commandRegistry.getByCategory(category);
    
    if (commands.length === 0) {
      return this.error(
        `No commands found in category: ${category}`,
        'CATEGORY_NOT_FOUND',
        {
          availableCategories: this.getAvailableCategories(),
        }
      );
    }

    const helpText = this.formatCategoryHelp(category, commands);
    return this.success(helpText, {
      category,
      commandCount: commands.length,
      type: 'category-specific',
    });
  }

  /**
   * Search commands by name or description
   */
  private async searchCommands(searchTerm: string): Promise<CommandResult> {
    const allCommands = commandRegistry.getAll();
    const matches = allCommands.filter(cmd => 
      cmd.name.toLowerCase().includes(searchTerm.toLowerCase()) ||
      cmd.description.toLowerCase().includes(searchTerm.toLowerCase()) ||
      (cmd.aliases && cmd.aliases.some(alias => alias.toLowerCase().includes(searchTerm.toLowerCase())))
    );

    if (matches.length === 0) {
      return this.error(
        `No commands found matching: "${searchTerm}"`,
        'NO_SEARCH_RESULTS',
        {
          suggestion: 'Try a different search term or use /help to see all commands',
        }
      );
    }

    const helpText = this.formatSearchResults(searchTerm, matches);
    return this.success(helpText, {
      searchTerm,
      matchCount: matches.length,
      type: 'search-results',
    });
  }

  /**
   * Show general help and overview
   */
  private async showGeneralHelp(): Promise<CommandResult> {
    const allCommands = commandRegistry.getAll();
    const categories = this.groupCommandsByCategory(allCommands);

    const helpText = this.formatGeneralHelp(categories);
    return this.success(helpText, {
      totalCommands: allCommands.length,
      categories: Object.keys(categories),
      type: 'general-overview',
    });
  }

  /**
   * Format general help text
   */
  private formatGeneralHelp(categories: Record<string, any[]>): string {
    const lines: string[] = [];

    // Header
    lines.push('');
    lines.push('🚀 MARIA CODE - AI-Powered Development Assistant');
    lines.push('═'.repeat(60));
    lines.push('');
    lines.push('📚 **COMMAND REFERENCE**');
    lines.push('');

    // Quick start
    lines.push('**🏃‍♂️ Quick Start:**');
    lines.push('  /help <command>     - Get detailed help for any command');
    lines.push('  /setup             - First-time environment setup');
    lines.push('  /clear             - Clear conversation context');
    lines.push('  /status            - Check system status');
    lines.push('');

    // Categories
    for (const [category, commands] of Object.entries(categories)) {
      const categoryEmoji = this.getCategoryEmoji(category);
      lines.push(`**${categoryEmoji} ${category.toUpperCase()} (${commands.length})**`);
      
      for (const command of commands.slice(0, 5)) { // Show max 5 per category
        const aliases = command.aliases && command.aliases.length > 0 
          ? ` (${command.aliases.map((a: string) => `/${a}`).join(', ')})` 
          : '';
        lines.push(`  /${command.name}${aliases.padEnd(15)} - ${command.description}`);
      }
      
      if (commands.length > 5) {
        lines.push(`  ... and ${commands.length - 5} more commands`);
      }
      lines.push('');
    }

    // Usage tips
    lines.push('**💡 Usage Tips:**');
    lines.push('  • Use /help --category <name> to see all commands in a category');
    lines.push('  • Use /help --search <term> to search for specific commands');
    lines.push('  • Most commands support --help flag for quick reference');
    lines.push('  • Tab completion is available for command names and options');
    lines.push('');

    // Footer
    lines.push('**🔗 More Information:**');
    lines.push('  • Documentation: https://docs.maria-code.ai');
    lines.push('  • GitHub: https://github.com/bonginkan/maria');
    lines.push('  • Support: https://discord.gg/maria-code');
    lines.push('');

    return lines.join('\n');
  }

  /**
   * Format category help text
   */
  private formatCategoryHelp(category: string, commands: any[]): string {
    const lines: string[] = [];
    const categoryEmoji = this.getCategoryEmoji(category);

    lines.push('');
    lines.push(`${categoryEmoji} ${category.toUpperCase()} COMMANDS`);
    lines.push('═'.repeat(40));
    lines.push('');

    for (const command of commands) {
      lines.push(`**/${command.name}**`);
      lines.push(`  ${command.description}`);
      
      if (command.aliases && command.aliases.length > 0) {
        lines.push(`  Aliases: ${command.aliases.map((a: string) => `/${a}`).join(', ')}`);
      }
      
      if (command.usage) {
        lines.push(`  Usage: /${command.name} ${command.usage}`);
      }
      
      lines.push('');
    }

    return lines.join('\n');
  }

  /**
   * Format search results
   */
  private formatSearchResults(searchTerm: string, matches: any[]): string {
    const lines: string[] = [];

    lines.push('');
    lines.push(`🔍 SEARCH RESULTS FOR "${searchTerm}"`);
    lines.push('═'.repeat(40));
    lines.push('');
    lines.push(`Found ${matches.length} matching commands:`);
    lines.push('');

    for (const command of matches) {
      lines.push(`**/${command.name}** (${command.category})`);
      lines.push(`  ${command.description}`);
      
      // Highlight matching terms
      const description = command.description.toLowerCase();
      if (description.includes(searchTerm.toLowerCase())) {
        const highlighted = command.description.replace(
          new RegExp(searchTerm, 'gi'),
          `**$&**`
        );
        lines.push(`  Match: ${highlighted}`);
      }
      
      lines.push('');
    }

    return lines.join('\n');
  }

  /**
   * Group commands by category
   */
  private groupCommandsByCategory(commands: any[]): Record<string, any[]> {
    const grouped: Record<string, any[]> = {};

    for (const command of commands) {
      if (!grouped[command.category]) {
        grouped[command.category] = [];
      }
      grouped[command.category]?.push(command);
    }

    // Sort commands within each category
    for (const category in grouped) {
      grouped[category]?.sort((a, b) => a.name.localeCompare(b.name));
    }

    return grouped;
  }

  /**
   * Get emoji for category
   */
  private getCategoryEmoji(category: string): string {
    const emojiMap: Record<string, string> = {
      core: '⚡',
      system: '🛠️',
      configuration: '⚙️',
      conversation: '💬',
      generation: '🎨',
      analysis: '🔍',
      auth: '🔐',
      project: '📁',
      utilities: '🔧',
      media: '🎬',
      integration: '🔗',
    };

    return emojiMap[category] || '📋';
  }

  /**
   * Get available categories
   */
  private getAvailableCategories(): string[] {
    const allCommands = commandRegistry.getAll();
    const categories = new Set(allCommands.map(cmd => cmd.category));
    return Array.from(categories).sort();
  }

  /**
   * Get command suggestions for typos
   */
  private getCommandSuggestions(input: string): string[] {
    const allCommands = commandRegistry.getAll();
    const suggestions: string[] = [];

    for (const command of allCommands) {
      if (command.name.toLowerCase().includes(input.toLowerCase()) ||
          input.toLowerCase().includes(command.name.toLowerCase())) {
        suggestions.push(`/${command.name}`);
      }
    }

    return suggestions.slice(0, 5);
  }

  /**
   * Validation for help command
   */
  override async validate(args: CommandArgs): Promise<{ success: boolean; error?: string }> {
    const { options } = args;

    // Validate category if provided
    if (options['category']) {
      const availableCategories = this.getAvailableCategories();
      if (!availableCategories.includes(options['category'])) {
        return {
          success: false,
          error: `Unknown category: ${options['category']}. Available: ${availableCategories.join(', ')}`,
        };
      }
    }

    // Validate search term if provided
    if (options['search'] && typeof options['search'] !== 'string') {
      return {
        success: false,
        error: 'Search term must be a string',
      };
    }

    return { success: true };
  }
}