import { EventEmitter } from 'events';
import * as WebSocket from 'ws';
import { createHash } from 'crypto';

export interface StreamingConfig {
    port: number;
    host: string;
    maxConnections: number;
    heartbeatInterval: number;
    compressionEnabled: boolean;
    rateLimiting: RateLimitConfig;
    authentication: AuthConfig;
}

export interface RateLimitConfig {
    enabled: boolean;
    messagesPerMinute: number;
    burstSize: number;
}

export interface AuthConfig {
    enabled: boolean;
    tokenValidation: (token: string) => Promise<boolean>;
    permissions: (token: string) => Promise<string[]>;
}

export interface StreamSubscription {
    id: string;
    clientId: string;
    topic: string;
    filters: StreamFilter[];
    lastActivity: Date;
    messageCount: number;
    rateLimiter: RateLimiter;
}

export interface StreamFilter {
    field: string;
    operator: 'eq' | 'neq' | 'gt' | 'gte' | 'lt' | 'lte' | 'contains' | 'regex';
    value: any;
}

export interface StreamMessage {
    id: string;
    timestamp: Date;
    topic: string;
    type: 'data' | 'event' | 'alert' | 'system';
    payload: any;
    metadata: Record<string, any>;
}

export interface ClientConnection {
    id: string;
    socket: WebSocket;
    authenticated: boolean;
    permissions: string[];
    subscriptions: Map<string, StreamSubscription>;
    lastPing: Date;
    rateLimiter: RateLimiter;
    metadata: Record<string, any>;
}

export interface DataStream {
    topic: string;
    source: StreamSource;
    buffer: CircularBuffer<StreamMessage>;
    subscribers: Set<string>;
    lastUpdate: Date;
    messageCount: number;
    compressionRatio: number;
}

export interface StreamSource {
    type: 'metrics' | 'logs' | 'events' | 'custom';
    provider: string;
    config: Record<string, any>;
    enabled: boolean;
    healthCheck?: () => Promise<boolean>;
}

export interface StreamMetrics {
    connections: {
        active: number;
        total: number;
        authenticated: number;
    };
    messages: {
        sent: number;
        received: number;
        dropped: number;
        rateLimited: number;
    };
    streams: {
        active: number;
        subscribers: number;
        averageLatency: number;
    };
    performance: {
        memoryUsage: number;
        cpuUsage: number;
        uptime: number;
    };
}

class RateLimiter {
    private tokens: number;
    private lastRefill: number;
    private maxTokens: number;
    private refillRate: number;

    constructor(maxTokens: number, refillRate: number) {
        this.maxTokens = maxTokens;
        this.tokens = maxTokens;
        this.refillRate = refillRate;
        this.lastRefill = Date.now();
    }

    consume(tokens: number = 1): boolean {
        this.refill();
        
        if (this.tokens >= tokens) {
            this.tokens -= tokens;
            return true;
        }
        
        return false;
    }

    private refill(): void {
        const now = Date.now();
        const timePassed = now - this.lastRefill;
        const tokensToAdd = Math.floor((timePassed / 1000) * this.refillRate);
        
        this.tokens = Math.min(this.maxTokens, this.tokens + tokensToAdd);
        this.lastRefill = now;
    }
}

class CircularBuffer<T> {
    private buffer: T[];
    private head: number = 0;
    private tail: number = 0;
    private size: number = 0;

    constructor(private capacity: number) {
        this.buffer = new Array(capacity);
    }

    push(item: T): void {
        this.buffer[this.tail] = item;
        this.tail = (this.tail + 1) % this.capacity;
        
        if (this.size < this.capacity) {
            this.size++;
        } else {
            this.head = (this.head + 1) % this.capacity;
        }
    }

    getAll(): T[] {
        if (this.size === 0) return [];
        
        const result: T[] = [];
        for (let i = 0; i < this.size; i++) {
            const index = (this.head + i) % this.capacity;
            result.push(this.buffer[index]);
        }
        return result;
    }

    getLast(count: number): T[] {
        const all = this.getAll();
        return all.slice(-count);
    }

    clear(): void {
        this.head = 0;
        this.tail = 0;
        this.size = 0;
    }

    isFull(): boolean {
        return this.size === this.capacity;
    }

    getSize(): number {
        return this.size;
    }
}

export class RealTimeStreamingSystem extends EventEmitter {
    private server?: WebSocket.Server;
    private clients = new Map<string, ClientConnection>();
    private streams = new Map<string, DataStream>();
    private subscriptions = new Map<string, StreamSubscription>();
    private config: StreamingConfig;
    private metrics: StreamMetrics;
    private heartbeatTimer?: NodeJS.Timer;

    constructor(config: StreamingConfig) {
        super();
        this.config = config;
        this.metrics = this.initializeMetrics();
    }

    async start(): Promise<void> {
        this.server = new WebSocket.Server({
            port: this.config.port,
            host: this.config.host,
            maxPayload: 1024 * 1024, // 1MB
            perMessageDeflate: this.config.compressionEnabled
        });

        this.server.on('connection', (socket, request) => {
            this.handleConnection(socket, request);
        });

        this.server.on('error', (error) => {
            this.emit('server-error', error);
        });

        // Start heartbeat
        this.heartbeatTimer = setInterval(() => {
            this.sendHeartbeats();
        }, this.config.heartbeatInterval);

        this.emit('server-started', {
            host: this.config.host,
            port: this.config.port
        });
    }

    async stop(): Promise<void> {
        if (this.heartbeatTimer) {
            clearInterval(this.heartbeatTimer);
        }

        if (this.server) {
            this.server.close();
            this.server = undefined;
        }

        // Close all client connections
        for (const client of this.clients.values()) {
            client.socket.close();
        }
        this.clients.clear();

        this.emit('server-stopped');
    }

    private handleConnection(socket: WebSocket, request: any): void {
        if (this.clients.size >= this.config.maxConnections) {
            socket.close(4000, 'Server at capacity');
            return;
        }

        const clientId = this.generateClientId();
        const client: ClientConnection = {
            id: clientId,
            socket,
            authenticated: !this.config.authentication.enabled,
            permissions: [],
            subscriptions: new Map(),
            lastPing: new Date(),
            rateLimiter: new RateLimiter(
                this.config.rateLimiting.messagesPerMinute,
                this.config.rateLimiting.messagesPerMinute / 60
            ),
            metadata: {
                remoteAddress: request.socket.remoteAddress,
                userAgent: request.headers['user-agent'],
                connectedAt: new Date()
            }
        };

        this.clients.set(clientId, client);
        this.metrics.connections.total++;
        this.metrics.connections.active++;

        // Setup message handlers
        socket.on('message', async (data) => {
            await this.handleClientMessage(clientId, data);
        });

        socket.on('close', () => {
            this.handleClientDisconnect(clientId);
        });

        socket.on('error', (error) => {
            this.emit('client-error', { clientId, error });
            this.handleClientDisconnect(clientId);
        });

        // Send welcome message
        this.sendToClient(clientId, {
            type: 'welcome',
            payload: {
                clientId,
                serverTime: new Date().toISOString(),
                requiresAuth: this.config.authentication.enabled
            }
        });

        this.emit('client-connected', { clientId, metadata: client.metadata });
    }

    private async handleClientMessage(clientId: string, data: WebSocket.Data): Promise<void> {
        const client = this.clients.get(clientId);
        if (!client) return;

        // Rate limiting
        if (!client.rateLimiter.consume()) {
            this.metrics.messages.rateLimited++;
            this.sendToClient(clientId, {
                type: 'error',
                payload: { message: 'Rate limit exceeded' }
            });
            return;
        }

        try {
            const message = JSON.parse(data.toString());
            this.metrics.messages.received++;

            switch (message.type) {
                case 'auth':
                    await this.handleAuthentication(clientId, message.payload);
                    break;
                case 'subscribe':
                    await this.handleSubscription(clientId, message.payload);
                    break;
                case 'unsubscribe':
                    await this.handleUnsubscription(clientId, message.payload);
                    break;
                case 'ping':
                    this.handlePing(clientId);
                    break;
                case 'query':
                    await this.handleQuery(clientId, message.payload);
                    break;
                default:
                    this.sendToClient(clientId, {
                        type: 'error',
                        payload: { message: 'Unknown message type' }
                    });
            }
        } catch (error) {
            this.sendToClient(clientId, {
                type: 'error',
                payload: { message: 'Invalid message format' }
            });
        }
    }

    private async handleAuthentication(clientId: string, payload: any): Promise<void> {
        const client = this.clients.get(clientId);
        if (!client) return;

        if (!this.config.authentication.enabled) {
            client.authenticated = true;
            this.sendToClient(clientId, {
                type: 'auth-success',
                payload: { authenticated: true }
            });
            return;
        }

        try {
            const isValid = await this.config.authentication.tokenValidation(payload.token);
            
            if (isValid) {
                client.authenticated = true;
                client.permissions = await this.config.authentication.permissions(payload.token);
                this.metrics.connections.authenticated++;

                this.sendToClient(clientId, {
                    type: 'auth-success',
                    payload: { authenticated: true, permissions: client.permissions }
                });
            } else {
                this.sendToClient(clientId, {
                    type: 'auth-failed',
                    payload: { message: 'Invalid token' }
                });
            }
        } catch (error) {
            this.sendToClient(clientId, {
                type: 'auth-error',
                payload: { message: 'Authentication error' }
            });
        }
    }

    private async handleSubscription(clientId: string, payload: any): Promise<void> {
        const client = this.clients.get(clientId);
        if (!client || !client.authenticated) {
            this.sendToClient(clientId, {
                type: 'error',
                payload: { message: 'Authentication required' }
            });
            return;
        }

        const { topic, filters = [] } = payload;
        
        // Check permissions
        if (!this.hasPermission(client, 'read', topic)) {
            this.sendToClient(clientId, {
                type: 'subscription-denied',
                payload: { topic, reason: 'Insufficient permissions' }
            });
            return;
        }

        const subscriptionId = this.generateSubscriptionId();
        const subscription: StreamSubscription = {
            id: subscriptionId,
            clientId,
            topic,
            filters,
            lastActivity: new Date(),
            messageCount: 0,
            rateLimiter: new RateLimiter(100, 10) // Per-subscription rate limiting
        };

        this.subscriptions.set(subscriptionId, subscription);
        client.subscriptions.set(subscriptionId, subscription);

        // Add to stream subscribers
        let stream = this.streams.get(topic);
        if (!stream) {
            stream = await this.createStream(topic);
        }
        stream.subscribers.add(subscriptionId);

        this.sendToClient(clientId, {
            type: 'subscription-success',
            payload: { subscriptionId, topic }
        });

        // Send recent data if available
        const recentMessages = stream.buffer.getLast(10);
        for (const message of recentMessages) {
            if (this.messagePassesFilters(message, filters)) {
                this.sendToClient(clientId, {
                    type: 'data',
                    payload: {
                        subscriptionId,
                        message
                    }
                });
            }
        }

        this.emit('subscription-created', { clientId, topic, subscriptionId });
    }

    private async handleUnsubscription(clientId: string, payload: any): Promise<void> {
        const client = this.clients.get(clientId);
        if (!client) return;

        const { subscriptionId } = payload;
        const subscription = this.subscriptions.get(subscriptionId);

        if (subscription && subscription.clientId === clientId) {
            // Remove from stream subscribers
            const stream = this.streams.get(subscription.topic);
            if (stream) {
                stream.subscribers.delete(subscriptionId);
            }

            // Remove from client and global subscriptions
            client.subscriptions.delete(subscriptionId);
            this.subscriptions.delete(subscriptionId);

            this.sendToClient(clientId, {
                type: 'unsubscription-success',
                payload: { subscriptionId }
            });

            this.emit('subscription-removed', { clientId, subscriptionId });
        }
    }

    private handlePing(clientId: string): void {
        const client = this.clients.get(clientId);
        if (client) {
            client.lastPing = new Date();
            this.sendToClient(clientId, {
                type: 'pong',
                payload: { timestamp: Date.now() }
            });
        }
    }

    private async handleQuery(clientId: string, payload: any): Promise<void> {
        const client = this.clients.get(clientId);
        if (!client || !client.authenticated) return;

        const { queryId, topic, timeRange, filters = [] } = payload;

        if (!this.hasPermission(client, 'read', topic)) {
            this.sendToClient(clientId, {
                type: 'query-error',
                payload: { queryId, error: 'Insufficient permissions' }
            });
            return;
        }

        const stream = this.streams.get(topic);
        if (!stream) {
            this.sendToClient(clientId, {
                type: 'query-error',
                payload: { queryId, error: 'Stream not found' }
            });
            return;
        }

        // Get messages within time range
        const allMessages = stream.buffer.getAll();
        let filteredMessages = allMessages.filter(msg => {
            if (timeRange) {
                const msgTime = msg.timestamp.getTime();
                const start = new Date(timeRange.start).getTime();
                const end = new Date(timeRange.end).getTime();
                return msgTime >= start && msgTime <= end;
            }
            return true;
        });

        // Apply filters
        filteredMessages = filteredMessages.filter(msg => 
            this.messagePassesFilters(msg, filters)
        );

        this.sendToClient(clientId, {
            type: 'query-result',
            payload: {
                queryId,
                messages: filteredMessages,
                total: filteredMessages.length
            }
        });
    }

    private handleClientDisconnect(clientId: string): void {
        const client = this.clients.get(clientId);
        if (!client) return;

        // Remove all subscriptions
        for (const subscription of client.subscriptions.values()) {
            const stream = this.streams.get(subscription.topic);
            if (stream) {
                stream.subscribers.delete(subscription.id);
            }
            this.subscriptions.delete(subscription.id);
        }

        this.clients.delete(clientId);
        this.metrics.connections.active--;

        this.emit('client-disconnected', { clientId });
    }

    private sendHeartbeats(): void {
        const now = new Date();
        const timeout = this.config.heartbeatInterval * 2;

        for (const [clientId, client] of this.clients) {
            const timeSinceLastPing = now.getTime() - client.lastPing.getTime();
            
            if (timeSinceLastPing > timeout) {
                // Client is unresponsive, disconnect
                client.socket.close();
                this.handleClientDisconnect(clientId);
            } else {
                // Send ping
                this.sendToClient(clientId, {
                    type: 'ping',
                    payload: { timestamp: Date.now() }
                });
            }
        }
    }

    async createStream(topic: string, source?: StreamSource): Promise<DataStream> {
        const stream: DataStream = {
            topic,
            source: source || {
                type: 'custom',
                provider: 'manual',
                config: {},
                enabled: true
            },
            buffer: new CircularBuffer(1000), // Keep last 1000 messages
            subscribers: new Set(),
            lastUpdate: new Date(),
            messageCount: 0,
            compressionRatio: 1.0
        };

        this.streams.set(topic, stream);
        this.emit('stream-created', { topic, source: stream.source });
        
        return stream;
    }

    async publishMessage(topic: string, message: Omit<StreamMessage, 'id' | 'timestamp'>): Promise<void> {
        const stream = this.streams.get(topic);
        if (!stream) {
            await this.createStream(topic);
        }

        const fullMessage: StreamMessage = {
            id: this.generateMessageId(),
            timestamp: new Date(),
            topic,
            ...message
        };

        // Add to stream buffer
        const targetStream = this.streams.get(topic)!;
        targetStream.buffer.push(fullMessage);
        targetStream.lastUpdate = new Date();
        targetStream.messageCount++;

        // Send to subscribers
        const subscribersToNotify = Array.from(targetStream.subscribers);
        
        for (const subscriptionId of subscribersToNotify) {
            const subscription = this.subscriptions.get(subscriptionId);
            if (!subscription) continue;

            // Check rate limiting
            if (!subscription.rateLimiter.consume()) {
                continue;
            }

            // Check filters
            if (!this.messagePassesFilters(fullMessage, subscription.filters)) {
                continue;
            }

            const client = this.clients.get(subscription.clientId);
            if (client && client.socket.readyState === WebSocket.OPEN) {
                this.sendToClient(subscription.clientId, {
                    type: 'data',
                    payload: {
                        subscriptionId,
                        message: fullMessage
                    }
                });

                subscription.messageCount++;
                subscription.lastActivity = new Date();
            }
        }

        this.metrics.messages.sent += subscribersToNotify.length;
        this.emit('message-published', { topic, messageId: fullMessage.id, subscribers: subscribersToNotify.length });
    }

    private messagePassesFilters(message: StreamMessage, filters: StreamFilter[]): boolean {
        for (const filter of filters) {
            const fieldValue = this.getNestedValue(message.payload, filter.field);
            
            switch (filter.operator) {
                case 'eq':
                    if (fieldValue !== filter.value) return false;
                    break;
                case 'neq':
                    if (fieldValue === filter.value) return false;
                    break;
                case 'gt':
                    if (Number(fieldValue) <= Number(filter.value)) return false;
                    break;
                case 'gte':
                    if (Number(fieldValue) < Number(filter.value)) return false;
                    break;
                case 'lt':
                    if (Number(fieldValue) >= Number(filter.value)) return false;
                    break;
                case 'lte':
                    if (Number(fieldValue) > Number(filter.value)) return false;
                    break;
                case 'contains':
                    if (!String(fieldValue).includes(String(filter.value))) return false;
                    break;
                case 'regex':
                    if (!new RegExp(filter.value).test(String(fieldValue))) return false;
                    break;
            }
        }
        
        return true;
    }

    private sendToClient(clientId: string, message: any): void {
        const client = this.clients.get(clientId);
        if (client && client.socket.readyState === WebSocket.OPEN) {
            try {
                client.socket.send(JSON.stringify(message));
            } catch (error) {
                this.emit('send-error', { clientId, error });
                this.handleClientDisconnect(clientId);
            }
        }
    }

    private hasPermission(client: ClientConnection, action: string, resource: string): boolean {
        if (!this.config.authentication.enabled) return true;
        
        return client.permissions.includes('*') || 
               client.permissions.includes(`${action}:*`) ||
               client.permissions.includes(`${action}:${resource}`);
    }

    private getNestedValue(obj: any, path: string): any {
        return path.split('.').reduce((current, key) => current?.[key], obj);
    }

    private generateClientId(): string {
        return `client_${Date.now()}_${Math.random().toString(36).substr(2, 9)}`;
    }

    private generateSubscriptionId(): string {
        return `sub_${Date.now()}_${Math.random().toString(36).substr(2, 9)}`;
    }

    private generateMessageId(): string {
        return createHash('sha256')
            .update(`${Date.now()}_${Math.random()}`)
            .digest('hex')
            .substring(0, 16);
    }

    private initializeMetrics(): StreamMetrics {
        return {
            connections: { active: 0, total: 0, authenticated: 0 },
            messages: { sent: 0, received: 0, dropped: 0, rateLimited: 0 },
            streams: { active: 0, subscribers: 0, averageLatency: 0 },
            performance: { memoryUsage: 0, cpuUsage: 0, uptime: Date.now() }
        };
    }

    // Public API methods
    getMetrics(): StreamMetrics {
        this.updatePerformanceMetrics();
        return { ...this.metrics };
    }

    getActiveStreams(): string[] {
        return Array.from(this.streams.keys());
    }

    getStreamInfo(topic: string): DataStream | undefined {
        return this.streams.get(topic);
    }

    getConnectedClients(): number {
        return this.clients.size;
    }

    getSubscriptions(topic?: string): StreamSubscription[] {
        const subscriptions = Array.from(this.subscriptions.values());
        return topic ? subscriptions.filter(sub => sub.topic === topic) : subscriptions;
    }

    async closeStream(topic: string): Promise<void> {
        const stream = this.streams.get(topic);
        if (!stream) return;

        // Notify all subscribers
        for (const subscriptionId of stream.subscribers) {
            const subscription = this.subscriptions.get(subscriptionId);
            if (subscription) {
                this.sendToClient(subscription.clientId, {
                    type: 'stream-closed',
                    payload: { topic, reason: 'Stream closed by server' }
                });
            }
        }

        // Remove stream and subscriptions
        this.streams.delete(topic);
        
        for (const subscriptionId of stream.subscribers) {
            this.subscriptions.delete(subscriptionId);
        }

        this.emit('stream-closed', { topic });
    }

    private updatePerformanceMetrics(): void {
        const usage = process.memoryUsage();
        this.metrics.performance.memoryUsage = usage.heapUsed;
        this.metrics.performance.uptime = Date.now() - this.metrics.performance.uptime;
        
        // Update stream metrics
        this.metrics.streams.active = this.streams.size;
        this.metrics.streams.subscribers = Array.from(this.streams.values())
            .reduce((total, stream) => total + stream.subscribers.size, 0);
    }

    destroy(): void {
        if (this.server) {
            this.stop();
        }

        this.clients.clear();
        this.streams.clear();
        this.subscriptions.clear();
        this.removeAllListeners();
    }
}