/**
 * RealTimeFeedbackManager Component
 * Manages real-time feedback, notifications, and status updates
 */

import chalk from 'chalk';
import { EventEmitter } from 'events';
import { EnhancedProgressReporter, ProgressSessionConfig } from './EnhancedProgressReporter.js';
import { EnhancedModeIndicator, ModeDisplayConfig } from './EnhancedModeIndicator.js';

/**
 * Feedback types
 */
export type FeedbackType = 'info' | 'success' | 'warning' | 'error' | 'progress' | 'mode';

/**
 * Feedback message
 */
export interface FeedbackMessage {
  id: string;
  type: FeedbackType;
  message: string;
  details?: string;
  timestamp: Date;
  duration?: number; // Auto-dismiss after ms
  persistent?: boolean;
  metadata?: Record<string, any>;
}

/**
 * Real-time feedback configuration
 */
export interface RealTimeFeedbackConfig {
  showTimestamps?: boolean;
  enableSounds?: boolean;
  maxMessages?: number;
  defaultDuration?: number;
  enableNotifications?: boolean;
  compactMode?: boolean;
}

/**
 * Real-time feedback manager class
 */
export class RealTimeFeedbackManager extends EventEmitter {
  private config: Required<RealTimeFeedbackConfig>;
  private messages: Map<string, FeedbackMessage> = new Map();
  private messageOrder: string[] = [];
  private progressReporter: EnhancedProgressReporter | null = null;
  private modeIndicator: EnhancedModeIndicator | null = null;
  private activeTimers: Map<string, NodeJS.Timeout> = new Map();

  // Feedback icons and colors
  private readonly feedbackStyles = {
    info: { icon: 'ℹ️', color: 'blue', sound: '\x07' },
    success: { icon: '✅', color: 'green', sound: '\x07\x07' },
    warning: { icon: '⚠️', color: 'yellow', sound: '\x07\x07\x07' },
    error: { icon: '❌', color: 'red', sound: '\x07\x07\x07\x07' },
    progress: { icon: '⏳', color: 'cyan', sound: '' },
    mode: { icon: '🧠', color: 'magenta', sound: '\x07' },
  };

  constructor(config: RealTimeFeedbackConfig = {}) {
    super();
    this.config = {
      showTimestamps: config.showTimestamps ?? true,
      enableSounds: config.enableSounds ?? false,
      maxMessages: config.maxMessages ?? 50,
      defaultDuration: config.defaultDuration ?? 5000,
      enableNotifications: config.enableNotifications ?? true,
      compactMode: config.compactMode ?? false,
    };
    
    // Initialize components
    this.initializeModeIndicator();
  }

  /**
   * Initialize mode indicator
   */
  private initializeModeIndicator(): void {
    const modeConfig: ModeDisplayConfig = {
      showAnimations: true,
      showDescription: !this.config.compactMode,
      showIntensity: true,
      compactMode: this.config.compactMode,
      autoHide: false,
    };
    
    this.modeIndicator = new EnhancedModeIndicator(modeConfig);
    
    // Forward mode events
    this.modeIndicator.on('mode-changed', (transition) => {
      this.emit('mode-changed', transition);
    });
  }

  /**
   * Show feedback message
   */
  showMessage(type: FeedbackType, message: string, options: {
    details?: string;
    duration?: number;
    persistent?: boolean;
    metadata?: Record<string, any>;
  } = {}): string {
    const id = this.generateId();
    const feedbackMessage: FeedbackMessage = {
      id,
      type,
      message,
      details: options.details,
      timestamp: new Date(),
      duration: options.duration ?? this.config.defaultDuration,
      persistent: options.persistent ?? false,
      metadata: options.metadata,
    };

    this.addMessage(feedbackMessage);
    this.displayMessage(feedbackMessage);
    
    // Auto-dismiss if not persistent
    if (!feedbackMessage.persistent && feedbackMessage.duration && feedbackMessage.duration > 0) {
      this.scheduleAutoDismiss(id, feedbackMessage.duration);
    }

    this.emit('message-shown', feedbackMessage);
    return id;
  }

  /**
   * Show info message
   */
  info(message: string, details?: string, duration?: number): string {
    return this.showMessage('info', message, { details, duration });
  }

  /**
   * Show success message
   */
  success(message: string, details?: string, duration?: number): string {
    return this.showMessage('success', message, { details, duration });
  }

  /**
   * Show warning message
   */
  warning(message: string, details?: string, duration?: number): string {
    return this.showMessage('warning', message, { details, duration });
  }

  /**
   * Show error message
   */
  error(message: string, details?: string, persistent: boolean = true): string {
    return this.showMessage('error', message, { details, persistent });
  }

  /**
   * Show progress update
   */
  progress(message: string, percentage?: number): string {
    const details = percentage !== undefined ? `${percentage.toFixed(0)}% complete` : undefined;
    return this.showMessage('progress', message, { details, duration: 1000 });
  }

  /**
   * Start progress session
   */
  startProgressSession(config: ProgressSessionConfig): EnhancedProgressReporter {
    if (this.progressReporter) {
      this.progressReporter.destroy();
    }
    
    this.progressReporter = new EnhancedProgressReporter(config);
    
    // Forward progress events
    this.progressReporter.on('session-start', (data) => {
      this.emit('progress-session-start', data);
    });
    
    this.progressReporter.on('step-updated', (step) => {
      this.emit('progress-step-updated', step);
    });
    
    this.progressReporter.on('session-complete', (data) => {
      this.emit('progress-session-complete', data);
      this.progressReporter = null;
    });
    
    this.progressReporter.start();
    return this.progressReporter;
  }

  /**
   * Switch mode
   */
  switchMode(mode: any, reason?: string, confidence?: number): void {
    if (this.modeIndicator) {
      this.modeIndicator.switchMode(mode, reason, confidence);
    }
  }

  /**
   * Show typing indicator
   */
  showTypingIndicator(message: string = 'Processing'): string {
    const frames = ['⠋', '⠙', '⠹', '⠸', '⠼', '⠴', '⠦', '⠧', '⠇', '⠏'];
    let frameIndex = 0;
    
    const indicatorId = this.generateId();
    
    const animate = () => {
      const frame = frames[frameIndex % frames.length];
      process.stdout.write(`\r${chalk.blue(frame)} ${message}...`);
      frameIndex++;
    };
    
    const interval = setInterval(animate, 100);
    animate(); // Show immediately
    
    // Store cleanup function
    this.activeTimers.set(indicatorId, interval as any);
    
    return indicatorId;
  }

  /**
   * Hide typing indicator
   */
  hideTypingIndicator(id: string): void {
    const timer = this.activeTimers.get(id);
    if (timer) {
      clearInterval(timer);
      this.activeTimers.delete(id);
      process.stdout.write('\r' + ' '.repeat(50) + '\r'); // Clear line
    }
  }

  /**
   * Show network status
   */
  showNetworkStatus(online: boolean, provider?: string): void {
    if (online) {
      const message = provider ? `Connected to ${provider}` : 'Network connection restored';
      this.success(message, 'Cloud services available');
    } else {
      this.warning('Network offline', 'Using local processing only');
    }
  }

  /**
   * Show processing status
   */
  showProcessingStatus(status: 'start' | 'progress' | 'complete' | 'error', operation: string, details?: string): void {
    switch (status) {
      case 'start':
        this.info(`Starting ${operation}`, details);
        break;
      case 'progress':
        this.progress(operation, undefined);
        break;
      case 'complete':
        this.success(`Completed ${operation}`, details);
        break;
      case 'error':
        this.error(`Failed ${operation}`, details);
        break;
    }
  }

  /**
   * Display message
   */
  private displayMessage(message: FeedbackMessage): void {
    const style = this.feedbackStyles[message.type];
    const color = chalk[style.color as keyof typeof chalk] as any;
    const timestamp = this.config.showTimestamps 
      ? chalk.gray(`[${message.timestamp.toLocaleTimeString()}] `)
      : '';

    if (this.config.compactMode) {
      console.log(`${timestamp}${style.icon} ${message.message}`);
    } else {
      console.log(`${timestamp}${color(style.icon)} ${color(message.message)}`);
      
      if (message.details) {
        console.log(chalk.gray(`   ${message.details}`));
      }
    }

    // Play sound if enabled
    if (this.config.enableSounds && style.sound) {
      process.stdout.write(style.sound);
    }
  }

  /**
   * Add message to collection
   */
  private addMessage(message: FeedbackMessage): void {
    this.messages.set(message.id, message);
    this.messageOrder.unshift(message.id);
    
    // Limit message history
    if (this.messageOrder.length > this.config.maxMessages) {
      const oldestId = this.messageOrder.pop()!;
      this.messages.delete(oldestId);
      
      // Clean up timer if exists
      const timer = this.activeTimers.get(oldestId);
      if (timer) {
        clearTimeout(timer);
        this.activeTimers.delete(oldestId);
      }
    }
  }

  /**
   * Schedule auto-dismiss
   */
  private scheduleAutoDismiss(messageId: string, duration: number): void {
    const timer = setTimeout(() => {
      this.dismissMessage(messageId);
    }, duration);
    
    this.activeTimers.set(messageId, timer);
  }

  /**
   * Dismiss message
   */
  dismissMessage(messageId: string): void {
    const message = this.messages.get(messageId);
    if (message) {
      this.messages.delete(messageId);
      
      const index = this.messageOrder.indexOf(messageId);
      if (index > -1) {
        this.messageOrder.splice(index, 1);
      }
      
      const timer = this.activeTimers.get(messageId);
      if (timer) {
        clearTimeout(timer);
        this.activeTimers.delete(messageId);
      }
      
      this.emit('message-dismissed', message);
    }
  }

  /**
   * Clear all messages
   */
  clearAll(): void {
    // Clear all timers
    for (const [, timer] of this.activeTimers) {
      clearTimeout(timer);
    }
    
    this.activeTimers.clear();
    this.messages.clear();
    this.messageOrder = [];
    
    this.emit('messages-cleared');
  }

  /**
   * Show message history
   */
  showHistory(limit: number = 10): void {
    const recentMessages = this.messageOrder.slice(0, limit);
    
    if (recentMessages.length === 0) {
      console.log(chalk.gray('No recent messages'));
      return;
    }
    
    console.log(chalk.cyan('\n📋 Recent Messages:'));
    
    for (const id of recentMessages) {
      const message = this.messages.get(id);
      if (message) {
        const style = this.feedbackStyles[message.type];
        const color = chalk[style.color as keyof typeof chalk] as any;
        const timestamp = message.timestamp.toLocaleTimeString();
        
        console.log(`  ${color(style.icon)} ${message.message} ${chalk.gray(`(${timestamp})`)}`);
        
        if (message.details) {
          console.log(chalk.gray(`     ${message.details}`));
        }
      }
    }
  }

  /**
   * Generate unique ID
   */
  private generateId(): string {
    return `feedback-${Date.now()}-${Math.random().toString(36).substr(2, 9)}`;
  }

  /**
   * Get progress reporter
   */
  getProgressReporter(): EnhancedProgressReporter | null {
    return this.progressReporter;
  }

  /**
   * Get mode indicator
   */
  getModeIndicator(): EnhancedModeIndicator | null {
    return this.modeIndicator;
  }

  /**
   * Get all messages
   */
  getMessages(): FeedbackMessage[] {
    return this.messageOrder.map(id => this.messages.get(id)!).filter(Boolean);
  }

  /**
   * Clean up resources
   */
  destroy(): void {
    this.clearAll();
    
    if (this.progressReporter) {
      this.progressReporter.destroy();
      this.progressReporter = null;
    }
    
    if (this.modeIndicator) {
      this.modeIndicator.destroy();
      this.modeIndicator = null;
    }
    
    this.removeAllListeners();
  }
}

export default RealTimeFeedbackManager;