/**
 * Enhanced CLI Interface - Main orchestrator for the visual CLI system
 */
import chalk from 'chalk';
import * as readline from 'readline';
import { InputRenderer, InputBoxConfig } from './InputRenderer';
import { FileDropHandler, DroppedFile } from './FileDropHandler';
import { OCRProcessor, OCRResult } from './OCRProcessor';
import { ReferenceManager } from './ReferenceManager';
import { ResponseRenderer } from './ResponseRenderer';
import { MariaAI } from '../../maria-ai';

export interface EnhancedCLIConfig {
  inputBox: Partial<InputBoxConfig>;
  enableFileDrops: boolean;
  enableOCR: boolean;
  enableImageAnalysis: boolean;
  autoResize: boolean;
  showProgressReports: boolean;
}

export interface CLISession {
  start(): Promise<void>;
  stop(): void;
  processInput(input: string): Promise<void>;
  addFile(filePath: string): Promise<boolean>;
  addURL(url: string): Promise<boolean>;
}

export class EnhancedCLIInterface implements CLISession {
  private inputRenderer: InputRenderer;
  private fileDropHandler: FileDropHandler;
  private ocrProcessor: OCRProcessor;
  private referenceManager: ReferenceManager;
  private responseRenderer: ResponseRenderer;
  private maria: MariaAI;
  private rl: readline.Interface | null = null;
  private running: boolean = false;
  private config: EnhancedCLIConfig;

  constructor(maria: MariaAI, config: Partial<EnhancedCLIConfig> = {}) {
    this.maria = maria;
    this.config = {
      inputBox: {
        width: 120,
        height: 6,
        title: 'MARIA - Enhanced CLI Interface',
        borderStyle: 'single',
        borderColor: 'white',
        textColor: 'white',
      },
      enableFileDrops: true,
      enableOCR: true,
      enableImageAnalysis: true,
      autoResize: true,
      showProgressReports: true,
      ...config,
    };

    // Initialize components
    this.inputRenderer = new InputRenderer(this.config.inputBox);
    this.fileDropHandler = new FileDropHandler({
      enableOCR: this.config.enableOCR,
      enableImageAnalysis: this.config.enableImageAnalysis,
    });
    this.ocrProcessor = new OCRProcessor();
    this.referenceManager = new ReferenceManager();
    this.responseRenderer = new ResponseRenderer({
      maxWidth: this.config.inputBox.width || 120,
      showProgress: this.config.showProgressReports,
    });
  }

  /**
   * Initialize and start the enhanced CLI interface
   */
  async start(): Promise<void> {
    this.running = true;

    try {
      // Display welcome message
      this.displayWelcome();

      // Initialize components
      await this.initializeComponents();

      // Set up readline interface
      this.setupReadlineInterface();

      // Handle terminal resize
      if (this.config.autoResize) {
        this.setupResizeHandler();
      }

      // Main interaction loop
      await this.startInteractionLoop();

    } catch (error) {
      console.log(chalk.red(`❌ Failed to start enhanced CLI: ${error instanceof Error ? error.message : 'Unknown error'}`));
    } finally {
      await this.cleanup();
    }
  }

  /**
   * Stop the CLI interface
   */
  stop(): void {
    this.running = false;
    this.rl?.close();
  }

  /**
   * Display welcome message with visual design
   */
  private displayWelcome(): void {
    console.clear();
    console.log(chalk.blue.bold('╔══════════════════════════════════════════════════════════╗'));
    console.log(chalk.blue.bold('║') + chalk.white.bold('              MARIA Enhanced CLI Interface               ') + chalk.blue.bold('║'));
    console.log(chalk.blue.bold('║') + chalk.gray('       Visual Input Box with File/Image Support        ') + chalk.blue.bold('║'));
    console.log(chalk.blue.bold('╚══════════════════════════════════════════════════════════╝'));
    console.log();
    console.log(chalk.cyan('Features:'));
    console.log(chalk.white('  📦 Visual Input Box (120 chars wide)'));
    console.log(chalk.white('  📎 Drag & Drop Files/Images'));
    console.log(chalk.white('  🔍 OCR Text Extraction'));
    console.log(chalk.white('  🧠 AI Response Outside Input Area'));
    console.log(chalk.white('  ⚡ Real-time Progress Reporting'));
    console.log();
    console.log(chalk.gray('Instructions: Type in the input box, drag files, or use URLs'));
    console.log(chalk.gray('Commands: /help, /exit, /clear, /files, /refs'));
    console.log();
  }

  /**
   * Initialize all components
   */
  private async initializeComponents(): Promise<void> {
    const steps = [
      { id: 'file_handler', description: 'Initializing file drop handler' },
      { id: 'ocr_processor', description: 'Loading OCR processor' },
      { id: 'maria_ai', description: 'Connecting to MARIA AI' },
    ];

    for (const step of steps) {
      this.responseRenderer.displayProgressStep({
        ...step,
        status: 'processing',
        timestamp: new Date(),
      });

      try {
        switch (step.id) {
          case 'file_handler':
            await this.fileDropHandler.initialize();
            break;
          case 'ocr_processor':
            if (this.config.enableOCR) {
              await this.ocrProcessor.initialize();
            }
            break;
          case 'maria_ai':
            await this.maria.initialize();
            break;
        }

        this.responseRenderer.updateProgressStep(step.id, {
          status: 'completed',
          details: 'Ready',
        });

      } catch (error) {
        this.responseRenderer.updateProgressStep(step.id, {
          status: 'failed',
          details: error instanceof Error ? error.message : 'Unknown error',
        });
      }
    }

    console.log();
  }

  /**
   * Set up readline interface
   */
  private setupReadlineInterface(): void {
    this.rl = readline.createInterface({
      input: process.stdin,
      output: process.stdout,
      terminal: true,
      historySize: 100,
    });

    // Handle Ctrl+C
    this.rl.on('SIGINT', () => {
      this.responseRenderer.displayWarning('Use /exit to quit gracefully');
      this.promptForInput();
    });
  }

  /**
   * Set up terminal resize handler
   */
  private setupResizeHandler(): void {
    process.stdout.on('resize', () => {
      this.inputRenderer.autoResize();
      this.redrawInterface();
    });
  }

  /**
   * Main interaction loop
   */
  private async startInteractionLoop(): Promise<void> {
    while (this.running) {
      try {
        // Draw the input box
        this.inputRenderer.drawInputBox();
        
        // Initialize response area
        this.responseRenderer.initializeResponseArea(this.config.inputBox.height || 6);
        
        // Show file summary if files are attached
        this.showAttachedFilesSummary();

        // Get user input
        const input = await this.getUserInput();

        if (!input || !this.running) break;

        // Process the input
        await this.processInput(input);

      } catch (error) {
        this.responseRenderer.displayError(
          'Session error',
          error instanceof Error ? error.message : 'Unknown error'
        );
      }
    }
  }

  /**
   * Get user input with visual feedback
   */
  private getUserInput(): Promise<string> {
    return new Promise((resolve) => {
      if (!this.rl) {
        resolve('');
        return;
      }

      this.rl.question('', (answer) => {
        resolve(answer.trim());
      });
    });
  }

  /**
   * Process user input and handle commands
   */
  async processInput(input: string): Promise<void> {
    if (!input) return;

    // Handle special commands
    if (input.startsWith('/')) {
      await this.handleCommand(input);
      return;
    }

    // Check if input is a URL
    if (this.isURL(input)) {
      await this.addURL(input);
      return;
    }

    // Regular chat input - process with AI
    await this.processChatInput(input);
  }

  /**
   * Process chat input with AI
   */
  private async processChatInput(input: string): Promise<void> {
    try {
      // Start response display
      this.responseRenderer.startResponse();

      // Generate context from references
      const context = this.referenceManager.generateContext();
      const fullInput = input + context;

      // Process any pending OCR tasks
      await this.processOCRTasks();

      // Stream AI response
      const stream = this.maria.chatStream(fullInput);
      let isFirstChunk = true;

      for await (const chunk of stream) {
        this.responseRenderer.streamContent(chunk, isFirstChunk);
        if (isFirstChunk) isFirstChunk = false;
      }

      // Complete response
      this.responseRenderer.completeResponse();

    } catch (error) {
      this.responseRenderer.displayError(
        'AI processing failed',
        error instanceof Error ? error.message : 'Unknown error'
      );
    }
  }

  /**
   * Handle special commands
   */
  private async handleCommand(command: string): Promise<void> {
    const parts = command.split(' ');
    const cmd = parts[0].toLowerCase();
    const args = parts.slice(1);

    switch (cmd) {
      case '/help':
        this.showHelp();
        break;

      case '/exit':
      case '/quit':
        this.running = false;
        break;

      case '/clear':
        console.clear();
        this.displayWelcome();
        break;

      case '/files':
        this.showFiles();
        break;

      case '/refs':
        this.showReferences();
        break;

      case '/add':
        if (args[0]) {
          await this.addFile(args[0]);
        } else {
          this.responseRenderer.displayWarning('Usage: /add <file_path>');
        }
        break;

      case '/url':
        if (args[0]) {
          await this.addURL(args[0]);
        } else {
          this.responseRenderer.displayWarning('Usage: /url <url>');
        }
        break;

      case '/clearrefs':
        this.referenceManager.clearReferences();
        this.fileDropHandler.clearFiles();
        break;

      default:
        this.responseRenderer.displayWarning(`Unknown command: ${cmd}. Type /help for available commands.`);
    }
  }

  /**
   * Add file to the system
   */
  async addFile(filePath: string): Promise<boolean> {
    const file = await this.fileDropHandler.addFile(filePath);
    if (!file) return false;

    // Process OCR if it's an image
    let ocrResult: OCRResult | undefined;
    if (file.isImage && this.config.enableOCR) {
      ocrResult = await this.ocrProcessor.processImage(file);
    }

    // Add to reference manager
    this.referenceManager.addFileReference(file, ocrResult);
    
    return true;
  }

  /**
   * Add URL to the system
   */
  async addURL(url: string): Promise<boolean> {
    const reference = await this.referenceManager.addUrlReference(url);
    return reference !== null;
  }

  /**
   * Process pending OCR tasks
   */
  private async processOCRTasks(): Promise<void> {
    if (!this.config.enableOCR) return;

    const images = this.fileDropHandler.getImagesForProcessing();
    if (images.length === 0) return;

    for (const image of images) {
      const reference = this.referenceManager.getReference(`ref_${image.id}`);
      if (reference && !reference.metadata.ocrResult) {
        const ocrResult = await this.ocrProcessor.processImage(image);
        if (ocrResult) {
          reference.metadata.ocrResult = ocrResult;
        }
      }
    }
  }

  /**
   * Show attached files summary
   */
  private showAttachedFilesSummary(): void {
    const summary = this.referenceManager.getSummary();
    if (summary !== 'No references attached') {
      this.inputRenderer.showDropIndicator(this.referenceManager.getAllReferences().length);
    }
  }

  /**
   * Show help information
   */
  private showHelp(): void {
    this.responseRenderer.displayInfo('Enhanced CLI Commands', 
      '/help - Show this help\n' +
      '/exit - Exit the interface\n' +
      '/clear - Clear screen\n' +
      '/files - Show attached files\n' +
      '/refs - Show references\n' +
      '/add <path> - Add file\n' +
      '/url <url> - Add URL reference\n' +
      '/clearrefs - Clear all references'
    );
  }

  /**
   * Show attached files
   */
  private showFiles(): void {
    const files = this.fileDropHandler.getDroppedFiles();
    if (files.length === 0) {
      this.responseRenderer.displayInfo('No files attached');
      return;
    }

    const fileInfo = files.map(file => ({
      name: file.name,
      status: 'completed',
      details: `${file.type} - ${this.formatFileSize(file.size)}`,
    }));

    this.responseRenderer.displayReferenceStatus(fileInfo);
  }

  /**
   * Show references
   */
  private showReferences(): void {
    const stats = this.referenceManager.getStatistics();
    this.responseRenderer.displaySuccess(
      `References: ${stats.total} total`,
      Object.entries(stats.byType)
        .map(([type, count]) => `${type}: ${count}`)
        .join(', ')
    );
  }

  /**
   * Check if input is a URL
   */
  private isURL(input: string): boolean {
    try {
      new URL(input);
      return true;
    } catch {
      return false;
    }
  }

  /**
   * Format file size
   */
  private formatFileSize(bytes: number): string {
    const units = ['B', 'KB', 'MB', 'GB'];
    let size = bytes;
    let unitIndex = 0;
    
    while (size >= 1024 && unitIndex < units.length - 1) {
      size /= 1024;
      unitIndex++;
    }
    
    return `${size.toFixed(1)}${units[unitIndex]}`;
  }

  /**
   * Redraw interface after resize
   */
  private redrawInterface(): void {
    console.clear();
    this.displayWelcome();
  }

  /**
   * Prompt for input (used after interruptions)
   */
  private promptForInput(): void {
    if (this.rl && this.running) {
      this.rl.prompt();
    }
  }

  /**
   * Clean up resources
   */
  private async cleanup(): Promise<void> {
    this.rl?.close();
    
    if (this.ocrProcessor.isReady()) {
      await this.ocrProcessor.cleanup();
    }
    
    await this.maria.close();
    
    this.responseRenderer.displaySuccess('Enhanced CLI interface closed');
  }
}