/**
 * Reference Manager - Manages all reference materials (files, images, URLs)
 */
import chalk from 'chalk';
import { DroppedFile } from './FileDropHandler';
import { OCRResult } from './OCRProcessor';

export interface Reference {
  id: string;
  type: 'file' | 'image' | 'url' | 'text';
  source: string;
  content: string;
  metadata: ReferenceMetadata;
  timestamp: Date;
  processed: boolean;
}

export interface ReferenceMetadata {
  title?: string;
  summary?: string;
  fileSize?: number;
  mimeType?: string;
  ocrResult?: OCRResult;
  urlInfo?: UrlInfo;
  tags?: string[];
  confidence?: number;
}

export interface UrlInfo {
  title: string;
  description?: string;
  domain: string;
  isAccessible: boolean;
  statusCode?: number;
}

export class ReferenceManager {
  private references: Map<string, Reference> = new Map();
  private contextCache: string | null = null;
  private cacheTimestamp: number = 0;
  private readonly CACHE_TTL = 5 * 60 * 1000; // 5 minutes

  /**
   * Add file reference
   */
  addFileReference(file: DroppedFile, ocrResult?: OCRResult): Reference {
    const reference: Reference = {
      id: `ref_${file.id}`,
      type: file.isImage ? 'image' : 'file',
      source: file.path,
      content: file.content || '',
      metadata: {
        title: file.name,
        summary: this.generateFileSummary(file),
        fileSize: file.size,
        mimeType: file.mimeType,
        ocrResult,
        tags: this.generateFileTags(file),
      },
      timestamp: new Date(),
      processed: true,
    };

    this.references.set(reference.id, reference);
    this.invalidateCache();

    console.log(chalk.green(`📎 Added reference: ${file.name}`));
    return reference;
  }

  /**
   * Add URL reference
   */
  async addUrlReference(url: string): Promise<Reference | null> {
    try {
      const urlInfo = await this.fetchUrlInfo(url);
      
      const reference: Reference = {
        id: `ref_url_${Date.now()}`,
        type: 'url',
        source: url,
        content: urlInfo.description || '',
        metadata: {
          title: urlInfo.title,
          summary: `Web resource: ${urlInfo.domain}`,
          urlInfo,
          tags: ['web', 'url'],
        },
        timestamp: new Date(),
        processed: urlInfo.isAccessible,
      };

      this.references.set(reference.id, reference);
      this.invalidateCache();

      console.log(chalk.green(`🔗 Added URL reference: ${urlInfo.title || url}`));
      return reference;

    } catch (error) {
      console.log(chalk.red(`❌ Failed to add URL reference: ${error instanceof Error ? error.message : 'Unknown error'}`));
      return null;
    }
  }

  /**
   * Add text reference
   */
  addTextReference(text: string, title?: string): Reference {
    const reference: Reference = {
      id: `ref_text_${Date.now()}`,
      type: 'text',
      source: 'user_input',
      content: text,
      metadata: {
        title: title || 'User Text',
        summary: `Text snippet (${text.length} characters)`,
        tags: ['text', 'user_input'],
      },
      timestamp: new Date(),
      processed: true,
    };

    this.references.set(reference.id, reference);
    this.invalidateCache();

    console.log(chalk.green(`📝 Added text reference: ${reference.metadata.title}`));
    return reference;
  }

  /**
   * Get all references
   */
  getAllReferences(): Reference[] {
    return Array.from(this.references.values());
  }

  /**
   * Get references by type
   */
  getReferencesByType(type: Reference['type']): Reference[] {
    return this.getAllReferences().filter(ref => ref.type === type);
  }

  /**
   * Get reference by ID
   */
  getReference(id: string): Reference | undefined {
    return this.references.get(id);
  }

  /**
   * Remove reference by ID
   */
  removeReference(id: string): boolean {
    const removed = this.references.delete(id);
    if (removed) {
      this.invalidateCache();
      console.log(chalk.yellow(`🗑️ Removed reference: ${id}`));
    }
    return removed;
  }

  /**
   * Clear all references
   */
  clearReferences(): void {
    const count = this.references.size;
    this.references.clear();
    this.invalidateCache();
    console.log(chalk.yellow(`🗑️ Cleared ${count} references`));
  }

  /**
   * Generate context string for AI processing
   */
  generateContext(): string {
    // Use cache if available and not expired
    const now = Date.now();
    if (this.contextCache && (now - this.cacheTimestamp) < this.CACHE_TTL) {
      return this.contextCache;
    }

    const references = this.getAllReferences();
    if (references.length === 0) {
      this.contextCache = '';
      this.cacheTimestamp = now;
      return '';
    }

    let context = '\n\n🔍 REFERENCE MATERIALS:\n';
    context += '═'.repeat(50) + '\n';

    for (const ref of references.sort((a, b) => b.timestamp.getTime() - a.timestamp.getTime())) {
      context += this.formatReferenceForContext(ref);
    }

    context += '═'.repeat(50) + '\n';
    context += `Total References: ${references.length} | Generated: ${new Date().toLocaleTimeString()}\n\n`;

    this.contextCache = context;
    this.cacheTimestamp = now;
    return context;
  }

  /**
   * Format single reference for context
   */
  private formatReferenceForContext(ref: Reference): string {
    let formatted = `\n📎 ${ref.metadata.title || 'Untitled'}\n`;
    formatted += `   Type: ${ref.type.toUpperCase()} | Source: ${this.shortenSource(ref.source)}\n`;
    
    if (ref.metadata.summary) {
      formatted += `   Summary: ${ref.metadata.summary}\n`;
    }

    // Add OCR content for images
    if (ref.metadata.ocrResult && ref.metadata.ocrResult.text) {
      formatted += `   Extracted Text: ${ref.metadata.ocrResult.text.substring(0, 200)}${ref.metadata.ocrResult.text.length > 200 ? '...' : ''}\n`;
      formatted += `   OCR Confidence: ${ref.metadata.ocrResult.confidence.toFixed(1)}%\n`;
    }

    // Add file content
    if (ref.content && ref.type !== 'image') {
      const contentPreview = ref.content.substring(0, 300);
      formatted += `   Content: ${contentPreview}${ref.content.length > 300 ? '...' : ''}\n`;
    }

    // Add URL info
    if (ref.metadata.urlInfo) {
      formatted += `   Domain: ${ref.metadata.urlInfo.domain}\n`;
      if (ref.metadata.urlInfo.description) {
        formatted += `   Description: ${ref.metadata.urlInfo.description}\n`;
      }
    }

    // Add tags
    if (ref.metadata.tags && ref.metadata.tags.length > 0) {
      formatted += `   Tags: ${ref.metadata.tags.join(', ')}\n`;
    }

    formatted += '   ' + '-'.repeat(40) + '\n';
    return formatted;
  }

  /**
   * Get summary for display
   */
  getSummary(): string {
    const references = this.getAllReferences();
    if (references.length === 0) {
      return 'No references attached';
    }

    const counts = references.reduce((acc, ref) => {
      acc[ref.type] = (acc[ref.type] || 0) + 1;
      return acc;
    }, {} as Record<string, number>);

    const parts = Object.entries(counts).map(([type, count]) => {
      const icon = this.getTypeIcon(type as Reference['type']);
      return `${icon} ${count} ${type}${count !== 1 ? 's' : ''}`;
    });

    return `📎 ${parts.join(', ')}`;
  }

  /**
   * Search references
   */
  searchReferences(query: string): Reference[] {
    const lowerQuery = query.toLowerCase();
    
    return this.getAllReferences().filter(ref => {
      const title = ref.metadata.title?.toLowerCase() || '';
      const summary = ref.metadata.summary?.toLowerCase() || '';
      const content = ref.content.toLowerCase();
      const tags = ref.metadata.tags?.join(' ').toLowerCase() || '';
      
      return title.includes(lowerQuery) ||
             summary.includes(lowerQuery) ||
             content.includes(lowerQuery) ||
             tags.includes(lowerQuery);
    });
  }

  /**
   * Get statistics
   */
  getStatistics(): {
    total: number;
    byType: Record<string, number>;
    totalSize: number;
    processedCount: number;
    recentCount: number;
  } {
    const references = this.getAllReferences();
    const now = Date.now();
    const oneHourAgo = now - (60 * 60 * 1000);

    return {
      total: references.length,
      byType: references.reduce((acc, ref) => {
        acc[ref.type] = (acc[ref.type] || 0) + 1;
        return acc;
      }, {} as Record<string, number>),
      totalSize: references.reduce((sum, ref) => sum + (ref.metadata.fileSize || 0), 0),
      processedCount: references.filter(ref => ref.processed).length,
      recentCount: references.filter(ref => ref.timestamp.getTime() > oneHourAgo).length,
    };
  }

  /**
   * Helper methods
   */
  private generateFileSummary(file: DroppedFile): string {
    if (file.isImage) {
      return `Image file (${this.formatFileSize(file.size)}) - OCR analysis available`;
    } else if (file.isText) {
      const wordCount = file.content?.split(/\s+/).length || 0;
      return `Text file with ${wordCount} words (${this.formatFileSize(file.size)})`;
    } else {
      return `${file.type.toUpperCase()} file (${this.formatFileSize(file.size)})`;
    }
  }

  private generateFileTags(file: DroppedFile): string[] {
    const tags = [file.type.replace('.', '')];
    
    if (file.isImage) tags.push('image', 'visual');
    if (file.isText) tags.push('text', 'document');
    if (file.size > 1024 * 1024) tags.push('large');
    
    return tags;
  }

  private formatFileSize(bytes: number): string {
    const units = ['B', 'KB', 'MB', 'GB'];
    let size = bytes;
    let unitIndex = 0;
    
    while (size >= 1024 && unitIndex < units.length - 1) {
      size /= 1024;
      unitIndex++;
    }
    
    return `${size.toFixed(1)}${units[unitIndex]}`;
  }

  private shortenSource(source: string): string {
    if (source.length <= 40) return source;
    if (source.startsWith('http')) {
      try {
        const url = new URL(source);
        return `${url.hostname}${url.pathname}`;
      } catch {
        return source.substring(0, 40) + '...';
      }
    }
    return source.substring(0, 40) + '...';
  }

  private getTypeIcon(type: Reference['type']): string {
    switch (type) {
      case 'image': return '🖼️';
      case 'file': return '📄';
      case 'url': return '🔗';
      case 'text': return '📝';
      default: return '📎';
    }
  }

  private async fetchUrlInfo(url: string): Promise<UrlInfo> {
    // Simplified URL info fetching - in a real implementation, this would fetch the actual page
    try {
      const urlObj = new URL(url);
      return {
        title: `Resource from ${urlObj.hostname}`,
        description: `Web content from ${url}`,
        domain: urlObj.hostname,
        isAccessible: true,
        statusCode: 200,
      };
    } catch (error) {
      return {
        title: 'Invalid URL',
        domain: 'unknown',
        isAccessible: false,
      };
    }
  }

  private invalidateCache(): void {
    this.contextCache = null;
    this.cacheTimestamp = 0;
  }
}