/**
 * OCRProcessor Component
 * Handles OCR processing for images using tesseract.js
 */

import Tesseract from 'tesseract.js';
import * as fs from 'fs';
import * as path from 'path';
import chalk from 'chalk';
import { EventEmitter } from 'events';

/**
 * OCR processing result
 */
export interface OCRResult {
  text: string;
  confidence: number;
  language: string;
  imagePath: string;
  processedAt: Date;
  error?: string;
}

/**
 * OCR processor configuration
 */
export interface OCRProcessorConfig {
  languages?: string[];
  cacheDir?: string;
  enableCache?: boolean;
  minConfidence?: number;
}

/**
 * OCR processor class
 */
export class OCRProcessor extends EventEmitter {
  private config: Required<OCRProcessorConfig>;
  private processing: Map<string, Promise<OCRResult>> = new Map();
  private cache: Map<string, OCRResult> = new Map();
  
  constructor(config: OCRProcessorConfig = {}) {
    super();
    this.config = {
      languages: config.languages || ['eng'],
      cacheDir: config.cacheDir || path.join(process.cwd(), '.maria-ocr-cache'),
      enableCache: config.enableCache ?? true,
      minConfidence: config.minConfidence || 60,
    };
    
    // Load cache if enabled
    if (this.config.enableCache) {
      this.loadCache();
    }
  }

  /**
   * Process image for OCR
   */
  async processImage(imagePath: string): Promise<OCRResult> {
    // Check if already processing
    if (this.processing.has(imagePath)) {
      return this.processing.get(imagePath)!;
    }
    
    // Check cache
    if (this.config.enableCache && this.cache.has(imagePath)) {
      const cached = this.cache.get(imagePath)!;
      this.emit('cache-hit', { imagePath, result: cached });
      return cached;
    }
    
    // Start processing
    const processingPromise = this.performOCR(imagePath);
    this.processing.set(imagePath, processingPromise);
    
    try {
      const result = await processingPromise;
      
      // Cache result
      if (this.config.enableCache) {
        this.cache.set(imagePath, result);
        this.saveCache();
      }
      
      return result;
    } finally {
      this.processing.delete(imagePath);
    }
  }

  /**
   * Perform actual OCR processing
   */
  private async performOCR(imagePath: string): Promise<OCRResult> {
    try {
      // Verify file exists
      if (!fs.existsSync(imagePath)) {
        throw new Error(`Image file not found: ${imagePath}`);
      }
      
      // Emit processing start
      this.emit('processing-start', { imagePath });
      
      // Create worker
      const worker = await Tesseract.createWorker({
        logger: (m) => {
          if (m.status === 'recognizing text') {
            const progress = Math.round((m.progress || 0) * 100);
            this.emit('progress', { imagePath, progress });
          }
        },
      });
      
      // Load language data
      await worker.loadLanguage(this.config.languages.join('+'));
      await worker.initialize(this.config.languages.join('+'));
      
      // Perform OCR
      const { data } = await worker.recognize(imagePath);
      
      // Terminate worker
      await worker.terminate();
      
      // Create result
      const result: OCRResult = {
        text: data.text,
        confidence: data.confidence,
        language: this.config.languages[0],
        imagePath,
        processedAt: new Date(),
      };
      
      // Check confidence
      if (result.confidence < this.config.minConfidence) {
        result.error = `Low confidence: ${result.confidence}% (minimum: ${this.config.minConfidence}%)`;
      }
      
      // Emit completion
      this.emit('processing-complete', { imagePath, result });
      
      return result;
    } catch (error) {
      const errorMessage = error instanceof Error ? error.message : 'Unknown error';
      const result: OCRResult = {
        text: '',
        confidence: 0,
        language: this.config.languages[0],
        imagePath,
        processedAt: new Date(),
        error: errorMessage,
      };
      
      this.emit('processing-error', { imagePath, error: errorMessage });
      return result;
    }
  }

  /**
   * Process multiple images in parallel
   */
  async processImages(imagePaths: string[]): Promise<OCRResult[]> {
    const promises = imagePaths.map(path => this.processImage(path));
    return Promise.all(promises);
  }

  /**
   * Extract text from image with progress display
   */
  async extractTextWithProgress(imagePath: string): Promise<string> {
    console.log(chalk.cyan(`\n🔍 Processing image: ${path.basename(imagePath)}`));
    
    let lastProgress = 0;
    const progressHandler = ({ progress }: { progress: number }) => {
      if (progress > lastProgress + 10) {
        process.stdout.write(chalk.gray(`\r  Progress: ${progress}%`));
        lastProgress = progress;
      }
    };
    
    this.on('progress', progressHandler);
    
    try {
      const result = await this.processImage(imagePath);
      
      process.stdout.write('\r' + ' '.repeat(20) + '\r'); // Clear progress line
      
      if (result.error) {
        console.log(chalk.red(`  ✗ OCR failed: ${result.error}`));
        return '';
      }
      
      console.log(chalk.green(`  ✓ Text extracted (confidence: ${result.confidence.toFixed(1)}%)`));
      
      if (result.text.trim()) {
        console.log(chalk.gray('  Preview: ' + result.text.substring(0, 100) + '...'));
      } else {
        console.log(chalk.yellow('  ⚠️ No text found in image'));
      }
      
      return result.text;
    } finally {
      this.off('progress', progressHandler);
    }
  }

  /**
   * Clear OCR cache
   */
  clearCache(): void {
    this.cache.clear();
    if (this.config.enableCache) {
      this.saveCache();
    }
  }

  /**
   * Get cache statistics
   */
  getCacheStats(): { size: number; hits: number; misses: number } {
    return {
      size: this.cache.size,
      hits: 0, // Would need to track this
      misses: 0, // Would need to track this
    };
  }

  /**
   * Load cache from disk
   */
  private loadCache(): void {
    try {
      const cacheFile = path.join(this.config.cacheDir, 'ocr-cache.json');
      if (fs.existsSync(cacheFile)) {
        const data = JSON.parse(fs.readFileSync(cacheFile, 'utf-8'));
        
        // Convert back to Map with Date objects
        for (const [key, value] of Object.entries(data)) {
          const result = value as OCRResult;
          result.processedAt = new Date(result.processedAt);
          this.cache.set(key, result);
        }
      }
    } catch (error) {
      // Silently fail cache loading
    }
  }

  /**
   * Save cache to disk
   */
  private saveCache(): void {
    try {
      const cacheFile = path.join(this.config.cacheDir, 'ocr-cache.json');
      
      // Create cache directory if needed
      fs.mkdirSync(this.config.cacheDir, { recursive: true });
      
      // Convert Map to object for JSON
      const cacheData: Record<string, OCRResult> = {};
      for (const [key, value] of this.cache.entries()) {
        cacheData[key] = value;
      }
      
      fs.writeFileSync(cacheFile, JSON.stringify(cacheData, null, 2), 'utf-8');
    } catch (error) {
      // Silently fail cache saving
    }
  }

  /**
   * Check if image format is supported
   */
  static isSupportedImage(filePath: string): boolean {
    const ext = path.extname(filePath).toLowerCase();
    const supportedFormats = ['.png', '.jpg', '.jpeg', '.gif', '.bmp', '.pbm', '.webp'];
    return supportedFormats.includes(ext);
  }

  /**
   * Get supported languages
   */
  static getSupportedLanguages(): string[] {
    return [
      'eng', // English
      'jpn', // Japanese
      'chi_sim', // Simplified Chinese
      'chi_tra', // Traditional Chinese
      'kor', // Korean
      'spa', // Spanish
      'fra', // French
      'deu', // German
      'rus', // Russian
      'ara', // Arabic
    ];
  }
}

export default OCRProcessor;