/**
 * VisionAnalyzer Component
 * Analyzes images using cloud vision models (Gemini, GPT-4V) with OCR fallback
 */

import * as fs from 'fs';
import * as path from 'path';
import chalk from 'chalk';
import { EventEmitter } from 'events';
import { OCRProcessor } from './OCRProcessor.js';

/**
 * Vision analysis result
 */
export interface VisionAnalysisResult {
  provider: 'gemini' | 'openai' | 'ocr' | 'none';
  text?: string;
  description?: string;
  objects?: string[];
  labels?: string[];
  confidence?: number;
  error?: string;
  processedAt: Date;
}

/**
 * Vision provider configuration
 */
export interface VisionProviderConfig {
  provider: 'gemini' | 'openai';
  apiKey: string;
  model?: string;
  maxTokens?: number;
}

/**
 * Vision analyzer configuration
 */
export interface VisionAnalyzerConfig {
  preferredProvider?: 'gemini' | 'openai' | 'auto';
  fallbackToOCR?: boolean;
  geminiConfig?: Partial<VisionProviderConfig>;
  openaiConfig?: Partial<VisionProviderConfig>;
  enableCache?: boolean;
}

/**
 * Vision analyzer class
 */
export class VisionAnalyzer extends EventEmitter {
  private config: Required<VisionAnalyzerConfig>;
  private ocrProcessor: OCRProcessor;
  private cache: Map<string, VisionAnalysisResult> = new Map();
  private geminiAvailable: boolean = false;
  private openaiAvailable: boolean = false;
  private networkAvailable: boolean = true;
  private lastNetworkCheck: number = 0;
  private networkCheckInterval: number = 30000; // 30 seconds
  
  constructor(config: VisionAnalyzerConfig = {}) {
    super();
    
    this.config = {
      preferredProvider: config.preferredProvider || 'auto',
      fallbackToOCR: config.fallbackToOCR ?? true,
      geminiConfig: config.geminiConfig || {},
      openaiConfig: config.openaiConfig || {},
      enableCache: config.enableCache ?? true,
    };
    
    // Initialize OCR processor as fallback
    this.ocrProcessor = new OCRProcessor({
      enableCache: true,
      minConfidence: 60,
    });
    
    // Check API availability
    this.checkProviderAvailability();
    
    // Initial network check
    this.checkNetworkConnectivity();
  }

  /**
   * Check which vision providers are available
   */
  private checkProviderAvailability(): void {
    // Check for Gemini API key
    if (process.env['GOOGLE_API_KEY'] || this.config.geminiConfig?.apiKey) {
      this.geminiAvailable = true;
      console.log(chalk.green('✓ Gemini 2.0 Flash vision available'));
    }
    
    // Check for OpenAI API key
    if (process.env['OPENAI_API_KEY'] || this.config.openaiConfig?.apiKey) {
      this.openaiAvailable = true;
      console.log(chalk.green('✓ GPT-4 Vision available'));
    }
    
    if (!this.geminiAvailable && !this.openaiAvailable) {
      console.log(chalk.yellow('⚠️ No cloud vision APIs available, using local OCR'));
    }
  }

  /**
   * Check network connectivity
   */
  private async checkNetworkConnectivity(): Promise<boolean> {
    const now = Date.now();
    
    // Don't check too frequently
    if (now - this.lastNetworkCheck < this.networkCheckInterval) {
      return this.networkAvailable;
    }
    
    this.lastNetworkCheck = now;
    
    try {
      // Simple connectivity test
      const controller = new AbortController();
      const timeout = setTimeout(() => controller.abort(), 5000); // 5 second timeout
      
      await fetch('https://www.google.com/generate_204', { 
        method: 'HEAD',
        signal: controller.signal 
      });
      
      clearTimeout(timeout);
      this.networkAvailable = true;
      return true;
    } catch (error) {
      this.networkAvailable = false;
      console.log(chalk.yellow('⚠️ Network connectivity issue, using local OCR'));
      return false;
    }
  }

  /**
   * Check if cloud vision is available (has API keys and network)
   */
  private async isCloudVisionAvailable(): Promise<boolean> {
    if (!this.geminiAvailable && !this.openaiAvailable) {
      return false;
    }
    
    const networkOk = await this.checkNetworkConnectivity();
    return networkOk;
  }

  /**
   * Analyze image using best available method
   */
  async analyzeImage(imagePath: string, prompt?: string): Promise<VisionAnalysisResult> {
    // Check cache
    if (this.config.enableCache && this.cache.has(imagePath)) {
      const cached = this.cache.get(imagePath)!;
      this.emit('cache-hit', { imagePath, result: cached });
      return cached;
    }
    
    // Verify file exists
    if (!fs.existsSync(imagePath)) {
      return {
        provider: 'none',
        error: `Image file not found: ${imagePath}`,
        processedAt: new Date(),
      };
    }
    
    let result: VisionAnalysisResult | null = null;
    
    // Check if cloud vision is available (network + API keys)
    const cloudAvailable = await this.isCloudVisionAvailable();
    
    // Try cloud vision models only if network is available
    if (cloudAvailable) {
      if (this.config.preferredProvider === 'gemini' && this.geminiAvailable) {
        result = await this.analyzeWithGemini(imagePath, prompt);
      } else if (this.config.preferredProvider === 'openai' && this.openaiAvailable) {
        result = await this.analyzeWithOpenAI(imagePath, prompt);
      } else if (this.config.preferredProvider === 'auto') {
        // Try Gemini first (faster and cheaper)
        if (this.geminiAvailable) {
          result = await this.analyzeWithGemini(imagePath, prompt);
        }
        // Fallback to OpenAI if Gemini fails
        if (!result && this.openaiAvailable) {
          result = await this.analyzeWithOpenAI(imagePath, prompt);
        }
      }
    } else {
      console.log(chalk.cyan('🌐 Cloud vision unavailable, using local OCR'));
    }
    
    // Fallback to OCR if cloud vision fails or unavailable
    if (!result && this.config.fallbackToOCR) {
      result = await this.analyzeWithOCR(imagePath);
    }
    
    // If still no result, return error
    if (!result) {
      result = {
        provider: 'none',
        error: 'No vision analysis method available',
        processedAt: new Date(),
      };
    }
    
    // Cache result
    if (this.config.enableCache && !result.error) {
      this.cache.set(imagePath, result);
    }
    
    return result;
  }

  /**
   * Analyze image with Gemini 2.0 Flash
   */
  private async analyzeWithGemini(imagePath: string, prompt?: string): Promise<VisionAnalysisResult | null> {
    try {
      console.log(chalk.cyan('🔮 Analyzing with Gemini 2.0 Flash...'));
      this.emit('analysis-start', { provider: 'gemini', imagePath });
      
      // Dynamic import for Google AI SDK
      const { GoogleGenerativeAI } = await import('@google/generative-ai');
      
      const apiKey = this.config.geminiConfig?.apiKey || process.env['GOOGLE_API_KEY'];
      if (!apiKey) {
        throw new Error('Gemini API key not found');
      }
      
      const genAI = new GoogleGenerativeAI(apiKey);
      const model = genAI.getGenerativeModel({ 
        model: this.config.geminiConfig?.model || 'gemini-2.0-flash-exp'
      });
      
      // Read image and convert to base64
      const imageBuffer = fs.readFileSync(imagePath);
      const base64Image = imageBuffer.toString('base64');
      
      // Determine MIME type
      const ext = path.extname(imagePath).toLowerCase();
      const mimeType = this.getMimeType(ext);
      
      // Create prompt for vision analysis
      const analysisPrompt = prompt || `Analyze this image and provide:
1. Extracted text (if any)
2. Description of what you see
3. Key objects or elements
4. Any important details or context

Be thorough but concise.`;
      
      // Generate content with image
      const result = await model.generateContent([
        analysisPrompt,
        {
          inlineData: {
            mimeType,
            data: base64Image,
          },
        },
      ]);
      
      const response = await result.response;
      const text = response.text();
      
      // Parse response for structured data
      const lines = text.split('\n');
      const extractedText = this.extractSection(lines, 'text', 'extracted text');
      const description = this.extractSection(lines, 'description', 'see');
      const objects = this.extractList(lines, 'objects', 'elements');
      
      const analysisResult: VisionAnalysisResult = {
        provider: 'gemini',
        text: extractedText || text,
        description: description || text,
        objects,
        confidence: 95, // Gemini typically has high confidence
        processedAt: new Date(),
      };
      
      this.emit('analysis-complete', { provider: 'gemini', imagePath, result: analysisResult });
      console.log(chalk.green('✓ Gemini analysis complete'));
      
      return analysisResult;
    } catch (error) {
      const errorMessage = error instanceof Error ? error.message : 'Unknown error';
      
      // Check if it's a network-related error
      if (this.isNetworkError(error)) {
        console.log(chalk.yellow('⚠️ Network error detected, switching to local OCR'));
        this.networkAvailable = false;
      } else {
        console.log(chalk.yellow(`⚠️ Gemini analysis failed: ${errorMessage}`));
      }
      
      this.emit('analysis-error', { provider: 'gemini', imagePath, error });
      return null;
    }
  }

  /**
   * Analyze image with GPT-4 Vision
   */
  private async analyzeWithOpenAI(imagePath: string, prompt?: string): Promise<VisionAnalysisResult | null> {
    try {
      console.log(chalk.cyan('🤖 Analyzing with GPT-4 Vision...'));
      this.emit('analysis-start', { provider: 'openai', imagePath });
      
      // Dynamic import for OpenAI SDK
      const { default: OpenAI } = await import('openai');
      
      const apiKey = this.config.openaiConfig?.apiKey || process.env['OPENAI_API_KEY'];
      if (!apiKey) {
        throw new Error('OpenAI API key not found');
      }
      
      const openai = new OpenAI({ apiKey });
      
      // Read image and convert to base64
      const imageBuffer = fs.readFileSync(imagePath);
      const base64Image = imageBuffer.toString('base64');
      
      // Create prompt for vision analysis
      const analysisPrompt = prompt || `Analyze this image and provide:
1. Extracted text (if any)
2. Description of what you see
3. Key objects or elements
4. Any important details or context

Be thorough but concise.`;
      
      // Call GPT-4o-mini Vision
      const response = await openai.chat.completions.create({
        model: this.config.openaiConfig?.model || 'gpt-4o-mini',
        messages: [
          {
            role: 'user',
            content: [
              { type: 'text', text: analysisPrompt },
              {
                type: 'image_url',
                image_url: {
                  url: `data:image/jpeg;base64,${base64Image}`,
                },
              },
            ],
          },
        ],
        max_tokens: this.config.openaiConfig?.maxTokens || 1000,
      });
      
      const text = response.choices[0]?.message?.content || '';
      
      // Parse response for structured data
      const lines = text.split('\n');
      const extractedText = this.extractSection(lines, 'text', 'extracted text');
      const description = this.extractSection(lines, 'description', 'see');
      const objects = this.extractList(lines, 'objects', 'elements');
      
      const analysisResult: VisionAnalysisResult = {
        provider: 'openai',
        text: extractedText || text,
        description: description || text,
        objects,
        confidence: 90, // GPT-4V typically has good confidence
        processedAt: new Date(),
      };
      
      this.emit('analysis-complete', { provider: 'openai', imagePath, result: analysisResult });
      console.log(chalk.green('✓ GPT-4 Vision analysis complete'));
      
      return analysisResult;
    } catch (error) {
      const errorMessage = error instanceof Error ? error.message : 'Unknown error';
      
      // Check if it's a network-related error
      if (this.isNetworkError(error)) {
        console.log(chalk.yellow('⚠️ Network error detected, switching to local OCR'));
        this.networkAvailable = false;
      } else {
        console.log(chalk.yellow(`⚠️ OpenAI analysis failed: ${errorMessage}`));
      }
      
      this.emit('analysis-error', { provider: 'openai', imagePath, error });
      return null;
    }
  }

  /**
   * Analyze image with local OCR
   */
  private async analyzeWithOCR(imagePath: string): Promise<VisionAnalysisResult> {
    console.log(chalk.cyan('📝 Falling back to local OCR...'));
    
    try {
      const ocrResult = await this.ocrProcessor.processImage(imagePath);
      
      return {
        provider: 'ocr',
        text: ocrResult.text,
        description: ocrResult.text ? `Text document containing: ${ocrResult.text.substring(0, 100)}...` : 'No text detected',
        confidence: ocrResult.confidence,
        error: ocrResult.error,
        processedAt: new Date(),
      };
    } catch (error) {
      return {
        provider: 'ocr',
        error: error instanceof Error ? error.message : 'OCR processing failed',
        processedAt: new Date(),
      };
    }
  }

  /**
   * Extract section from parsed lines
   */
  private extractSection(lines: string[], ...keywords: string[]): string | undefined {
    for (const line of lines) {
      const lowerLine = line.toLowerCase();
      for (const keyword of keywords) {
        if (lowerLine.includes(keyword)) {
          // Get content after colon or on next line
          const colonIndex = line.indexOf(':');
          if (colonIndex > -1) {
            return line.substring(colonIndex + 1).trim();
          }
          const lineIndex = lines.indexOf(line);
          if (lineIndex < lines.length - 1) {
            return lines[lineIndex + 1].trim();
          }
        }
      }
    }
    return undefined;
  }

  /**
   * Extract list items from parsed lines
   */
  private extractList(lines: string[], ...keywords: string[]): string[] {
    const items: string[] = [];
    let inSection = false;
    
    for (const line of lines) {
      const lowerLine = line.toLowerCase();
      
      // Check if we're entering the section
      for (const keyword of keywords) {
        if (lowerLine.includes(keyword)) {
          inSection = true;
          continue;
        }
      }
      
      // Extract list items
      if (inSection) {
        if (line.match(/^[-*•]\s+/)) {
          items.push(line.replace(/^[-*•]\s+/, '').trim());
        } else if (line.match(/^\d+\.\s+/)) {
          items.push(line.replace(/^\d+\.\s+/, '').trim());
        } else if (line.trim() === '' || line.match(/^\d+\.|^[A-Z]/)) {
          // End of list
          break;
        }
      }
    }
    
    return items;
  }

  /**
   * Get MIME type from file extension
   */
  private getMimeType(ext: string): string {
    const mimeTypes: Record<string, string> = {
      '.png': 'image/png',
      '.jpg': 'image/jpeg',
      '.jpeg': 'image/jpeg',
      '.gif': 'image/gif',
      '.bmp': 'image/bmp',
      '.webp': 'image/webp',
    };
    return mimeTypes[ext] || 'image/jpeg';
  }

  /**
   * Display analysis result
   */
  displayResult(result: VisionAnalysisResult, imagePath: string): void {
    const filename = path.basename(imagePath);
    
    console.log(chalk.cyan(`\n🖼️ Image Analysis: ${filename}`));
    console.log(`  Provider: ${chalk.yellow(result.provider.toUpperCase())}`);
    
    if (result.error) {
      console.log(chalk.red(`  Error: ${result.error}`));
      return;
    }
    
    if (result.text) {
      const preview = result.text.substring(0, 200);
      console.log(`  ${chalk.green('Text')}: ${preview}${result.text.length > 200 ? '...' : ''}`);
    }
    
    if (result.description && result.description !== result.text) {
      console.log(`  ${chalk.blue('Description')}: ${result.description.substring(0, 150)}...`);
    }
    
    if (result.objects && result.objects.length > 0) {
      console.log(`  ${chalk.magenta('Objects')}: ${result.objects.slice(0, 5).join(', ')}${result.objects.length > 5 ? '...' : ''}`);
    }
    
    if (result.confidence !== undefined) {
      console.log(`  ${chalk.gray('Confidence')}: ${result.confidence.toFixed(1)}%`);
    }
  }

  /**
   * Clear cache
   */
  clearCache(): void {
    this.cache.clear();
    this.ocrProcessor.clearCache();
  }

  /**
   * Check if error is network-related
   */
  private isNetworkError(error: any): boolean {
    if (!error) return false;
    
    const message = error.message?.toLowerCase() || '';
    const code = error.code?.toLowerCase() || '';
    
    // Common network error patterns
    const networkErrorPatterns = [
      'network',
      'connection',
      'timeout',
      'enotfound',
      'econnrefused',
      'econnreset',
      'ehostunreach',
      'offline',
      'fetch failed',
      'failed to fetch',
      'network error',
      'connection error',
      'request timeout',
      'service unavailable',
      'bad gateway',
      'gateway timeout',
    ];
    
    return networkErrorPatterns.some(pattern => 
      message.includes(pattern) || code.includes(pattern)
    );
  }

  /**
   * Get available providers
   */
  getAvailableProviders(): string[] {
    const providers: string[] = [];
    if (this.geminiAvailable && this.networkAvailable) providers.push('gemini');
    if (this.openaiAvailable && this.networkAvailable) providers.push('openai');
    if (this.config.fallbackToOCR) providers.push('ocr');
    return providers;
  }

  /**
   * Get current network status
   */
  isNetworkAvailable(): boolean {
    return this.networkAvailable;
  }

  /**
   * Force network recheck
   */
  async recheckNetwork(): Promise<boolean> {
    this.lastNetworkCheck = 0; // Reset timer
    return this.checkNetworkConnectivity();
  }
}

export default VisionAnalyzer;